fn anagram_key(word: String) -> String {
  return word
    |> split("")
    |> sort_by(|ch| ch)
    |> join("")
}

fn anagram_groups(words: List[String]) -> List[List[String]] {
  return words
    |> group_by(anagram_key)
    |> filter(|group| len(group.1) >= 2)
    |> map(|group| group.1)
}

