fn bracket_depth(s: String) -> Result[Int, String] {
  var stack = take([""], 0)
  var deepest = 0
  for (i, ch) in enumerate(split(s, "")) {
    if ch == "(" || ch == "[" || ch == "{" {
      stack = append(stack, ch)
      deepest = max(deepest, len(stack))
    } else {
      let expected = match ch {
        ")" => "(",
        "]" => "[",
        "}" => "{",
        _ => "",
      }
      if expected != "" {
        if last(stack) != Some(expected) {
          return Err("mismatch at " + to_string(i))
        }
        stack = take(stack, len(stack) - 1)
      }
    }
  }
  if len(stack) != 0 {
    return Err("unclosed at end")
  }
  return Ok(deepest)
}

