fn caesar_shift(s: String, k: Int) -> String {
  let alphabet = split("a b c d e f g h i j k l m n o p q r s t u v w x y z", " ")
  let offset = (k % 26 + 26) % 26
  var pairs = []
  for (i, letter) in enumerate(alphabet) {
    let target = (i + offset) % 26
    let shifted = alphabet
      |> drop(target)
      |> first()
      |> unwrap_or(letter)
    pairs = append(pairs, (letter, shifted))
  }
  let shifts = map_from(pairs)
  let chars = split(s, "")
  let shifted_chars = map(chars, |c| unwrap_or(map_get(shifts, c), c))
  return join(shifted_chars, "")
}

