fn next_roll(rolls: List[Int]) -> Result[Int, String] {
  return match first(rolls) {
    Some(pins) => Ok(pins),
    None => Err("incomplete game"),
  }
}

fn score_tenth(rolls: List[Int]) -> Result[Int, String] {
  let a = try next_roll(rolls)
  let b = try next_roll(drop(rolls, 1))
  let pair = a + b
  if a != 10 && pair > 10 {
    return Err("too many pins in frame 10")
  }
  if a == 10 || pair == 10 {
    let c = try next_roll(drop(rolls, 2))
    if a == 10 && b != 10 && b + c > 10 {
      return Err("too many pins in frame 10")
    }
    if len(rolls) > 3 {
      return Err("too many rolls")
    }
    return Ok(pair + c)
  }
  if len(rolls) > 2 {
    return Err("too many rolls")
  }
  return Ok(pair)
}

fn bowling_score(rolls: List[Int]) -> Result[Int, String] {
  for pins in rolls {
    if pins < 0 || pins > 10 {
      return Err("invalid roll")
    }
  }
  var remaining = rolls
  var total = 0
  for frame in range(1, 10) {
    let a = try next_roll(remaining)
    remaining = drop(remaining, 1)
    if a == 10 {
      total = total + 10 + sum(take(remaining, 2))
    } else {
      let b = try next_roll(remaining)
      remaining = drop(remaining, 1)
      let pair = a + b
      if pair > 10 {
        return Err("too many pins in frame " + to_string(frame))
      }
      total = total + pair
      if pair == 10 {
        total = total + sum(take(remaining, 1))
      }
    }
  }
  let tenth = try score_tenth(remaining)
  return Ok(total + tenth)
}

