type Person {
  name: String,
  age: Int,
}

fn endpoint_text(start: Int, offset: Int) -> String {
  let ones = start % 10 + offset % 10
  let prefix = start / 10 + offset / 10 + ones / 10
  if prefix == 0 {
    return to_string(ones)
  }
  return to_string(prefix) + to_string(ones % 10)
}

fn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {
  if width < 1 {
    return Err("bad width")
  }
  for person in people {
    if person.age < 0 {
      return Err("negative age: " + person.name)
    }
  }
  var counts = map_from([(0, 0)])
  var lowest = 0
  var highest = -1
  for person in people {
    let bucket = person.age / width
    if highest < 0 || bucket < lowest {
      lowest = bucket
    }
    highest = max(highest, bucket)
    let count = unwrap_or(map_get(counts, bucket), 0)
    counts = map_set(counts, bucket, count + 1)
  }
  var rows = []
  var bucket = lowest
  while bucket <= highest {
    let start = bucket * width
    let label = to_string(start) + "-" + endpoint_text(start, width - 1)
    let count = unwrap_or(map_get(counts, bucket), 0)
    rows = append(rows, (label, count))
    if bucket == highest {
      break
    }
    bucket = bucket + 1
  }
  return Ok(rows)
}

