fn strip_trailing_spaces(line: String) -> String {
  let parts = split(line, " ")
  var end = 0
  for (i, part) in enumerate(parts) {
    if part != "" {
      end = i + 1
    }
  }
  return join(take(parts, end), " ")
}

fn align_columns(rows: List[List[String]]) -> List[String] {
  var widths = map_from([(0, 0)])
  for row in rows {
    for (j, cell) in enumerate(row) {
      let width = unwrap_or(map_get(widths, j), 0)
      widths = map_set(widths, j, max(width, str_len(cell)))
    }
  }
  var lines = []
  for row in rows {
    var cells = []
    for (j, cell) in enumerate(row) {
      let width = unwrap_or(map_get(widths, j), 0)
      let padding = join(map(range(0, width - str_len(cell)), |_| " "), "")
      cells = append(cells, cell + padding)
    }
    let line = strip_trailing_spaces(join(cells, " | "))
    lines = append(lines, line)
  }
  return lines
}

