  score: Int,
}

fn competition_rank(players: List[Player]) -> List[(Int, String)] {
  let by_name = sort_by(players, |p| p.name)
  let ordered = sort_desc_by(by_name, |p| p.score)
  var ranked = []
  var rank = 1
  var previous_score = 0
  for (i, player) in enumerate(ordered) {
    if i == 0 || player.score != previous_score {
      rank = i + 1
      previous_score = player.score
    }
    ranked = append(ranked, (rank, player.name))
  }
  return ranked
}

