type Shift {
  worker: String,
  start_hour: Int,
  end_hour: Int,
}

fn coverage_gaps(shifts: List[Shift], required: Int) -> List[Int] {
  var gaps = take(range(0, 24), 0)
  for hour in range(0, 24) {
    let active = filter(shifts, |s| s.start_hour <= hour && hour < s.end_hour)
    let workers = group_by(active, |s| s.worker)
    if len(workers) < required {
      gaps = append(gaps, hour)
    }
  }
  return gaps
}

