type Job {
  name: String,
  deps: List[String],
}

fn deps_placed(deps: List[String], placed: Map[String, Bool]) -> Bool {
  for dep in deps {
    if map_get(placed, dep) != Some(true) {
      return false
    }
  }
  return true
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let initial = map_from(map(jobs, |job| (job.name, false)))
  var seen = initial
  for job in jobs {
    if map_get(seen, job.name) == Some(true) {
      return Err("duplicate job: " + job.name)
    }
    seen = map_set(seen, job.name, true)
  }
  for job in jobs {
    for dep in job.deps {
      if map_get(initial, dep) == None {
        return Err("unknown dependency: " + dep)
      }
    }
  }
  var placed = initial
  var order = take(keys(initial), 0)
  while len(order) < len(jobs) {
    let before = len(order)
    for job in jobs {
      if map_get(placed, job.name) == Some(false) && deps_placed(job.deps, placed) {
        placed = map_set(placed, job.name, true)
        order = append(order, job.name)
        break
      }
    }
    if len(order) == before {
      return Err("cycle detected")
    }
  }
  return Ok(order)
}

