fn edit_script_distance(a: String, b: String) -> Int {
  let a_chars = filter(split(a, ""), |ch| ch != "")
  let b_chars = filter(split(b, ""), |ch| ch != "")
  let width = len(b_chars)
  var above = map_from(map(range(0, width + 1), |j| (j, j)))
  var two_above = above
  var prev_a = ""
  for (i, a_char) in enumerate(a_chars) {
    var row = map_from([(0, i + 1)])
    var left = i + 1
    var prev_b = ""
    for (j, b_char) in enumerate(b_chars) {
      let deletion = unwrap_or(map_get(above, j + 1), 0) + 1
      let insertion = left + 1
      let diagonal = unwrap_or(map_get(above, j), 0)
      var replacement = diagonal
      if a_char != b_char {
        replacement = diagonal + 1
      }
      var best = min(min(deletion, insertion), replacement)
      if i > 0 && j > 0 && a_char == prev_b && prev_a == b_char {
        let swap = unwrap_or(map_get(two_above, j - 1), 0) + 1
        best = min(best, swap)
      }
      row = map_set(row, j + 1, best)
      left = best
      prev_b = b_char
    }
    two_above = above
    above = row
    prev_a = a_char
  }
  return unwrap_or(map_get(above, width), 0)
}

