fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {
  let floors = requests
    |> map(|floor| (floor, true))
    |> map_from()
    |> keys()
    |> sort_by(|floor| floor)
  let above = filter(floors, |floor| floor > start)
  let below = reverse(filter(floors, |floor| floor < start))
  let sweeps = match direction {
    "down" => (below, above),
    _ => (above, below),
  }
  var served = filter(floors, |floor| floor == start)
  for floor in sweeps.0 {
    served = append(served, floor)
  }
  for floor in sweeps.1 {
    served = append(served, floor)
  }
  return served
}

