fn find_all(s: String, pat: String) -> List[Int] {
  if pat == "" {
    return []
  }
  let needle = split(pat, "")
  let width = len(needle)
  var window = take(needle, 0)
  var positions = range(0, 0)
  for (i, ch) in enumerate(split(s, "")) {
    window = append(window, ch)
    if len(window) > width {
      window = drop(window, 1)
    }
    if window == needle {
      positions = append(positions, i - width + 1)
    }
  }
  return positions
}

