type BankOp =
  | Open(name: String)
  | Deposit(name: String, amount: Int)
  | Withdraw(name: String, amount: Int)
  | Transfer(src: String, dst: String, amount: Int)

fn empty_accounts() -> Map[String, Int] {
  return map_from([])
}

fn open_account(accts: Map[String, Int], name: String) -> Result[Map[String, Int], String] {
  return match map_get(accts, name) {
    Some(_) => Err("duplicate account " + name),
    None => Ok(map_set(accts, name, 0)),
  }
}

fn account_balance(accts: Map[String, Int], name: String) -> Result[Int, String] {
  return match map_get(accts, name) {
    Some(balance) => Ok(balance),
    None => Err("unknown account " + name),
  }
}

fn deposit(accts: Map[String, Int], name: String, n: Int) -> Result[Map[String, Int], String] {
  let balance = try account_balance(accts, name)
  if n <= 0 {
    return Err("invalid amount")
  }
  return Ok(map_set(accts, name, balance + n))
}

fn withdraw(accts: Map[String, Int], name: String, n: Int) -> Result[Map[String, Int], String] {
  let balance = try account_balance(accts, name)
  if n <= 0 {
    return Err("invalid amount")
  }
  if n > balance {
    return Err("insufficient funds")
  }
  return Ok(map_set(accts, name, balance - n))
}

fn move(a: Map[String, Int], src: String, dst: String, n: Int) -> Result[Map[String, Int], String] {
  let src_balance = try account_balance(a, src)
  let dst_balance = try account_balance(a, dst)
  if src == dst {
    return Err("same account")
  }
  if n <= 0 {
    return Err("invalid amount")
  }
  if n > src_balance {
    return Err("insufficient funds")
  }
  let debited = map_set(a, src, src_balance - n)
  return Ok(map_set(debited, dst, dst_balance + n))
}

fn apply_op(accts: Map[String, Int], op: BankOp, step: Int) -> Result[Map[String, Int], String] {
  let outcome = match op {
    Open(name) => open_account(accts, name),
    Deposit(name, amount) => deposit(accts, name, amount),
    Withdraw(name, amount) => withdraw(accts, name, amount),
    Transfer(src, dst, amount) => move(accts, src, dst, amount),
  }
  return match outcome {
    Ok(updated) => Ok(updated),
    Err(message) => Err("step " + to_string(step) + ": " + message),
  }
}

fn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {
  var accounts = empty_accounts()
  for (i, op) in enumerate(ops) {
    accounts = try apply_op(accounts, op, i + 1)
  }
  let entries = zip(keys(accounts), values(accounts))
  return Ok(entries)
}

