type Meeting {
  start: Int,
  end: Int,
}

fn free_slots(meetings: List[Meeting], day_start: Int, day_end: Int) -> List[(Int, Int)] {
  if day_end <= day_start {
    return []
  }
  let ordered = sort_by(meetings, |meeting| meeting.start)
  var slots = take([(day_start, day_end)], 0)
  var cursor = day_start
  for meeting in ordered {
    let start = max(meeting.start, day_start)
    let end = min(meeting.end, day_end)
    if start < end && end > cursor {
      if start > cursor {
        slots = append(slots, (cursor, start))
      }
      cursor = end
    }
  }
  if cursor < day_end {
    slots = append(slots, (cursor, day_end))
  }
  return slots
}

