fn heading_numbers(lines: List[String]) -> List[String] {
  var headings = []
  var level_one = 0
  var level_two = 0
  var level_three = 0
  for line in lines {
    let parts = split(line, " ")
    let marker = unwrap_or(first(parts), "")
    let title = join(drop(parts, 1), " ")
    if title != "" {
      if marker == "#" {
        level_one = level_one + 1
        level_two = 0
        level_three = 0
        headings = append(headings, to_string(level_one) + " " + title)
      } else if marker == "##" {
        level_two = level_two + 1
        level_three = 0
        let number = to_string(level_one) + "." + to_string(level_two)
        headings = append(headings, number + " " + title)
      } else if marker == "###" {
        level_three = level_three + 1
        let prefix = to_string(level_one) + "." + to_string(level_two)
        let number = prefix + "." + to_string(level_three)
        headings = append(headings, number + " " + title)
      }
    }
  }
  return headings
}

