type Stock {
  sku: String,
  qty: Int,
}

type Txn {
  sku: String,
  delta: Int,
}

fn inventory_ledger(stock: List[Stock], txns: List[Txn]) -> Result[List[Stock], String] {
  var quantities = map_from(map(stock, |s| (s.sku, s.qty)))
  for (i, txn) in enumerate(txns) {
    let prefix = "txn " + to_string(i + 1) + ": "
    let qty = unwrap_or(map_get(quantities, txn.sku), -1)
    if qty < 0 {
      return Err(prefix + "unknown sku " + txn.sku)
    }
    let updated = qty + txn.delta
    if updated < 0 {
      return Err(prefix + txn.sku + " would go negative")
    }
    quantities = map_set(quantities, txn.sku, updated)
  }
  var remaining = []
  for sku in keys(quantities) {
    let qty = unwrap_or(map_get(quantities, sku), 0)
    if qty > 0 {
      remaining = append(remaining, Stock { sku: sku, qty: qty })
    }
  }
  return Ok(sort_by(remaining, |s| s.sku))
}

