fn k_most_frequent(xs: List[Int], k: Int) -> List[(Int, Int)] {
  if k <= 0 {
    return []
  }
  let ranked = xs
    |> group_by(|x| x)
    |> map(|value, items| (value, len(items)))
    |> sort_by(|pair| pair.0)
    |> sort_desc_by(|pair| pair.1)
  return take(ranked, min(k, len(ranked)))
}

