type GlobToken =
  | Star
  | AnyChar
  | Literal(text: String)

fn glob_characters(text: String) -> List[String] {
  return filter(split(text, ""), |ch| ch != "")
}

fn glob_tokens(pattern: String) -> List[GlobToken] {
  var tokens = []
  var escaped = false
  for ch in glob_characters(pattern) {
    if escaped {
      tokens = append(tokens, Literal(ch))
      escaped = false
    } else if ch == "\\" {
      escaped = true
    } else if ch == "*" {
      tokens = append(tokens, Star)
    } else if ch == "?" {
      tokens = append(tokens, AnyChar)
    } else {
      tokens = append(tokens, Literal(ch))
    }
  }
  if escaped {
    tokens = append(tokens, Literal("\\"))
  }
  return tokens
}

fn glob_match(pattern: String, s: String) -> Bool {
  let chars = glob_characters(s)
  var row = [true]
  for ch in chars {
    row = append(row, false)
  }
  for token in glob_tokens(pattern) {
    var diagonal = unwrap_or(first(row), false)
    var left = token == Star && diagonal
    var next_row = [left]
    for entry in zip(chars, drop(row, 1)) {
      let ch = entry.0
      let above = entry.1
      left = match token {
        Star => above || left,
        AnyChar => diagonal,
        Literal(text) => diagonal && text == ch,
      }
      next_row = append(next_row, left)
      diagonal = above
    }
    row = next_row
  }
  return unwrap_or(last(row), false)
}

