fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  if len(xs) == 0 {
    return None
  }
  var run_sum = 0
  var run_start = 0
  var best_sum = 0
  var best_start = 0
  var best_end = 0
  for (i, x) in enumerate(xs) {
    if run_sum < 0 {
      run_sum = x
      run_start = i
