type Match {
  home: String,
  away: String,
  home_goals: Int,
  away_goals: Int,
}

fn summarize(team: String, scores: List[(String, Int, Int)]) -> (String, Int, Int, Int) {
  var points = 0
  var goals_for = 0
  var goals_against = 0
  for score in scores {
    let scored = score.1
    let conceded = score.2
    goals_for = goals_for + scored
    goals_against = goals_against + conceded
    if scored > conceded {
      points = points + 3
    } else if scored == conceded {
      points = points + 1
    }
  }
  return (team, points, goals_for - goals_against, goals_for)
}

fn league_table(matches: List[Match]) -> List[(String, Int, Int, Int)] {
  var scores = map(matches, |m| (m.home, m.home_goals, m.away_goals))
  for m in matches {
    scores = append(scores, (m.away, m.away_goals, m.home_goals))
  }
  return scores
    |> group_by(|s| s.0)
    |> map(|g| summarize(g.0, g.1))
    |> sort_by(|r| r.0)
    |> sort_desc_by(|r| r.3)
    |> sort_desc_by(|r| r.2)
    |> sort_desc_by(|r| r.1)
}

