fn cell_key(row: Int, col: Int) -> String {
  return to_string(row) + ":" + to_string(col)
}

fn live_cells(grid: List[String]) -> Map[String, Bool] {
  var cells = map_from([("", false)])
  for (row, text) in enumerate(grid) {
    let width = str_len(text)
    var col = 0
    for gap in split(text, "#") {
      col = col + str_len(gap)
      if col < width {
        cells = map_set(cells, cell_key(row, col), true)
      }
      col = col + 1
    }
  }
  return cells
}

fn count_neighbours(cells: Map[String, Bool], row: Int, col: Int) -> Int {
  var count = 0
  for dr in range(-1, 2) {
    for dc in range(-1, 2) {
      if dr != 0 || dc != 0 {
        let key = cell_key(row + dr, col + dc)
        if unwrap_or(map_get(cells, key), false) {
          count = count + 1
        }
      }
    }
  }
  return count
}

fn next_generation(grid: List[String]) -> List[String] {
  let cells = live_cells(grid)
  var next_grid = take(grid, 0)
  for (row, text) in enumerate(grid) {
    var next_row = ""
    for col in range(0, str_len(text)) {
      let count = count_neighbours(cells, row, col)
      let alive = unwrap_or(map_get(cells, cell_key(row, col)), false)
      if count == 3 || alive && count == 2 {
        next_row = next_row + "#"
      } else {
        next_row = next_row + "."
      }
    }
    next_grid = append(next_grid, next_row)
  }
  return next_grid
}

fn life_step(grid: List[String], steps: Int) -> List[String] {
  var current = grid
  var remaining = steps
  while remaining > 0 {
    current = next_generation(current)
    remaining = remaining - 1
  }
  return current
}

