type ParseState =
  | Start
  | FirstElement
  | NextElement
  | Minus
  | Digits
  | Separator
  | Done

fn invalid_at(position: Int) -> String {
  return "invalid at " + to_string(position)
}

fn flatten_nested(s: String) -> Result[(List[Int], Int), String] {
  let chars = filter(split(s, ""), |ch| ch != " " && ch != "")
  var state = Start
  var depth = 0
  var max_depth = 0
  var numbers = []
  var number = 0
  var negative = false
  for (position, ch) in enumerate(chars) {
    let digit = ch >= "0" && ch <= "9"
    if state == Digits && !digit {
      numbers = append(numbers, number)
      number = 0
      negative = false
      state = Separator
    }
    let can_start = state == FirstElement || state == NextElement
    if ch == "[" && (state == Start || can_start) {
      depth = depth + 1
      max_depth = max(max_depth, depth)
      state = FirstElement
    } else if ch == "]" && (state == FirstElement || state == Separator) {
      depth = depth - 1
      if depth == 0 {
        state = Done
      } else {
        state = Separator
      }
    } else if ch == "," && state == Separator {
      state = NextElement
    } else if ch == "-" && can_start {
      negative = true
      state = Minus
    } else if digit && (can_start || state == Minus || state == Digits) {
      var prefix = ""
      if number != 0 {
        prefix = to_string(number)
      } else if negative {
        prefix = "-"
      }
      let parsed = parse_int(prefix + ch)
      if parsed == None {
        return Err(invalid_at(position))
      }
      number = unwrap_or(parsed, 0)
      state = Digits
    } else {
      return Err(invalid_at(position))
    }
  }
  if state != Done {
    return Err(invalid_at(len(chars)))
  }
  return Ok((numbers, max_depth))
}

