type LisSuffix {
  value: Int,
  length: Int,
  count: Int,
}

fn empty_suffixes() -> List[LisSuffix] {
  return []
}

fn lis_length(xs: List[Int]) -> (Int, Int) {
  var ending = []
  var longest = 0
  for x in xs {
    var length = 1
    for (value, prev_length) in ending {
      if value < x {
        length = max(length, prev_length + 1)
      }
    }
    ending = append(ending, (x, length))
    longest = max(longest, length)
  }
  var suffixes = empty_suffixes()
  var total = 0
  for (x, length) in reverse(ending) {
    var count = 0
    if length == longest {
      count = 1
    } else {
      for next in suffixes {
        if x < next.value && next.length == length + 1 {
          count = count + next.count
        }
      }
    }
    if count > 0 {
      suffixes = append(suffixes, LisSuffix { value: x, length: length, count: count })
      if length == 1 {
        total = total + count
      }
    }
  }
  return (longest, total)
}

