fn min_coins(coins: List[Int], amount: Int) -> Option[(Int, List[Int])] {
  if amount < 0 {
    return None
  }
  var best = map_from([(0, (0, 0))])
  var subtotal = 0
  while subtotal < amount {
    subtotal = subtotal + 1
    var best_count = 0
    var best_coin = 0
    for coin in coins {
      if coin <= subtotal {
        let previous = unwrap_or(map_get(best, subtotal - coin), (-1, 0))
        if previous.0 >= 0 {
          let count = previous.0 + 1
          if best_count == 0 || count < best_count || count == best_count && coin > best_coin {
            best_count = count
            best_coin = coin
          }
        }
      }
    }
    if best_count > 0 {
      best = map_set(best, subtotal, (best_count, best_coin))
    }
  }
  var used = []
  var remaining = amount
  while remaining > 0 {
    let choice = unwrap_or(map_get(best, remaining), (0, 0))
    if choice.1 == 0 {
      return None
    }
    used = append(used, choice.1)
    remaining = remaining - choice.1
  }
  return Some((len(used), used))
}

