type Instruction =
  | Push(start: Int, stop: Int)
  | Apply(op: String)

type ParseState {
  chars: Map[Int, String],
  pos: Int,
  code: List[Instruction],
}

fn char_at(chars: Map[Int, String], pos: Int) -> String {
  return unwrap_or(map_get(chars, pos), "")
}

fn peek(state: ParseState) -> String {
  return char_at(state.chars, state.pos)
}

fn syntax_error(state: ParseState) -> String {
  let c = peek(state)
  if c == "" {
    return "unexpected end"
  }
  return "unexpected character: " + c
}

fn is_digit(c: String) -> Bool {
  return c >= "0" && c <= "9"
}

fn parse_factor(input: ParseState) -> Result[ParseState, String] {
  var state = input
  let c = peek(state)
  if is_digit(c) {
    let start = state.pos
    while is_digit(peek(state)) {
      state.pos = state.pos + 1
    }
    state.code = append(state.code, Push(start, state.pos))
    return Ok(state)
  }
  if c == "(" {
    state.pos = state.pos + 1
    state = try parse_level(state, 0)
    if peek(state) != ")" {
      return Err(syntax_error(state))
    }
    state.pos = state.pos + 1
    return Ok(state)
  }
  return Err(syntax_error(state))
}

fn is_operator(op: String, level: Int) -> Bool {
  if level == 0 {
    return op == "+" || op == "-"
  }
  return op == "*" || op == "/"
}

fn parse_level(input: ParseState, level: Int) -> Result[ParseState, String] {
  if level == 2 {
    return parse_factor(input)
  }
  var state = try parse_level(input, level + 1)
  while is_operator(peek(state), level) {
    let op = peek(state)
    state.pos = state.pos + 1
    state = try parse_level(state, level + 1)
    state.code = append(state.code, Apply(op))
  }
  return Ok(state)
}

fn read_number(chars: Map[Int, String], start: Int, stop: Int) -> Int {
  var value = 0
  for pos in range(start, stop) {
    let c = char_at(chars, pos)
    let digit = unwrap_or(parse_int(c), 0)
    value = value * 10 + digit
  }
  return value
}

fn apply_top(op: String, stack: Map[Int, Int], size: Int) -> Result[Int, String] {
  let left = unwrap_or(map_get(stack, size - 2), 0)
  let right = unwrap_or(map_get(stack, size - 1), 0)
  if op == "/" && right == 0 {
    return Err("division by zero")
  }
  return Ok(match op {
    "+" => left + right,
    "-" => left - right,
    "*" => left * right,
    _ => left / right,
  })
}

fn evaluate(state: ParseState) -> Result[Int, String] {
  var stack = map_from([(0, 0)])
  var size = 0
  for instruction in state.code {
    let step = match instruction {
      Push(start, stop) => (size, Ok(read_number(state.chars, start, stop))),
      Apply(op) => (size - 2, apply_top(op, stack, size)),
    }
    let value = try step.1
    stack = map_set(stack, step.0, value)
    size = step.0 + 1
  }
  return Ok(unwrap_or(map_get(stack, 0), 0))
}

fn eval_expr(s: String) -> Result[Int, String] {
  let chars = s
    |> split("")
    |> filter(|c| c != "" && c != " ")
    |> enumerate()
    |> map_from()
  let input = ParseState { chars: chars, pos: 0, code: [] }
  let parsed = try parse_level(input, 0)
  if peek(parsed) != "" {
    return Err(syntax_error(parsed))
  }
  return evaluate(parsed)
}

