type CsvState =
  | FieldStart
  | Unquoted
  | Quoted
  | AfterQuote

fn parse_csv_line(s: String) -> Result[List[String], String] {
  var fields = []
  var field = ""
  var state = FieldStart
  for (i, ch) in enumerate(split(s, "")) {
    if state == Quoted {
      if ch == "\"" {
        state = AfterQuote
      } else {
        field = field + ch
      }
    } else if ch == "," {
      fields = append(fields, field)
      field = ""
      state = FieldStart
    } else if state == AfterQuote {
      if ch != "\"" {
        return Err("expected comma at " + to_string(i))
      }
      field = field + ch
      state = Quoted
    } else if ch == "\"" {
      if state != FieldStart {
        return Err("unexpected quote at " + to_string(i))
      }
      state = Quoted
    } else {
      field = field + ch
      state = Unquoted
    }
  }
  if state == Quoted {
    return Err("unterminated quote")
  }
  return Ok(append(fields, field))
}

