fn parse_duration(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  let limit = 9007199254740991
  var total = 0
  var number = 0
  var has_digits = false
  var previous_scale = 3601
  var overflow = false
  for ch in split(s, "") {
    if ch >= "0" && ch <= "9" {
      has_digits = true
      if !overflow {
        let digit = unwrap_or(parse_int(ch), 0)
        if number > (limit - digit) / 10 {
          overflow = true
        } else {
          number = number * 10 + digit
        }
      }
    } else {
      let scale = match ch {
        "h" => 3600,
        "m" => 60,
        "s" => 1,
        _ => 0,
      }
      if scale == 0 {
        return Err("unknown unit: " + ch)
      }
      if !has_digits {
        return Err("missing number before " + ch)
      }
      if scale >= previous_scale {
        return Err("unit out of order: " + ch)
      }
      if !overflow {
        if number > (limit - total) / scale {
          overflow = true
        } else {
          total = total + number * scale
        }
      }
      previous_scale = scale
      number = 0
      has_digits = false
    }
  }
  if has_digits {
    return Err("missing unit")
  }
  if overflow {
    return Err("overflow")
  }
  return Ok(total)
}

