  let indexed = enumerate(contacts)
  var parents = map_from(take([(0, -1)], 0))
  var emails = map_from(take([("", 0)], 0))
  var phones = emails
  for (i, contact) in indexed {
    let email = trim(contact.email)
    let phone = phone_key(contact.phone)
    if email != "" {
      let previous = unwrap_or(map_get(emails, email), i)
      parents = link_contacts(parents, i, previous)
      emails = map_set(emails, email, i)
    }
    if phone != "" {
      let previous = unwrap_or(map_get(phones, phone), i)
      parents = link_contacts(parents, i, previous)
      phones = map_set(phones, phone, i)
    }
  }
  var merged = map_from(take(indexed, 0))
  for (i, contact) in indexed {
    let root = component_root(parents, i)
    let combined = match map_get(merged, root) {
      Some(earlier) => fill_contact(earlier, contact),
      None => contact,
    }
    merged = map_set(merged, root, combined)
  }
  return values(merged)
