type Employee {
  name: String,
  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn employee_pay(emp: Employee) -> Int {
  let regular = min(emp.hours, 40) * emp.rate_cents
  if emp.hours <= 40 {
    return regular
  }
  let overtime_base = (emp.hours - 40) * emp.rate_cents
  var half = overtime_base / 2
  if overtime_base < 0 && overtime_base % 2 != 0 {
    half = half - 1
  }
  return regular + overtime_base + half
}

fn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {
  return emps
    |> group_by(|emp| emp.dept)
    |> map(|group| (group.0, sum(map(group.1, employee_pay))))
    |> sort_by(|pair| pair.0)
    |> sort_desc_by(|pair| pair.1)
}

