type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

fn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {
  var orders = map_from(take([("", "")], 0))
  for event in events {
    let change = match event {
      Create(id) => (id, "create", [""], "created"),
      Pay(id) => (id, "pay", ["created"], "paid"),
      Ship(id) => (id, "ship", ["paid"], "shipped"),
      Cancel(id) => (id, "cancel", ["created", "paid"], "cancelled"),
    }
    let id = change.0
    let verb = change.1
    let current = unwrap_or(map_get(orders, id), "")
    if verb == "create" {
      if current != "" {
        return Err("duplicate order: " + id)
      }
    } else if current == "" {
      return Err("unknown order: " + id)
    } else if !contains(change.2, current) {
      return Err("cannot " + verb + " " + id + " from " + current)
    }
    orders = map_set(orders, id, change.3)
  }
  let pairs = zip(keys(orders), values(orders))
  let sorted = sort_by(pairs, |pair| pair.0)
  return Ok(sorted)
}

