type Setting {
  section: String,
  key: String,
  value: String,
}

fn upsert_setting(settings: List[Setting], setting: Setting) -> List[Setting] {
  var updated = []
  var replaced = false
  for old in settings {
    if old.section == setting.section && old.key == setting.key {
      updated = append(updated, setting)
      replaced = true
    } else {
      updated = append(updated, old)
    }
  }
  if !replaced {
    updated = append(updated, setting)
  }
  return updated
}

fn parse_config(lines: List[String]) -> Result[List[Setting], String] {
  var section = ""
  var settings = []
  for (i, raw) in enumerate(lines) {
    let line = trim(raw)
    if line != "" && first(split(line, "#")) != Some("") {
      let prefix = "line " + to_string(i + 1) + ": "
      let opening = split(line, "[")
      if first(opening) == Some("") {
        let rest = join(drop(opening, 1), "[")
        let closing = split(rest, "]")
        if len(closing) < 2 || last(closing) != Some("") {
          return Err(prefix + "bad header")
        }
        let interior = join(take(closing, len(closing) - 1), "]")
        let name = trim(interior)
        if name == "" {
          return Err(prefix + "bad header")
        }
        section = name
      } else {
        let parts = split(line, "=")
        if len(parts) < 2 {
          return Err(prefix + "missing =")
        }
        let raw_key = unwrap_or(first(parts), "")
        let key = trim(raw_key)
        if key == "" {
          return Err(prefix + "empty key")
        }
        let raw_value = join(drop(parts, 1), "=")
        let setting = Setting { section: section, key: key, value: trim(raw_value) }
        settings = upsert_setting(settings, setting)
      }
    }
  }
  return Ok(settings)
}

