fn rle_run(ch: String, count: Int) -> String {
  if count >= 2 {
    return ch + to_string(count)
  }
  return ch
}

fn rle_compress(s: String) -> String {
  var encoded = ""
  var previous = ""
  var count = 0
  for ch in split(s, "") {
    if ch != "" {
      if ch == previous {
        count = count + 1
      } else {
        encoded = encoded + rle_run(previous, count)
        previous = ch
        count = 1
      }
    }
  }
  encoded = encoded + rle_run(previous, count)
  if str_len(encoded) < str_len(s) {
    return encoded
  }
  return s
}

