fn is_vowel(letter: String, previous: String, at_start: Bool) -> Bool {
  let basic = contains(["a", "e", "i", "o"], letter)
  let valid_u = letter == "u" && previous != "q"
  let valid_y = letter == "y" && !at_start
  return basic || valid_u || valid_y
}

fn translate_word(word: String) -> String {
  let letters = filter(split(word, ""), |letter| letter != "")
  var previous = ""
  var prefix = ""
  for (i, letter) in enumerate(letters) {
    if is_vowel(letter, previous, i == 0) {
      if i == 0 {
        return word + "way"
      }
      return join(drop(letters, i), "") + prefix + "ay"
    }
    prefix = prefix + letter
    previous = letter
  }
  return word + "ay"
}

fn pig_latin(s: String) -> String {
  if s == "" {
    return ""
  }
  return s
    |> split(" ")
    |> map(translate_word)
    |> join(" ")
