fn decode_card(card: String) -> (Int, String) {
  let rank_names = ["2", "3", "4", "5", "6", "7", "8", "9", "T", "J", "Q", "K", "A"]
  for (rank, name) in enumerate(rank_names) {
    for suit in ["C", "D", "H", "S"] {
      if card == name + suit {
        return (rank, suit)
      }
    }
  }
  return (-1, "")
}

fn poker_hand(cards: List[String]) -> String {
  if len(cards) != 5 || len(group_by(cards, |card| card)) != 5 {
    return "invalid"
  }
  let decoded = map(cards, decode_card)
  for (rank, _) in decoded {
    if rank == -1 {
      return "invalid"
    }
  }
  let ranks = sort_by(map(decoded, |card| card.0), |rank| rank)
  let rank_groups = group_by(ranks, |rank| rank)
  let counts = map(rank_groups, |group| len(group.1))
  let has_three = contains(counts, 3)
  let pairs = len(filter(counts, |count| count == 2))
  let flush = len(group_by(decoded, |card| card.1)) == 1
  let low = unwrap_or(first(ranks), 0)
  let high = unwrap_or(last(ranks), 0)
  let straight = len(rank_groups) == 5 && (high - low == 4 || ranks == [0, 1, 2, 3, 12])
  if straight && flush {
    return "straight flush"
  }
  if contains(counts, 4) {
    return "four of a kind"
  }
  if has_three && pairs == 1 {
    return "full house"
  }
  if flush {
    return "flush"
  }
  if straight {
    return "straight"
  }
  if has_three {
    return "three of a kind"
  }
  if pairs == 2 {
    return "two pair"
  }
  if pairs == 1 {
    return "one pair"
  }
  return "high card"
}

