type Cmd =
  | Forward(steps: Int)
  | TurnLeft
  | TurnRight

fn advance(p: (Int, Int), d: (Int, Int), n: Int, obs: List[(Int, Int)]) -> (Int, Int) {
  var pos = p
  var remaining = n
  while remaining > 0 {
    let next = (pos.0 + d.0, pos.1 + d.1)
    if contains(obs, next) {
      break
    }
    pos = next
    remaining = remaining - 1
  }
  return pos
}

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var state = ((0, 0), 0)
  for cmd in cmds {
    let pos = state.0
    let heading = state.1
    let delta = match heading {
      0 => (0, 1),
      1 => (1, 0),
      2 => (0, -1),
      _ => (-1, 0),
    }
    state = match cmd {
      Forward(steps) => (advance(pos, delta, steps, obstacles), heading),
      TurnLeft => (pos, (heading + 3) % 4),
      TurnRight => (pos, (heading + 1) % 4),
    }
  }
  let pos = state.0
  let direction = match state.1 {
    0 => "N",
    1 => "E",
    2 => "S",
    _ => "W",
  }
  return (pos.0, pos.1, direction)
}

