fn standard_roman(n: Int) -> String {
  let symbols = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
  ]
  var remaining = n
  var text = ""
  for (value, symbol) in symbols {
    while remaining >= value {
      text = text + symbol
      remaining = remaining - value
    }
  }
  return text
}

fn roman_to_int(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  let chars = split(s, "")
  # Canonical numerals in range have at most 15 characters.
  let too_long = len(chars) > 15
  var total = 0
  var previous = 0
  for ch in chars {
    let value = match ch {
      "I" => 1,
      "V" => 5,
      "X" => 10,
      "L" => 50,
      "C" => 100,
      "D" => 500,
      "M" => 1000,
      _ => 0,
    }
    if value == 0 {
      return Err("invalid character: " + ch)
    }
    if !too_long {
      if previous < value {
        total = total - previous
      } else {
        total = total + previous
      }
      previous = value
    }
  }
  let value = total + previous
  if too_long || value < 1 || value > 3999 || standard_roman(value) != s {
    return Err("not canonical")
  }
  return Ok(value)
}

