type Session {
  user: String,
  kind: String,
  time: Int,
}

type UserState {
  started: Option[Int],
  total: Int,
}

fn empty_states() -> Map[String, UserState] {
  return map_from([])
}

fn close_session(state: UserState, time: Int) -> UserState {
  return match state.started {
    Some(start) => UserState { started: None, total: state.total + (time - start) },
    None => state,
  }
}

fn session_totals(events: List[Session]) -> List[(String, Int)] {
  let initial = UserState { started: None, total: 0 }
  var states = empty_states()
  var end_time = 0
  for event in events {
    end_time = event.time
    var state = unwrap_or(map_get(states, event.user), initial)
    if event.kind == "logout" {
      state = close_session(state, event.time)
    } else if state.started == None {
      state.started = Some(event.time)
    }
    states = map_set(states, event.user, state)
  }
  var totals = []
  for user in keys(states) {
    let state = unwrap_or(map_get(states, user), initial)
    let closed = close_session(state, end_time)
    totals = append(totals, (user, closed.total))
  }
  return sort_by(totals, |entry| entry.0)
}

