fn sliding_window_max(xs: List[Int], k: Int) -> Result[List[Int], String] {
  if k < 1 {
    return Err("window must be positive")
  }
  let n = len(xs)
  if k > n {
    return Err("window larger than input")
  }
  var prefixes = []
  var running = 0
  for (i, x) in enumerate(xs) {
    if i % k == 0 {
      running = x
    } else {
      running = max(running, x)
    }
    prefixes = append(prefixes, running)
  }
  var reversed_suffixes = []
  for (i, x) in enumerate(reverse(xs)) {
    if i == 0 || (n - i) % k == 0 {
      running = x
    } else {
      running = max(running, x)
    }
    reversed_suffixes = append(reversed_suffixes, running)
  }
  let starts = take(reverse(reversed_suffixes), n - k + 1)
  let ends = drop(prefixes, k - 1)
  let pairs = zip(starts, ends)
  return Ok(map(pairs, |a, b| max(a, b)))
}

