fn spiral_order(m: List[List[Int]]) -> List[Int] {
  var rows = m
  var order = []
  while len(rows) > 0 {
    let height = len(rows)
    let width = rows
      |> first()
      |> unwrap_or([])
      |> len()
    if width == 0 {
      break
    }
    for row in rows {
      order = append(order, unwrap_or(first(row), 0))
    }
    if width == 1 {
      break
    }
    let bottom = unwrap_or(last(rows), [])
    for value in drop(bottom, 1) {
      order = append(order, value)
    }
    if height == 1 {
      break
    }
    let above_bottom = take(rows, height - 1)
    for row in reverse(above_bottom) {
      order = append(order, unwrap_or(last(row), 0))
    }
    let top = unwrap_or(first(rows), [])
    let top_middle = take(drop(top, 1), width - 2)
    for value in reverse(top_middle) {
      order = append(order, value)
    }
    rows = map(drop(above_bottom, 1), |row| take(drop(row, 1), width - 2))
  }
  return order
}

