fn is_rle_digit(ch: String) -> Bool {
  return ch >= "0" && ch <= "9"
}

fn checked_rle_chars(s: String) -> Result[List[String], String] {
  let chars = filter(split(s, ""), |ch| ch != "")
  var current = ""
  var count_started = false
  for ch in chars {
    if is_rle_digit(ch) {
      if current == "" {
        return Err("missing character before count")
      }
      if !count_started && ch == "0" {
        return Err("bad count for " + current)
      }
      count_started = true
    } else {
      current = ch
      count_started = false
    }
  }
  return Ok(chars)
}

fn repeat_text(text: String, n: Int) -> String {
  var out = ""
  var remaining = n
  while remaining > 0 {
    out = out + text
    remaining = remaining - 1
  }
  return out
}

fn finish_run(ch: String, run: String) -> String {
  if run == "" {
    return ch
  }
  return run
}

fn rle_decode(s: String) -> Result[String, String] {
  let chars = try checked_rle_chars(s)
  var parts = []
  var current = ""
  var run = ""
  for ch in chars {
    if is_rle_digit(ch) {
      let digit = unwrap_or(parse_int(ch), 0)
      run = repeat_text(run, 10) + repeat_text(current, digit)
    } else {
      parts = append(parts, finish_run(current, run))
      current = ch
      run = ""
    }
  }
  parts = append(parts, finish_run(current, run))
  return Ok(join(parts, ""))
}

