from __future__ import annotations
from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Person(TypedDict):
    name: str
    age: int


def age_histogram(
    people: list[Person], width: int
) -> Ok[list[tuple[str, int]]] | Err:
    if width < 1:
        return {"ok": False, "error": "bad width"}

    for person in people:
        if person["age"] < 0:
            return {"ok": False, "error": "negative age: " + person["name"]}

    if not people:
        return {"ok": True, "value": []}

    counts: dict[int, int] = {}
    for person in people:
        bucket = person["age"] // width
        counts[bucket] = counts.get(bucket, 0) + 1

    result: list[tuple[str, int]] = []
    for bucket in range(min(counts), max(counts) + 1):
        start = bucket * width
        end = start + width - 1
        result.append((f"{start}-{end}", counts.get(bucket, 0)))

    return {"ok": True, "value": result}

