fn top_product_per_region(sales: List[Sale]) -> List[(String, String, Int)] {
  let regions = sort_by(group_by(sales, |sale| sale.region), |group| group.0)
  var winners = []
  for (region, region_sales) in regions {
    let products = group_by(region_sales, |sale| sale.product)
    var has_best = false
    var best_product = ""
    var best_revenue = 0
    for (product, product_sales) in products {
      let revenue = sum(map(product_sales, |sale| sale.units * sale.price_cents))
      let wins_tie = revenue == best_revenue && product < best_product
      if !has_best || revenue > best_revenue || wins_tie {
        has_best = true
        best_product = product
        best_revenue = revenue
      }
    }
    winners = append(winners, (region, best_product, best_revenue))
  }
  return winners
}

