  | Select(price: Int)
  | Refund

fn accept_coin(credit: Int, messages: List[String], cents: Int) -> (Int, List[String]) {
  if cents == 5 || cents == 10 || cents == 25 || cents == 100 {
    return (credit + cents, messages)
  }
  return (credit, append(messages, "reject " + to_string(cents)))
}

fn select_item(credit: Int, messages: List[String], price: Int) -> (Int, List[String]) {
  if credit >= price {
    let message = "vend " + to_string(price) + " change " + to_string(credit - price)
    return (0, append(messages, message))
  }
  return (credit, append(messages, "insufficient " + to_string(credit)))
}

