  if credit > 0 {
    return append(messages, "refund " + to_string(credit))
  }
  return messages
}

fn vending_machine(events: List[Event]) -> List[String] {
  var credit = 0
  var messages = take([""], 0)
  for event in events {
    let next = match event {
      Coin(cents) => accept_coin(credit, messages, cents),
      Select(price) => select_item(credit, messages, price),
      Refund => (0, refund_credit(credit, messages)),
    }
    credit = next.0
    messages = next.1
  }
  return refund_credit(credit, messages)
}

