  var xs = []
  var os = []
  for (row_index, row) in enumerate(board) {
    let cells = filter(split(row, ""), |cell| cell != "")
    for (col_index, cell) in enumerate(cells) {
      let position = row_index * 3 + col_index
      if cell == "X" {
        xs = append(xs, position)
      } else if cell == "O" {
        os = append(os, position)
      }
    }
  }
  let x_count = len(xs)
  let o_count = len(os)
  let difference = x_count - o_count
  if difference != 0 && difference != 1 {
