final:
type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

type Snapshot {
  text: String,
  cursor: Int,
}

type Editor {
  current: Snapshot,
  history: List[Snapshot],
}

fn characters(text: String) -> List[String] {
  return filter(split(text, ""), |ch| ch != "")
}

fn save_edit(editor: Editor, text: String, cursor: Int) -> Editor {
  return Editor {
    current: Snapshot { text: text, cursor: cursor },
    history: append(editor.history, editor.current),
  }
}

fn insert_text(editor: Editor, text: String) -> Editor {
  let chars = characters(editor.current.text)
  let cursor = editor.current.cursor
  let before = join(take(chars, cursor), "")
  let after = join(drop(chars, cursor), "")
  let next_cursor = cursor + len(characters(text))
  return save_edit(editor, before + text + after, next_cursor)
}

fn delete_text(editor: Editor, n: Int) -> Editor {
  let chars = characters(editor.current.text)
  let cursor = editor.current.cursor
  let next_cursor = max(0, cursor - n)
  let before = join(take(chars, next_cursor), "")
  let after = join(drop(chars, cursor), "")
  return save_edit(editor, before + after, next_cursor)
}

fn move_cursor(editor: Editor, cursor: Int) -> Editor {
  let current = Snapshot { text: editor.current.text, cursor: cursor }
  return Editor { current: current, history: editor.history }
}

fn move_right(editor: Editor, n: Int) -> Editor {
  let cursor = editor.current.cursor
  let remaining = len(characters(editor.current.text)) - cursor
  return move_cursor(editor, cursor + min(n, remaining))
}

fn undo_edit(editor: Editor) -> Editor {
  let history = editor.history
  return match last(history) {
    Some(saved) => Editor { current: saved, history: take(history, len(history) - 1) },
    None => editor,
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  var editor = Editor { current: Snapshot { text: "", cursor: 0 }, history: [] }
  for op in ops {
    editor = match op {
      Insert(text) => insert_text(editor, text),
      Delete(n) => delete_text(editor, n),
      Left(n) => move_cursor(editor, max(0, editor.current.cursor - n)),
      Right(n) => move_right(editor, n),
      Undo => undo_edit(editor),
    }
  }
  return editor.current.text
}

