def bowling_score(rolls: list[int]) -> Ok[int] | Err:
    if any(roll < 0 or roll > 10 for roll in rolls):
        return {"ok": False, "error": "invalid roll"}

    pos = 0
    score = 0
    for frame in range(1, 10):
        if pos == len(rolls):
            return {"ok": False, "error": "incomplete game"}
        first = rolls[pos]
        pos += 1

        if first == 10:
            score += 10 + sum(rolls[pos:pos + 2])
            continue

        if pos == len(rolls):
            return {"ok": False, "error": "incomplete game"}
        pins = first + rolls[pos]
        pos += 1
        if pins > 10:
            return {"ok": False, "error": f"too many pins in frame {frame}"}
        score += pins
        if pins == 10:
            score += sum(rolls[pos:pos + 1])

    tenth_start = pos
    if len(rolls) - pos < 2:
        return {"ok": False, "error": "incomplete game"}
    first, second = rolls[pos], rolls[pos + 1]
    pos += 2

    if first != 10 and first + second > 10:
        return {"ok": False, "error": "too many pins in frame 10"}

    if first == 10 or first + second == 10:
        if pos == len(rolls):
            return {"ok": False, "error": "incomplete game"}
        third = rolls[pos]
        pos += 1
        if first == 10 and second != 10 and second + third > 10:
            return {"ok": False, "error": "too many pins in frame 10"}

    if pos < len(rolls):
        return {"ok": False, "error": "too many rolls"}

    return {"ok": True, "value": score + sum(rolls[tenth_start:pos])}

