  | Print
  | Halt

fn empty_ints() -> List[Int] {
  return []
}

fn stack_needed(instr: Instr) -> Int {
  return match instr {
    Pop => 1,
    Dup => 1,
    Print => 1,
    Jz(_) => 1,
    Add => 2,
    Sub => 2,
    Mul => 2,
    Swap => 2,
    _ => 0,
  }
}

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  let size = len(prog)
  let code = map_from(enumerate(prog))
  var stack = empty_ints()
  var output = empty_ints()
  var pc = 0
  var steps = 0
  while pc < size {
    if steps == 1000 {
      return Err("step limit exceeded")
    }
    let instr = unwrap_or(map_get(code, pc), Halt)
    if instr == Halt {
      return Ok(output)
    }
    let needed = stack_needed(instr)
    let depth = len(stack)
    if depth < needed {
      return Err("stack underflow at " + to_string(pc))
    }
    let target = match instr {
      Jz(t) => t,
      Jmp(t) => t,
      _ => pc,
    }
    if target < 0 || target >= size {
      return Err("bad jump at " + to_string(pc))
    }
    var b = 0
    var a = 0
    if needed >= 1 {
      b = unwrap_or(last(stack), 0)
      stack = take(stack, depth - 1)
    }
    if needed == 2 {
      a = unwrap_or(last(stack), 0)
      stack = take(stack, depth - 2)
    }
    stack = match instr {
      Push(n) => append(stack, n),
      Add => append(stack, a + b),
      Sub => append(stack, a - b),
      Mul => append(stack, a * b),
      Dup => append(append(stack, b), b),
      Swap => append(append(stack, b), a),
      _ => stack,
    }
    if instr == Print {
      output = append(output, b)
    }
    if instr == Jmp(target) || instr == Jz(target) && b == 0 {
      pc = target
    } else {
      pc = pc + 1
    }
    steps = steps + 1
  }
  return Ok(output)
}

