def _version_key(version: str) -> list[tuple[int, str]] | None:
    parts = version.split(".")
    if len(parts) > 4:
        return None

    key: list[tuple[int, str]] = []
    for part in parts:
        if not part.isdecimal():
            return None
        digits = "".join(str(decimal(ch)) for ch in part).lstrip("0")
        key.append((len(digits), digits))

    key.extend([(0, "")] * (4 - len(key)))
    return key


def compare_versions(a: str, b: str) -> Ok[int] | Err:
    left = _version_key(a)
    if left is None:
        return {"ok": False, "error": "bad version: " + a}

    right = _version_key(b)
    if right is None:
        return {"ok": False, "error": "bad version: " + b}

    return {"ok": True, "value": (left > right) - (left < right)}

