fn tokenize(s: String) -> Result[List[Token], String] {
  var tokens = take([Num(0)], 0)
  if s == "" {
    return Ok(tokens)
  }
  let chars = split(s, "")
  let by_pos = map_from(enumerate(chars))
  let size = len(chars)
  let double_symbols = ["==", "<=", ">=", "!="]
  let single_symbols = ["+", "-", "*", "/", "=", "<", ">", "(", ")", ","]
  var i = 0
  while i < size {
    let c = unwrap_or(map_get(by_pos, i), "")
    if c == " " {
      i = i + 1
    } else if is_digit(c) || is_ident_start(c) {
      let numeric = is_digit(c)
      var text = ""
      while i < size {
        let ch = unwrap_or(map_get(by_pos, i), "")
        if !(is_digit(ch) || !numeric && is_ident_start(ch)) {
          break
        }
        if !numeric || text != "" || ch != "0" {
          text = text + ch
        }
        i = i + 1
      }
      if numeric {
        let value = try read_decimal(text)
        tokens = append(tokens, Num(value))
      } else {
        tokens = append(tokens, Ident(text))
      }
    } else {
      let next = unwrap_or(map_get(by_pos, i + 1), "")
      let pair = c + next
      if contains(double_symbols, pair) {
        tokens = append(tokens, Sym(pair))
        i = i + 2
      } else if contains(single_symbols, c) {
        tokens = append(tokens, Sym(c))
        i = i + 1
      } else {
        return Err("unexpected character: " + c + " at " + to_string(i))
      }
    }
  }
  return Ok(tokens)
}

