    end: int


def free_slots(
    meetings: list[Meeting], day_start: int, day_end: int
) -> list[tuple[int, int]]:
    if day_end <= day_start:
        return []

    occupied: list[tuple[int, int]] = []
    for meeting in meetings:
        start = max(day_start, meeting["start"])
        end = min(day_end, meeting["end"])
        if start < end:
            occupied.append((start, end))
    occupied.sort()

    free: list[tuple[int, int]] = []
    cursor = day_start
    for start, end in occupied:
        if cursor < start:
            free.append((cursor, start))
        cursor = max(cursor, end)

    if cursor < day_end:
        free.append((cursor, day_end))
    return free

