                matched = char == "?" or char == s[i]

            if matched:
                p += width
                i += 1
                continue

        if after_star == -1:
            return False

        star_end += 1
        i = star_end
        p = after_star

    while p < len(pattern) and pattern[p] == "*":
        p += 1
    return p == len(pattern)

