def _invalid(position: int) -> Err:
    return {"ok": False, "error": f"invalid at {position}"}


def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    text = s.replace(" ", "")
    end = len(text)
    if not text.startswith("["):
        return _invalid(0)

    is_decimal: Callable[[str], bool] = str.isdecimal
    values: list[int] = []
    depth = max_depth = 1
    position = 1
    state: Literal["start", "element", "separator"] = "start"

    while position < end:
        char = text[position]
        if char == "]" and state != "element":
            depth -= 1
            position += 1
            if depth == 0:
                if position != end:
                    return _invalid(position)
                return {"ok": True, "value": (values, max_depth)}
            state = "separator"
        elif state == "separator":
            if char != ",":
                return _invalid(position)
            position += 1
            state = "element"
        elif char == "[":
            depth += 1
            max_depth = max(max_depth, depth)
            position += 1
            state = "start"
        else:
            negative = char == "-"
            if negative:
                position += 1
            if position == end or not is_decimal(text[position]):
                return _invalid(position)

            value = 0
            while position < end and is_decimal(text[position]):
                value = value * 10 + int(text[position])
                position += 1
            values.append(-value if negative else value)
            state = "separator"

    return _invalid(end)

from __future__ import annotations


def life_step(grid: list[str], steps: int) -> list[str]:
    height = len(grid)
    if height == 0:
        return []
    width = len(grid[0])
    current = grid.copy()

    for _ in range(steps):
        next_grid: list[str] = []
        for row in range(height):
            next_row: list[str] = []
            for col in range(width):
                neighbors = 0
                for r in range(max(0, row - 1), min(height, row + 2)):
                    for c in range(max(0, col - 1), min(width, col + 2)):
                        if (r != row or c != col) and current[r][c] == "#":
                            neighbors += 1
                alive = neighbors == 3 or (
                    neighbors == 2 and current[row][col] == "#"
                )
                next_row.append("#" if alive else ".")
            next_grid.append("".join(next_row))
        current = next_grid

    return current

from __future__ import annotations


def max_subarray(xs: list[int]) -> tuple[int, int, int] | None:
    if not xs:
        return None

    current_sum = xs[0]
    current_start = 0
    best = (current_sum, 0, 0)

    for end in range(1, len(xs)):
        if current_sum < 0:
            current_sum = xs[end]
            current_start = end
        else:
            current_sum += xs[end]

        best_sum, best_start, best_end = best
        if current_sum > best_sum or (
            current_sum == best_sum
            and (current_start, end) < (best_start, best_end)
        ):
            best = (current_sum, current_start, end)

    return best

