def _unexpected(character: str) -> Err:
    return {"ok": False, "error": "unexpected character: " + character}


def _trunc_div(left: int, right: int) -> int:
    quotient = abs(left) // abs(right)
    return -quotient if (left < 0) != (right < 0) else quotient


def eval_expr(s: str) -> Ok[int] | Err:
    text = s.replace(" ", "")
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2}
    operators: list[str] = []
    postfix: list[str] = []
    need_factor = True
    i = 0

    while i < len(text):
        character = text[i]
        if need_factor:
            if character == "(":
                operators.append(character)
            elif character.isdecimal():
                start = i
                i += 1
                while i < len(text) and text[i].isdecimal():
                    i += 1
                postfix.append(text[start:i])
                need_factor = False
                continue
            else:
                return _unexpected(character)
        elif character in precedence:
            while (
                operators
                and operators[-1] != "("
                and precedence[operators[-1]] >= precedence[character]
            ):
                postfix.append(operators.pop())
            operators.append(character)
            need_factor = True
        elif character == ")":
            while operators and operators[-1] != "(":
                postfix.append(operators.pop())
            if not operators:
                return _unexpected(character)
            operators.pop()
        else:
            return _unexpected(character)
        i += 1

    if need_factor or "(" in operators:
        return {"ok": False, "error": "unexpected end"}
    postfix.extend(reversed(operators))

    operations: dict[str, Callable[[int, int], int]] = {
        "+": lambda left, right: left + right,
        "-": lambda left, right: left - right,
        "*": lambda left, right: left * right,
        "/": _trunc_div,
    }
    values: list[int] = []
    for token in postfix:
        if token in operations:
            right = values.pop()
            left = values.pop()
            if token == "/" and right == 0:
                return {"ok": False, "error": "division by zero"}
            values.append(operations[token](left, right))
        else:
            value = 0
            for digit in token:
                value = value * 10 + int(digit)
            values.append(value)

    return {"ok": True, "value": values[0]}

