def parking_fees(events: list[Park]) -> list[tuple[str, int]]:
    parked: dict[str, int] = {}
    totals: dict[str, int] = {}

    for event in events:
        plate = event["plate"]
        minute = event["minute"]

        if event["kind"] == "Arrive":
            parked.setdefault(plate, minute)
            continue

        arrival = parked.pop(plate, None)
        if arrival is None:
            continue

        billable_minutes = max(0, minute - arrival - 30)
        fee = min(1000, 200 * ((billable_minutes + 59) // 60))
        totals[plate] = totals.get(plate, 0) + fee

    return sorted(totals.items())

from __future__ import annotations


def min_coins(coins: list[int], amount: int) -> tuple[int, list[int]] | None:
    if amount < 0:
        return None
    if amount == 0:
        return (0, [])

    values = sorted({coin for coin in coins if coin <= amount}, reverse=True)
    if not values:
        return None

    unreachable = amount + 1
    counts = [unreachable] * (amount + 1)
    first_coin = [0] * (amount + 1)
    counts[0] = 0

    for subtotal in range(1, amount + 1):
        for coin in values:
            if coin > subtotal:
                continue
            candidate = counts[subtotal - coin] + 1
            if candidate < counts[subtotal]:
                counts[subtotal] = candidate
                first_coin[subtotal] = coin

    if counts[amount] == unreachable:
        return None

    used: list[int] = []
    remaining = amount
    while remaining > 0:
        coin = first_coin[remaining]
        used.append(coin)
        remaining -= coin

    return (counts[amount], used)

