def order_states(events: list[OrderEvent]) -> Ok[list[tuple[str, str]]] | Err:
    states: dict[str, str] = {}
    for event in events:
        order_id = event["id"]
        kind = event["kind"]
        current = states.get(order_id)

        if kind == "Create":
            if current is not None:
                return {"ok": False, "error": f"duplicate order: {order_id}"}
            states[order_id] = "created"
            continue

        if current is None:
            return {"ok": False, "error": f"unknown order: {order_id}"}

        if kind == "Pay" and current == "created":
            states[order_id] = "paid"
        elif kind == "Ship" and current == "paid":
            states[order_id] = "shipped"
        elif kind == "Cancel" and current in ("created", "paid"):
            states[order_id] = "cancelled"
        else:
            return {
                "ok": False,
                "error": f"cannot {kind.lower()} {order_id} from {current}",
            }

    return {"ok": True, "value": sorted(states.items())}

