def session_totals(events: list[Session]) -> list[tuple[str, int]]:
    if not events:
        return []

    totals: dict[str, int] = {}
    starts: dict[str, int] = {}

    for event in events:
        user = event["user"]
        time = event["time"]
        totals.setdefault(user, 0)

        if event["kind"] == "login":
            starts.setdefault(user, time)
        else:
            start = starts.pop(user, None)
            if start is not None:
                totals[user] += time - start

    end = events[-1]["time"]
    for user, start in starts.items():
        totals[user] += end - start

    return sorted(totals.items())

