_SYMBOL_VALUES: dict[str, int] = {
    "I": 1,
    "V": 5,
    "X": 10,
    "L": 50,
    "C": 100,
    "D": 500,
    "M": 1000,
}

_CANONICAL_TOKENS: tuple[tuple[int, str], ...] = (
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
)


def _canonical_roman(n: int) -> str:
    parts: list[str] = []
    for value, token in _CANONICAL_TOKENS:
        count, n = divmod(n, value)
        parts.append(token * count)
    return "".join(parts)


def roman_to_int(s: str) -> Ok[int] | Err:
    if not s:
        return {"ok": False, "error": "empty"}

    total = 0
    previous = 0
    for symbol in s:
        current = _SYMBOL_VALUES.get(symbol)
        if current is None:
            return {"ok": False, "error": f"invalid character: {symbol}"}
        total += -previous if previous < current else previous
        previous = current
    total += previous

    if not 1 <= total <= 3999 or s != _canonical_roman(total):
        return {"ok": False, "error": "not canonical"}
    return {"ok": True, "value": total}

