# ruff: noqa: F401

def poker_hand(cards: list[str]) -> str:
    ranks = "23456789TJQKA"
    suits = "CDHS"

    if len(cards) != 5:
        return "invalid"
    if any(
        len(card) != 2 or card[0] not in ranks or card[1] not in suits
        for card in cards
    ):
        return "invalid"
    if len(set(cards)) != 5:
        return "invalid"

    counts: dict[int, int] = {}
    for card in cards:
        rank = ranks.index(card[0])
        counts[rank] = counts.get(rank, 0) + 1

    groups = sorted(counts.values(), reverse=True)
    ordered = sorted(counts)
    flush = len({card[1] for card in cards}) == 1
    straight = len(ordered) == 5 and (
        ordered[-1] - ordered[0] == 4 or ordered == [0, 1, 2, 3, 12]
    )

    if straight and flush:
        return "straight flush"
    if groups == [4, 1]:
        return "four of a kind"
    if groups == [3, 2]:
        return "full house"
