def rle_decode(s: str) -> Ok[str] | Err:
    if s and "0" <= s[0] <= "9":
        return {"ok": False, "error": "missing character before count"}

    groups: list[tuple[str, str]] = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        start = i
        if i < len(s) and s[i] == "0":
            return {"ok": False, "error": f"bad count for {char}"}
        while i < len(s) and "0" <= s[i] <= "9":
            i += 1
        groups.append((char, s[start:i]))

    parts: list[str] = []
    for char, digits in groups:
        count = 0
        for digit in digits:
            count = count * 10 + (ord(digit) - ord("0"))
        parts.append(char * (count if digits else 1))
    return {"ok": True, "value": "".join(parts)}

