    name: str
    scores: list[int]


def student_medians(students: list[Student]) -> list[tuple[str, float]]:
    medians: list[tuple[str, float]] = []

    for student in students:
        scores = sorted(student["scores"])
        if not scores:
            continue

        middle = len(scores) // 2
        if len(scores) % 2:
            median = float(scores[middle])
        else:
            median = (scores[middle - 1] + scores[middle]) / 2

        medians.append((student["name"], median))

    medians.sort(key=lambda pair: (-pair[1], pair[0]))
    return medians

