def sliding_window_max(xs: list[int], k: int) -> Ok[list[int]] | Err:
    if k < 1:
        return {"ok": False, "error": "window must be positive"}
    if k > len(xs):
        return {"ok": False, "error": "window larger than input"}

    from collections import deque

    candidates: deque[int] = deque()
    maxima: list[int] = []
    append_maximum: Callable[[int], None] = maxima.append

    for i, value in enumerate(xs):
        if candidates and candidates[0] <= i - k:
            candidates.popleft()
        while candidates and xs[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(i)
        if i >= k - 1:
            append_maximum(xs[candidates[0]])

    return {"ok": True, "value": maxima}

