        return f"game {winner}"

    if a >= 3 and b >= 3:
        if a == b:
            return "deuce"
        return "advantage A" if a > b else "advantage B"

    if a == b:
        return f"{_POINT_NAMES[a]}-all"
    return f"{_POINT_NAMES[a]}-{_POINT_NAMES[b]}"

