fn bracket_depth(s: String) -> Result[Int, String] {
  var openings = []
  var deepest = 0
  for (i, ch) in enumerate(split(s, "")) {
    if ch == "(" || ch == "[" || ch == "{" {
      openings = append(openings, ch)
      deepest = max(deepest, len(openings))
    } else {
      let expected = match ch {
        ")" => "(",
        "]" => "[",
        "}" => "{",
        _ => "",
      }
      if expected != "" {
        if last(openings) != Some(expected) {
          return Err("mismatch at " + to_string(i))
        }
        openings = take(openings, len(openings) - 1)
      }
    }
  }
  if len(openings) > 0 {
    return Err("unclosed at end")
  }
  return Ok(deepest)
}

