fn read_roll(rolls: List[Int]) -> Result[(Int, List[Int]), String] {
  return match first(rolls) {
    Some(pins) => Ok((pins, drop(rolls, 1))),
    None => Err("incomplete game"),
  }
}

fn score_tenth(rolls: List[Int]) -> Result[Int, String] {
  let opening = try read_roll(rolls)
  let second = try read_roll(opening.1)
  var remaining = second.1
  var pins = opening.0 + second.0
  if opening.0 != 10 && pins > 10 {
    return Err("too many pins in frame 10")
  }
  if opening.0 == 10 || pins == 10 {
    let third = try read_roll(remaining)
    if opening.0 == 10 && second.0 != 10 && second.0 + third.0 > 10 {
      return Err("too many pins in frame 10")
    }
    pins = pins + third.0
    remaining = third.1
  }
  if len(remaining) > 0 {
    return Err("too many rolls")
  }
  return Ok(pins)
}

fn bowling_score(rolls: List[Int]) -> Result[Int, String] {
  for pins in rolls {
    if pins < 0 || pins > 10 {
      return Err("invalid roll")
    }
  }
  var remaining = rolls
  var score = 0
  for frame in range(1, 10) {
    let opening = try read_roll(remaining)
    remaining = opening.1
    if opening.0 == 10 {
      score = score + 10 + sum(take(remaining, 2))
    } else {
      let second = try read_roll(remaining)
      remaining = second.1
      let pins = opening.0 + second.0
      if pins > 10 {
        return Err("too many pins in frame " + to_string(frame))
      }
      score = score + pins
      if pins == 10 {
        score = score + sum(take(remaining, 1))
      }
    }
  }
  let tenth = try score_tenth(remaining)
  return Ok(score + tenth)
}

