type Job {
  name: String,
  deps: List[String],
}

fn deps_placed(deps: List[String], placed: Map[String, Bool]) -> Bool {
  for dep in deps {
    if !unwrap_or(map_get(placed, dep), false) {
      return false
    }
  }
  return true
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let unplaced = map_from(map(jobs, |job| (job.name, false)))
  var seen = unplaced
  for job in jobs {
    if unwrap_or(map_get(seen, job.name), false) {
      return Err("duplicate job: " + job.name)
    }
    seen = map_set(seen, job.name, true)
  }
  for job in jobs {
    for dep in job.deps {
      if !unwrap_or(map_get(seen, dep), false) {
        return Err("unknown dependency: " + dep)
      }
    }
  }
  var placed = unplaced
  var order = []
  while len(order) < len(jobs) {
    var progressed = false
    for job in jobs {
      if !unwrap_or(map_get(placed, job.name), false) && deps_placed(job.deps, placed) {
        order = append(order, job.name)
        placed = map_set(placed, job.name, true)
        progressed = true
        break
      }
    }
    if !progressed {
      return Err("cycle detected")
    }
  }
  return Ok(order)
}

