fn caesar_shift(s: String, k: Int) -> String {
  let alphabet = split("a b c d e f g h i j k l m n o p q r s t u v w x y z", " ")
  let offset = (k % 26 + 26) % 26
  let tail = drop(alphabet, offset)
  let rotated = fold(take(alphabet, offset), tail, |xs, c| append(xs, c))
  let shifts = map_from(zip(alphabet, rotated))
  return s
    |> split("")
    |> map(|c| unwrap_or(map_get(shifts, c), c))
    |> join("")
}

