fn find_all(s: String, pat: String) -> List[Int] {
  if pat == "" {
    return []
  }
  let chars = filter(split(s, ""), |c| c != "")
  let needle = filter(split(pat, ""), |c| c != "")
  let width = len(needle)
  let end = len(chars) - width + 1
  var positions = []
  for i in range(0, max(0, end)) {
    if take(drop(chars, i), width) == needle {
      positions = append(positions, i)
    }
  }
  return positions
}

