fn elevator_scan(start: Int, requests: List[Int], direction: String) -> List[Int] {
  let floors = requests
    |> map(|floor| (floor, true))
    |> map_from()
    |> keys()
  let above = sort_by(filter(floors, |floor| floor > start), |floor| floor)
  let below = sort_desc_by(filter(floors, |floor| floor < start), |floor| floor)
  var served = filter(floors, |floor| floor == start)
  var sweeps = (above, below)
  if direction == "down" {
    sweeps = (below, above)
  }
  for floor in sweeps.0 {
    served = append(served, floor)
  }
  for floor in sweeps.1 {
    served = append(served, floor)
  }
  return served
}

