type Key =
  | Digit(d: Int)
  | Enter
  | Clear

fn door_lock(code: String, events: List[Key]) -> String {
  let capacity = str_len(code)
  let empty_buffer = take([code], 0)
  var buffer = empty_buffer
  var failures = 0
  var state = "locked"
  for event in events {
    if state == "blocked" {
      break
    }
    if state == "open" {
      if event == Enter {
        state = "locked"
      }
    } else if event == Enter {
      if join(buffer, "") == code {
        state = "open"
        failures = 0
      } else {
        failures = failures + 1
        if failures == 3 {
          state = "blocked"
        }
      }
      buffer = empty_buffer
    } else {
      let discard = max(0, len(buffer) - capacity + 1)
      buffer = match event {
        Digit(d) => append(drop(buffer, discard), to_string(d)),
        Clear => empty_buffer,
        Enter => empty_buffer,
      }
    }
  }
  return state
}

