fn edit_script_distance(a: String, b: String) -> Int {
  let left = filter(split(a, ""), |c| c != "")
  let right = filter(split(b, ""), |c| c != "")
  let columns = range(0, len(right) + 1)
  var previous = map_from(map(columns, |j| (j, j)))
  var two_back = previous
  var prior_a = ""
  for (i, char_a) in enumerate(left) {
    var current = map_from([(0, i + 1)])
    var left_cost = i + 1
    var prior_b = ""
    for (j, char_b) in enumerate(right) {
      let above = unwrap_or(map_get(previous, j + 1), 0)
      let diagonal = unwrap_or(map_get(previous, j), 0)
      var replacement = diagonal
      if char_a != char_b {
        replacement = replacement + 1
      }
      var cost = min(min(above, left_cost) + 1, replacement)
      if i > 0 && j > 0 && char_a == prior_b && prior_a == char_b {
        let before_pair = unwrap_or(map_get(two_back, j - 1), 0)
        cost = min(cost, before_pair + 1)
      }
      current = map_set(current, j + 1, cost)
      left_cost = cost
      prior_b = char_b
    }
    two_back = previous
    previous = current
    prior_a = char_a
  }
  return unwrap_or(map_get(previous, len(right)), 0)
}

