type Meeting {
  start: Int,
  end: Int,
}

fn free_slots(meetings: List[Meeting], day_start: Int, day_end: Int) -> List[(Int, Int)] {
  if day_end <= day_start {
    return []
  }
  let sorted = sort_by(meetings, |m| m.start)
  var slots = []
  var cursor = day_start
  for m in sorted {
    let start = max(day_start, m.start)
    let end = min(day_end, m.end)
    if start < end {
      if cursor < start {
        slots = append(slots, (cursor, start))
      }
      cursor = max(cursor, end)
    }
  }
  if cursor < day_end {
    slots = append(slots, (cursor, day_end))
  }
  return slots
}

