type BankOp =
  | Open(name: String)
  | Deposit(name: String, amount: Int)
  | Withdraw(name: String, amount: Int)
  | Transfer(src: String, dst: String, amount: Int)

type Ledger {
  balances: Map[String, Int],
  names: List[String],
}

fn account_balance(ledger: Ledger, name: String) -> Result[Int, String] {
  return match map_get(ledger.balances, name) {
    Some(balance) => Ok(balance),
    None => Err("unknown account " + name),
  }
}

fn open_account(ledger: Ledger, name: String) -> Result[Ledger, String] {
  if map_get(ledger.balances, name) != None {
    return Err("duplicate account " + name)
  }
  var updated = ledger
  updated.balances = map_set(ledger.balances, name, 0)
  updated.names = append(ledger.names, name)
  return Ok(updated)
}

fn deposit(ledger: Ledger, name: String, amount: Int) -> Result[Ledger, String] {
  let balance = try account_balance(ledger, name)
  if amount <= 0 {
    return Err("invalid amount")
  }
  var updated = ledger
  updated.balances = map_set(ledger.balances, name, balance + amount)
  return Ok(updated)
}

fn withdraw(ledger: Ledger, name: String, amount: Int) -> Result[Ledger, String] {
  let balance = try account_balance(ledger, name)
  if amount <= 0 {
    return Err("invalid amount")
  }
  if amount > balance {
    return Err("insufficient funds")
  }
  var updated = ledger
  updated.balances = map_set(ledger.balances, name, balance - amount)
  return Ok(updated)
}

fn transfer(ledger: Ledger, src: String, dst: String, amount: Int) -> Result[Ledger, String] {
  let src_balance = try account_balance(ledger, src)
  let dst_balance = try account_balance(ledger, dst)
  if src == dst {
    return Err("same account")
  }
  if amount <= 0 {
    return Err("invalid amount")
  }
  if amount > src_balance {
    return Err("insufficient funds")
  }
  let debited = map_set(ledger.balances, src, src_balance - amount)
  var updated = ledger
  updated.balances = map_set(debited, dst, dst_balance + amount)
  return Ok(updated)
}

fn apply_step(ledger: Ledger, op: BankOp, step: Int) -> Result[Ledger, String] {
  let outcome = match op {
    Open(name) => open_account(ledger, name),
    Deposit(name, amount) => deposit(ledger, name, amount),
    Withdraw(name, amount) => withdraw(ledger, name, amount),
    Transfer(src, dst, amount) => transfer(ledger, src, dst, amount),
  }
  return match outcome {
    Ok(updated) => Ok(updated),
    Err(message) => Err("step " + to_string(step) + ": " + message),
  }
}

fn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {
  var ledger = Ledger { balances: map_from([]), names: [] }
  for (i, op) in enumerate(ops) {
    ledger = try apply_step(ledger, op, i + 1)
  }
  let balances = ledger.balances
  let entries = map(ledger.names, |name| (name, unwrap_or(map_get(balances, name), 0)))
  return Ok(entries)
}

