fn heading_numbers(lines: List[String]) -> List[String] {
  var outputs = []
  var one = 0
  var two = 0
  var three = 0
  for line in lines {
    let parts = split(line, " ")
    let marker = unwrap_or(first(parts), "")
    let level = match marker {
      "#" => 1,
      "##" => 2,
      "###" => 3,
      _ => 0,
    }
    if level > 0 {
      let title = join(drop(parts, 1), " ")
      if title != "" {
        if level == 1 {
          one = one + 1
          two = 0
          three = 0
        } else if level == 2 {
          two = two + 1
          three = 0
        } else {
          three = three + 1
        }
        let top = to_string(one)
        let middle = top + "." + to_string(two)
        let number = match level {
          1 => top,
          2 => middle,
          _ => middle + "." + to_string(three),
        }
        outputs = append(outputs, number + " " + title)
      }
    }
  }
  return outputs
}

