fn count_islands(grid: List[String]) -> (Int, Int) {
  let first_row = unwrap_or(first(grid), "")
  let stride = str_len(first_row) + 1
  var land = map_from(take([(0, false)], 0))
  for (row_index, row) in enumerate(grid) {
    var cell = row_index * stride
    for run in split(row, ".") {
      let end = cell + str_len(run)
      for id in range(cell, end) {
        land = map_set(land, id, true)
      }
      cell = end + 1
    }
  }
  var islands = 0
  var largest = 0
  for start in keys(land) {
    if unwrap_or(map_get(land, start), false) {
      islands = islands + 1
      var size = 0
      var pending = [start]
      land = map_set(land, start, false)
      while len(pending) > 0 {
        let cell = unwrap_or(last(pending), start)
        pending = take(pending, len(pending) - 1)
        size = size + 1
        for neighbor in [cell - 1, cell + 1, cell - stride, cell + stride] {
          if unwrap_or(map_get(land, neighbor), false) {
            land = map_set(land, neighbor, false)
            pending = append(pending, neighbor)
          }
        }
      }
      largest = max(largest, size)
    }
  }
  return (islands, largest)
}

