type Stock {
  sku: String,
  qty: Int,
}

type Txn {
  sku: String,
  delta: Int,
}

fn inventory_ledger(stock: List[Stock], txns: List[Txn]) -> Result[List[Stock], String] {
  var quantities = map_from(map(stock, |item| (item.sku, item.qty)))
  for (i, txn) in enumerate(txns) {
    let prefix = "txn " + to_string(i + 1) + ": "
    let qty = try (match map_get(quantities, txn.sku) {
      Some(value) => Ok(value),
      None => Err(prefix + "unknown sku " + txn.sku),
    })
    let next_qty = qty + txn.delta
    if next_qty < 0 {
      return Err(prefix + txn.sku + " would go negative")
    }
    quantities = map_set(quantities, txn.sku, next_qty)
  }
  let remaining = stock
    |> map(|item| Stock { sku: item.sku, qty: unwrap_or(map_get(quantities, item.sku), 0) })
    |> filter(|item| item.qty > 0)
    |> sort_by(|item| item.sku)
  return Ok(remaining)
}

