type Request {
  endpoint: String,
  ms: Int,
  status: Int,
}

fn summarize_endpoint(group: (String, List[Request])) -> (String, Int, Int, Int) {
  let requests = group.1
  let count = len(requests)
  let rank = count - count / 10
  let sorted = sort_by(requests, |request| request.ms)
  let ranked = first(drop(sorted, rank - 1))
  let p90 = match ranked {
    Some(request) => request.ms,
    None => 0,
  }
  let errors = len(filter(requests, |request| request.status >= 500))
  return (group.0, count, p90, errors)
}

fn latency_report(entries: List[Request]) -> List[(String, Int, Int, Int)] {
  let groups = group_by(entries, |request| request.endpoint)
  return map(groups, summarize_endpoint)
}

