type ParseState =
  | Opening
  | FirstElement
  | NextElement
  | AfterElement
  | Minus
  | Digits
  | Done

fn invalid_at(i: Int) -> String {
  return "invalid at " + to_string(i)
}

fn add_digit(n: Int, negative: Bool, digit: String, i: Int) -> Result[Int, String] {
  if n == 0 && digit == "0" {
    return Ok(0)
  }
  let prefix = match (n == 0, negative) {
    (true, true) => "-",
    (true, false) => "",
    _ => to_string(n),
  }
  return match parse_int(prefix + digit) {
    Some(value) => Ok(value),
    None => Err(invalid_at(i)),
  }
}

fn flatten_nested(s: String) -> Result[(List[Int], Int), String] {
  let chars = filter(split(s, ""), |c| c != " " && c != "")
  var state = Opening
  var depth = 0
  var deepest = 0
  var integers = []
  var number = 0
  var negative = false
  for (i, c) in enumerate(chars) {
    let digit = c >= "0" && c <= "9"
    if state == Digits && !digit {
      integers = append(integers, number)
      state = AfterElement
    }
    let wants_element = state == FirstElement || state == NextElement
    let can_close = state == FirstElement || state == AfterElement
    let can_take_digit = wants_element || state == Minus || state == Digits
    if state == Opening || wants_element && c == "[" {
      if c != "[" {
        return Err(invalid_at(i))
      }
      depth = depth + 1
      deepest = max(deepest, depth)
      state = FirstElement
    } else if can_close && c == "]" {
      depth = depth - 1
      if depth == 0 {
        state = Done
      } else {
        state = AfterElement
      }
    } else if state == AfterElement && c == "," {
      state = NextElement
    } else if wants_element && c == "-" {
      number = 0
      negative = true
      state = Minus
    } else if can_take_digit && digit {
      if wants_element {
        number = 0
        negative = false
      }
      number = try add_digit(number, negative, c, i)
      state = Digits
    } else {
      return Err(invalid_at(i))
    }
  }
  if state != Done {
    return Err(invalid_at(len(chars)))
  }
  return Ok((integers, deepest))
}

