type GlobToken =
  | Star
  | AnyChar
  | Literal(value: String)

fn glob_chars(s: String) -> List[String] {
  return filter(split(s, ""), |c| c != "")
}

fn glob_tokens(pattern: String) -> List[GlobToken] {
  var tokens = []
  var escaped = false
  for c in glob_chars(pattern) {
    if escaped {
      tokens = append(tokens, Literal(c))
      escaped = false
    } else if c == "\\" {
      escaped = true
    } else if c == "*" {
      tokens = append(tokens, Star)
    } else if c == "?" {
      tokens = append(tokens, AnyChar)
    } else {
      tokens = append(tokens, Literal(c))
    }
  }
  if escaped {
    tokens = append(tokens, Literal("\\"))
  }
  return tokens
}

fn glob_match(pattern: String, s: String) -> Bool {
  let tokens = glob_tokens(pattern)
  let chars = glob_chars(s)
  let token_at = map_from(enumerate(tokens))
  let char_at = map_from(enumerate(chars))
  let token_count = len(tokens)
  let char_count = len(chars)
  var p = 0
  var i = 0
  var retry_at = -1
  var star_end = 0
  while i < char_count {
    let token = map_get(token_at, p)
    let c = unwrap_or(map_get(char_at, i), "")
    if token == Some(Star) {
      p = p + 1
      retry_at = p
      star_end = i
    } else if token == Some(AnyChar) || token == Some(Literal(c)) {
      p = p + 1
      i = i + 1
    } else if retry_at < 0 {
      return false
    } else {
      star_end = star_end + 1
      i = star_end
      p = retry_at
    }
  }
  while p < token_count {
    if map_get(token_at, p) != Some(Star) {
      return false
    }
    p = p + 1
  }
  return true
}

