fn is_digit(c: String) -> Bool {
  return c >= "0" && c <= "9"
}

fn precedence(op: String) -> Int {
  return match op {
    "+" => 1,
    "-" => 1,
    "*" => 2,
    "/" => 2,
    _ => 0,
  }
}

fn to_postfix(s: String) -> Result[List[String], String] {
  let chars = filter(split(s, ""), |c| c != " " && c != "")
  var output = take([""], 0)
  var ops = take([""], 0)
  var number = ""
  var need_operand = true
  var depth = 0
  for c in chars {
    if is_digit(c) {
      if !need_operand && number == "" {
        return Err("unexpected character: " + c)
      }
      number = number + c
      need_operand = false
    } else {
      if number != "" {
        output = append(output, number)
        number = ""
      }
      let rank = precedence(c)
      if need_operand && c == "(" {
        ops = append(ops, c)
        depth = depth + 1
      } else if !need_operand && c == ")" && depth > 0 {
        while len(ops) > 0 {
          let op = unwrap_or(last(ops), "")
          ops = take(ops, len(ops) - 1)
          if op == "(" {
            break
          }
          output = append(output, op)
        }
        depth = depth - 1
      } else if !need_operand && rank > 0 {
        while len(ops) > 0 {
          let op = unwrap_or(last(ops), "")
          if precedence(op) < rank {
            break
          }
          ops = take(ops, len(ops) - 1)
          output = append(output, op)
        }
        ops = append(ops, c)
        need_operand = true
      } else {
        return Err("unexpected character: " + c)
      }
    }
  }
  if need_operand || depth != 0 {
    return Err("unexpected end")
  }
  if number != "" {
    output = append(output, number)
  }
  for op in reverse(ops) {
    output = append(output, op)
  }
  return Ok(output)
}

fn read_number(token: String) -> Result[Int, String] {
  return match parse_int(token) {
    Some(value) => Ok(value),
    None => Err("integer overflow"),
  }
}

fn eval_expr(s: String) -> Result[Int, String] {
  let tokens = try to_postfix(s)
  var stack = take([0], 0)
  for token in tokens {
    if precedence(token) == 0 {
      let value = try read_number(token)
      stack = append(stack, value)
    } else {
      let right = unwrap_or(last(stack), 0)
      stack = take(stack, len(stack) - 1)
      let left = unwrap_or(last(stack), 0)
      stack = take(stack, len(stack) - 1)
      if token == "/" && right == 0 {
        return Err("division by zero")
      }
      let value = match token {
        "+" => left + right,
        "-" => left - right,
        "*" => left * right,
        _ => left / right,
      }
      stack = append(stack, value)
    }
  }
  return Ok(unwrap_or(last(stack), 0))
}

