type Match {
  home: String,
  away: String,
  home_goals: Int,
  away_goals: Int,
}

type Tally {
  points: Int,
  goals_for: Int,
  goals_against: Int,
}

fn empty_tally() -> Tally {
  return Tally { points: 0, goals_for: 0, goals_against: 0 }
}

fn add_result(ts: Map[String, Tally], team: String, gf: Int, ga: Int) -> Map[String, Tally] {
  let old = unwrap_or(map_get(ts, team), empty_tally())
  var points = 0
  if gf > ga {
    points = 3
  } else if gf == ga {
    points = 1
  }
  let updated = Tally {
    points: old.points + points,
    goals_for: old.goals_for + gf,
    goals_against: old.goals_against + ga,
  }
  return map_set(ts, team, updated)
}

fn league_table(matches: List[Match]) -> List[(String, Int, Int, Int)] {
  let initial = map(matches, |m| (m.home, empty_tally()))
  var totals = map_from(initial)
  for m in matches {
    totals = add_result(totals, m.home, m.home_goals, m.away_goals)
    totals = add_result(totals, m.away, m.away_goals, m.home_goals)
  }
  var rows = take([("", 0, 0, 0)], 0)
  for team in keys(totals) {
    let total = unwrap_or(map_get(totals, team), empty_tally())
    let difference = total.goals_for - total.goals_against
    rows = append(rows, (team, total.points, difference, total.goals_for))
  }
  return rows
    |> sort_by(|row| row.0)
    |> sort_desc_by(|row| row.3)
    |> sort_desc_by(|row| row.2)
    |> sort_desc_by(|row| row.1)
}

