fn life_key(y: Int, x: Int) -> String {
  return to_string(y) + "," + to_string(x)
}

fn life_live_cells(grid: List[String]) -> Map[String, Bool] {
  var live = map_from([("", false)])
  for (y, row) in enumerate(grid) {
    var x = 0
    for run in split(row, ".") {
      let width = str_len(run)
      for offset in range(0, width) {
        live = map_set(live, life_key(y, x + offset), true)
      }
      x = x + width + 1
    }
  }
  return live
}

fn life_next_cell(live: Map[String, Bool], y: Int, x: Int) -> String {
  var neighbours = 0
  for dy in [-1, 0, 1] {
    for dx in [-1, 0, 1] {
      if dy != 0 || dx != 0 {
        if unwrap_or(map_get(live, life_key(y + dy, x + dx)), false) {
          neighbours = neighbours + 1
        }
      }
    }
  }
  let alive = unwrap_or(map_get(live, life_key(y, x)), false)
  if neighbours == 3 || alive && neighbours == 2 {
    return "#"
  }
  return "."
}

fn life_step(grid: List[String], steps: Int) -> List[String] {
  var current = grid
  let first_row = unwrap_or(first(grid), "")
  let width = str_len(first_row)
  if width == 0 {
    return current
  }
  let columns = range(0, width)
  let rows = range(0, len(grid))
  var generation = 0
  while generation < steps {
    let live = life_live_cells(current)
    var next = take(grid, 0)
    for y in rows {
      let cells = map(columns, |x| life_next_cell(live, y, x))
      next = append(next, join(cells, ""))
    }
    current = next
    generation = generation + 1
  }
  return current
}

