fn min_coins(coins: List[Int], amount: Int) -> Option[(Int, List[Int])] {
  if amount < 0 {
    return None
  }
  if amount == 0 {
    return Some((0, []))
  }
  let usable = filter(coins, |coin| coin > 0 && coin <= amount)
  if len(usable) == 0 {
    return None
  }
  var best = map_from([(0, (0, 0))])
  var subtotal = 0
  while subtotal < amount {
    subtotal = subtotal + 1
    var best_count = 0
    var best_coin = 0
    for coin in usable {
      if coin <= subtotal {
        let previous = unwrap_or(map_get(best, subtotal - coin), (-1, 0))
        if previous.0 >= 0 {
          let count = previous.0 + 1
          if best_coin == 0 || count < best_count || count == best_count && coin > best_coin {
            best_count = count
            best_coin = coin
          }
        }
      }
    }
    if best_coin > 0 {
      best = map_set(best, subtotal, (best_count, best_coin))
    }
  }
  var used = []
  var remaining = amount
  while remaining > 0 {
    let step = unwrap_or(map_get(best, remaining), (0, 0))
    let coin = step.1
    if coin == 0 {
      return None
    }
    used = append(used, coin)
    remaining = remaining - coin
  }
  return Some((len(used), used))
}

