type Entry {
  value: Int,
  length: Int,
  ways: Int,
}

fn empty_entries() -> List[Entry] {
  return []
}

fn lis_length(xs: List[Int]) -> (Int, Int) {
  var endings = empty_entries()
  var longest = 0
  for x in xs {
    var length = 1
    for prev in endings {
      if prev.value < x {
        length = max(length, prev.length + 1)
      }
    }
    endings = append(endings, Entry { value: x, length: length, ways: 0 })
    longest = max(longest, length)
  }
  var successors = empty_entries()
  var count = 0
  for item in reverse(endings) {
    var entry = item
    if entry.length == longest {
      entry.ways = 1
    } else {
      for next in successors {
        if next.value > entry.value && next.length == entry.length + 1 {
          entry.ways = entry.ways + next.ways
        }
      }
    }
    if entry.ways > 0 {
      successors = append(successors, entry)
      if entry.length == 1 {
        count = count + entry.ways
      }
    }
  }
  return (longest, count)
}

