fn next_permutation(xs: List[Int]) -> List[Int] {
  let neighbors = zip(xs, drop(xs, 1))
  var pivot = -1
  var pivot_value = 0
  for (i, pair) in enumerate(neighbors) {
    if pair.0 < pair.1 {
      pivot = i
      pivot_value = pair.0
    }
  }
  if pivot == -1 {
    return reverse(xs)
  }
  let suffix = reverse(drop(xs, pivot + 1))
  var successor = pivot_value
  var successor_index = -1
  for (i, value) in enumerate(suffix) {
    if value > pivot_value {
      successor = value
      successor_index = i
      break
    }
  }
  var arranged = append(take(xs, pivot), successor)
  for (i, value) in enumerate(suffix) {
    if i == successor_index {
      arranged = append(arranged, pivot_value)
    } else {
      arranged = append(arranged, value)
    }
  }
  return arranged
}

