type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

fn empty_order_map() -> Map[String, String] {
  return map_from([])
}

fn next_order_state(id: String, verb: String, current: Option[String]) -> Result[String, String] {
  return match (verb, current) {
    ("create", None) => Ok("created"),
    ("create", Some(_)) => Err("duplicate order: " + id),
    (_, None) => Err("unknown order: " + id),
    ("pay", Some("created")) => Ok("paid"),
    ("ship", Some("paid")) => Ok("shipped"),
    ("cancel", Some("created")) => Ok("cancelled"),
    ("cancel", Some("paid")) => Ok("cancelled"),
    (_, Some(state)) => Err("cannot " + verb + " " + id + " from " + state),
  }
}

fn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {
  var states = empty_order_map()
  for event in events {
    let action = match event {
      Create(id) => (id, "create"),
      Pay(id) => (id, "pay"),
      Ship(id) => (id, "ship"),
      Cancel(id) => (id, "cancel"),
    }
    let id = action.0
    let state = try next_order_state(id, action.1, map_get(states, id))
    states = map_set(states, id, state)
  }
  let pairs = states
    |> keys()
    |> sort_by(|id| id)
    |> map(|id| (id, unwrap_or(map_get(states, id), "")))
  return Ok(pairs)
}

