type CsvState =
  | FieldStart
  | Unquoted
  | Quoted
  | AfterQuote

fn parse_csv_line(s: String) -> Result[List[String], String] {
  let chars = filter(split(s, ""), |c| c != "")
  var fields = []
  var field = ""
  var state = FieldStart
  for (i, c) in enumerate(chars) {
    if state == Quoted {
      if c == "\"" {
        state = AfterQuote
      } else {
        field = field + c
      }
    } else if c == "," {
      fields = append(fields, field)
      field = ""
      state = FieldStart
    } else if state == AfterQuote {
      if c != "\"" {
        return Err("expected comma at " + to_string(i))
      }
      field = field + c
      state = Quoted
    } else if c == "\"" {
      if state != FieldStart {
        return Err("unexpected quote at " + to_string(i))
      }
      state = Quoted
    } else {
      field = field + c
      state = Unquoted
    }
  }
  if state == Quoted {
    return Err("unterminated quote")
  }
  return Ok(append(fields, field))
}

