# A root stores its component size as a negative number.
# Other entries store the index of their parent.
fn contact_root(forest: Map[Int, Int], index: Int) -> Int {
  var root = index
  var parent = unwrap_or(map_get(forest, root), -1)
  while parent >= 0 {
    root = parent
    parent = unwrap_or(map_get(forest, root), -1)
  }
  return root
}

fn link_contacts(forest: Map[Int, Int], left: Int, right: Int) -> Map[Int, Int] {
  let a = contact_root(forest, left)
  let b = contact_root(forest, right)
  if a == b {
    return forest
  }
  let size_a = unwrap_or(map_get(forest, a), -1)
  let size_b = unwrap_or(map_get(forest, b), -1)
  let combined = size_a + size_b
  if size_a <= size_b {
    return map_set(map_set(forest, a, combined), b, a)
  }
  return map_set(map_set(forest, b, combined), a, b)
}

