  let indexed = enumerate(contacts)
  let no_indices = range(0, 0)
  let no_keys = take([""], 0)
  var seen = map_from(zip(no_keys, no_indices))
  var forest = map_from(map(indexed, |i, c| (i, -1)))
  for (i, contact) in indexed {
    let email = trim(contact.email)
    let phone = phone_digits(contact.phone)
    for key in ["e:" + email, "p:" + phone] {
      if str_len(key) > 2 {
        let previous = unwrap_or(map_get(seen, key), -1)
        if previous < 0 {
          seen = map_set(seen, key, i)
        } else {
          forest = link_contacts(forest, i, previous)
        }
      }
    }
  }
  var merged = map_from(zip(no_indices, contacts))
  for (i, contact) in indexed {
    let root = contact_root(forest, i)
    let updated = match map_get(merged, root) {
      Some(earlier) => fill_empty_fields(earlier, contact),
      None => contact,
    }
    merged = map_set(merged, root, updated)
