type Setting {
  section: String,
  key: String,
  value: String,
}

fn parse_header(open_parts: List[String], error_prefix: String) -> Result[String, String] {
  let body = join(drop(open_parts, 1), "[")
  let close_parts = split(body, "]")
  if len(close_parts) < 2 || last(close_parts) != Some("") {
    return Err(error_prefix + "bad header")
  }
  let section = close_parts
    |> take(len(close_parts) - 1)
    |> join("]")
    |> trim()
  if section == "" {
    return Err(error_prefix + "bad header")
  }
  return Ok(section)
}

fn same_key(a: Setting, b: Setting) -> Bool {
  return a.section == b.section && a.key == b.key
}

fn upsert(settings: List[Setting], entry: Setting) -> List[Setting] {
  for setting in settings {
    if same_key(setting, entry) {
      return map(settings, |s| if_same_key(s, entry))
    }
  }
  return append(settings, entry)
}

fn if_same_key(setting: Setting, entry: Setting) -> Setting {
  if same_key(setting, entry) {
    return entry
  }
  return setting
}

fn parse_config(lines: List[String]) -> Result[List[Setting], String] {
  var section = ""
  var settings = []
  for (i, raw) in enumerate(lines) {
    let line = trim(raw)
    if line != "" && first(split(line, "#")) != Some("") {
      let error_prefix = "line " + to_string(i + 1) + ": "
      let open_parts = split(line, "[")
      if first(open_parts) == Some("") {
        section = try parse_header(open_parts, error_prefix)
      } else {
        let parts = split(line, "=")
        if len(parts) < 2 {
          return Err(error_prefix + "missing =")
        }
        let raw_key = unwrap_or(first(parts), "")
        let key = trim(raw_key)
        if key == "" {
          return Err(error_prefix + "empty key")
        }
        let value = parts
          |> drop(1)
          |> join("=")
          |> trim()
        let entry = Setting { section: section, key: key, value: value }
        settings = upsert(settings, entry)
      }
    }
  }
  return Ok(settings)
}

