type Employee {
  name: String,
  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn employee_pay(emp: Employee) -> Int {
  if emp.hours <= 40 {
    return emp.hours * emp.rate_cents
  }
  let regular = 40 * emp.rate_cents
  let overtime_base = (emp.hours - 40) * emp.rate_cents
  var half = overtime_base / 2
  if overtime_base < 0 && overtime_base % 2 != 0 {
    half = half - 1
  }
  return regular + (overtime_base + half)
}

fn dept_total(dept: String, emps: List[Employee]) -> (String, Int) {
  return (dept, sum(map(emps, employee_pay)))
}

fn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {
  return emps
    |> group_by(|emp| emp.dept)
    |> map(|dept, members| dept_total(dept, members))
    |> sort_by(|pair| pair.0)
    |> sort_desc_by(|pair| pair.1)
}

