fn is_vowel(letter: String, previous: String, position: Int) -> Bool {
  if letter == "u" {
    return previous != "q"
  }
  if letter == "y" {
    return position > 0
  }
  return letter == "a" || letter == "e" || letter == "i" || letter == "o"
}

fn translate_word(word: String) -> String {
  let letters = filter(split(word, ""), |letter| letter != "")
  var previous = ""
  var prefix = ""
  for (position, letter) in enumerate(letters) {
    if is_vowel(letter, previous, position) {
      if position == 0 {
        return word + "way"
      }
      let suffix = join(drop(letters, position), "")
      return suffix + prefix + "ay"
    }
    prefix = prefix + letter
    previous = letter
  }
  return word + "ay"
}

fn pig_latin(s: String) -> String {
  if s == "" {
    return ""
  }
  return s
    |> split(" ")
    |> map(translate_word)
    |> join(" ")
