    return ch + to_string(count)
  }
  return ch
}

fn rle_compress(s: String) -> String {
  let chars = filter(split(s, ""), |ch| ch != "")
  var current = ""
  var count = 0
  var encoded = ""
  for ch in chars {
    if ch == current {
      count = count + 1
    } else {
      encoded = encoded + encode_run(current, count)
      current = ch
      count = 1
    }
  }
  encoded = encoded + encode_run(current, count)
  if str_len(encoded) < str_len(s) {
    return encoded
  }
  return s
}

