  | Arrive(plate: String, minute: Int)
  | Leave(plate: String, minute: Int)

type ParkingState {
  arrivals: Map[String, Option[Int]],
  totals: Map[String, Int],
}

fn stay_fee(arrival: Int, departure: Int) -> Int {
  if departure <= arrival {
    return 0
  }
  if arrival <= 0 && departure >= arrival + 271 {
    return 1000
  }
  let duration = departure - arrival
  if duration <= 30 {
    return 0
  }
  return 200 * min(5, 1 + (duration - 31) / 60)
}

fn record_arrival(state: ParkingState, plate: String, minute: Int) -> ParkingState {
  let arrival = unwrap_or(map_get(state.arrivals, plate), None)
  if arrival != None {
    return state
  }
  return ParkingState {
    arrivals: map_set(state.arrivals, plate, Some(minute)),
    totals: state.totals,
  }
}

fn finish_stay(state: ParkingState, plate: String, arrival: Int, departure: Int) -> ParkingState {
  let previous = unwrap_or(map_get(state.totals, plate), 0)
  let total = previous + stay_fee(arrival, departure)
  return ParkingState {
    arrivals: map_set(state.arrivals, plate, None),
    totals: map_set(state.totals, plate, total),
  }
}

fn record_departure(state: ParkingState, plate: String, minute: Int) -> ParkingState {
  let arrival = unwrap_or(map_get(state.arrivals, plate), None)
  return match arrival {
    Some(start) => finish_stay(state, plate, start, minute),
    None => state,
  }
}

