fn roman_symbol_value(symbol: String) -> Int {
  return match symbol {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn standard_roman(n: Int) -> String {
  let tokens = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
  ]
  var remaining = n
  var text = ""
  for (value, token) in tokens {
    while remaining >= value {
      text = text + token
      remaining = remaining - value
    }
  }
  return text
}

fn roman_to_int(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  let symbols = split(s, "")
  # The longest standard form in range is MMMDCCCLXXXVIII (15 symbols).
  let too_long = len(symbols) > 15
  var total = 0
  var previous = 0
  for symbol in symbols {
    let value = roman_symbol_value(symbol)
    if value == 0 {
      return Err("invalid character: " + symbol)
    }
    if !too_long {
      if previous < value {
        total = total - previous
      } else {
        total = total + previous
      }
      previous = value
    }
  }
  if too_long {
    return Err("not canonical")
  }
  total = total + previous
  if total < 1 || total > 3999 || s != standard_roman(total) {
    return Err("not canonical")
  }
  return Ok(total)
}

