fn sliding_window_max(xs: List[Int], k: Int) -> Result[List[Int], String] {
  if k < 1 {
    return Err("window must be positive")
  }
  let n = len(xs)
  if k > n {
    return Err("window larger than input")
  }
  var maxima = []
  for start in range(0, n - k + 1) {
    let window = take(drop(xs, start), k)
    var largest = unwrap_or(first(window), 0)
    for value in window {
      largest = max(largest, value)
    }
    maxima = append(maxima, largest)
  }
  return Ok(maxima)
}

