fn decode_card(card: String) -> (Int, String) {
  let ranks = ["2", "3", "4", "5", "6", "7", "8", "9", "T", "J", "Q", "K", "A"]
  for (rank, symbol) in enumerate(ranks) {
    for suit in ["C", "D", "H", "S"] {
      if card == symbol + suit {
        return (rank, suit)
      }
    }
  }
  return (-1, "")
}

fn poker_hand(cards: List[String]) -> String {
  if len(cards) != 5 || len(group_by(cards, |c| c)) != 5 {
    return "invalid"
  }
  let decoded = map(cards, decode_card)
  for (rank, _) in decoded {
    if rank == -1 {
      return "invalid"
    }
  }
  let ranks = map(decoded, |c| c.0)
  let groups = group_by(ranks, |r| r)
  let counts = map(groups, |g| len(g.1))
  let flush = len(group_by(decoded, |c| c.1)) == 1
  var straight = false
  if len(groups) == 5 {
    let ordered = sort_by(ranks, |r| r)
    let low = unwrap_or(first(ordered), 0)
    let high = unwrap_or(last(ordered), 0)
    straight = high - low == 4 || ordered == [0, 1, 2, 3, 12]
  }
  let pairs = len(filter(counts, |n| n == 2))
  let triple = contains(counts, 3)
  if straight && flush {
    return "straight flush"
  } else if contains(counts, 4) {
    return "four of a kind"
  } else if triple && pairs == 1 {
    return "full house"
  } else if flush {
    return "flush"
  } else if straight {
    return "straight"
  } else if triple {
    return "three of a kind"
  } else if pairs == 2 {
    return "two pair"
  } else if pairs == 1 {
    return "one pair"
  }
  return "high card"
}

