type Cmd =
  | Forward(steps: Int)
  | TurnLeft
  | TurnRight

fn advance(pos: (Int, Int), dir: Int, steps: Int, obs: List[(Int, Int)]) -> (Int, Int) {
  let delta = match dir {
    0 => (0, 1),
    1 => (1, 0),
    2 => (0, -1),
    _ => (-1, 0),
  }
  var current = pos
  var remaining = steps
  while remaining > 0 {
    let next = (current.0 + delta.0, current.1 + delta.1)
    if contains(obs, next) {
      break
    }
    current = next
    remaining = remaining - 1
  }
  return current
}

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var state = ((0, 0), 0)
  for cmd in cmds {
    state = match cmd {
      Forward(steps) => (advance(state.0, state.1, steps, obstacles), state.1),
      TurnLeft => (state.0, (state.1 + 3) % 4),
      TurnRight => (state.0, (state.1 + 1) % 4),
    }
  }
  let position = state.0
  let direction = match state.1 {
    0 => "N",
    1 => "E",
    2 => "S",
    _ => "W",
  }
  return (position.0, position.1, direction)
}

