type Expense {
  payer: String,
  amount_cents: Int,
}

fn empty_payments() -> List[(String, String, Int)] {
  return []
}

fn settle_debts(expenses: List[Expense], people: List[String]) -> List[(String, String, Int)] {
  var balances = map_from(map(people, |person| (person, 0)))
  var total = 0
  for expense in expenses {
    let paid = unwrap_or(map_get(balances, expense.payer), 0)
    balances = map_set(balances, expense.payer, paid + expense.amount_cents)
    total = total + expense.amount_cents
  }
  let count = len(people)
  var share = total / count
  var remainder = total % count
  if remainder < 0 {
    share = share - 1
    remainder = remainder + count
  }
  for (i, person) in enumerate(people) {
    var owed = share
    if i < remainder {
      owed = owed + 1
    }
    let paid = unwrap_or(map_get(balances, person), 0)
    balances = map_set(balances, person, paid - owed)
  }
  var payments = empty_payments()
  while true {
    var debtor = ""
    var creditor = ""
    var lowest = 0
    var highest = 0
    for person in people {
      let balance = unwrap_or(map_get(balances, person), 0)
      if balance < lowest {
        lowest = balance
        debtor = person
      } else if balance > highest {
        highest = balance
        creditor = person
      }
    }
    if lowest == 0 {
      break
    }
    let amount = min(-lowest, highest)
    payments = append(payments, (debtor, creditor, amount))
    balances = map_set(balances, debtor, lowest + amount)
    balances = map_set(balances, creditor, highest - amount)
  }
  return payments
}

