fn spiral_order(m: List[List[Int]]) -> List[Int] {
  var rows = m
  let top_row = unwrap_or(first(m), [])
  var width = len(top_row)
  var result = []
  while width > 0 && len(rows) > 0 {
    for row in rows {
      result = append(result, unwrap_or(first(row), 0))
    }
    rows = map(rows, |row| drop(row, 1))
    width = width - 1
    if width == 0 {
      break
    }
    for value in unwrap_or(last(rows), []) {
      result = append(result, value)
    }
    rows = take(rows, len(rows) - 1)
    if len(rows) == 0 {
      break
    }
    for row in reverse(rows) {
      result = append(result, unwrap_or(last(row), 0))
    }
    width = width - 1
    if width == 0 {
      break
    }
    rows = map(rows, |row| take(row, width))
    let top = unwrap_or(first(rows), [])
    for value in reverse(top) {
      result = append(result, value)
    }
    rows = drop(rows, 1)
  }
  return result
}

