  requires: width >= 1
{
  var lines = []
  var line = ""
  for word in split(s, " ") {
    if word != "" {
      if line == "" {
        line = word
      } else {
        let candidate = line + " " + word
        if str_len(candidate) <= width {
          line = candidate
        } else {
          lines = append(lines, line)
          line = word
        }
      }
    }
  }
  if line != "" {
    lines = append(lines, line)
  }
  return lines
}

