type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

type Snapshot {
  chars: List[String],
  cursor: Int,
}

type Editor {
  current: Snapshot,
  history: List[Snapshot],
}

fn save_edit(editor: Editor, chars: List[String], cursor: Int) -> Editor {
  let current = Snapshot { chars: chars, cursor: cursor }
  return Editor { current: current, history: append(editor.history, editor.current) }
}

fn insert_text(editor: Editor, text: String) -> Editor {
  let current = editor.current
  let inserted = filter(split(text, ""), |ch| ch != "")
  var chars = take(current.chars, current.cursor)
  for ch in inserted {
    chars = append(chars, ch)
  }
  for ch in drop(current.chars, current.cursor) {
    chars = append(chars, ch)
  }
  return save_edit(editor, chars, current.cursor + len(inserted))
}

fn delete_text(editor: Editor, n: Int) -> Editor {
  let current = editor.current
  let cursor = current.cursor - min(n, current.cursor)
  var chars = take(current.chars, cursor)
  for ch in drop(current.chars, current.cursor) {
    chars = append(chars, ch)
  }
  return save_edit(editor, chars, cursor)
}

fn move_to(editor: Editor, cursor: Int) -> Editor {
  let current = Snapshot { chars: editor.current.chars, cursor: cursor }
  return Editor { current: current, history: editor.history }
}

fn move_right(editor: Editor, n: Int) -> Editor {
  let current = editor.current
  let remaining = len(current.chars) - current.cursor
  return move_to(editor, current.cursor + min(n, remaining))
}

fn undo_edit(editor: Editor) -> Editor {
  return match last(editor.history) {
    None => editor,
    Some(saved) => Editor {
      current: saved,
      history: take(editor.history, len(editor.history) - 1),
    },
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  let initial = Snapshot { chars: [], cursor: 0 }
  var editor = Editor { current: initial, history: [] }
  for op in ops {
    editor = match op {
      Insert(text) => insert_text(editor, text),
      Delete(n) => delete_text(editor, n),
      Left(n) => move_to(editor, editor.current.cursor - min(n, editor.current.cursor)),
      Right(n) => move_right(editor, n),
      Undo => undo_edit(editor),
    }
  }
  return join(editor.current.chars, "")
}

