type Machine {
  credit: Int,
  messages: List[String],
}

fn accept_coin(machine: Machine, cents: Int) -> Machine {
  if cents == 5 || cents == 10 || cents == 25 || cents == 100 {
    return Machine { credit: machine.credit + cents, messages: machine.messages }
  }
  let message = "reject " + to_string(cents)
  return Machine { credit: machine.credit, messages: append(machine.messages, message) }
}

fn select_item(machine: Machine, price: Int) -> Machine {
  if machine.credit >= price {
    let change = machine.credit - price
    let message = "vend " + to_string(price) + " change " + to_string(change)
    return Machine { credit: 0, messages: append(machine.messages, message) }
  }
  let message = "insufficient " + to_string(machine.credit)
  return Machine { credit: machine.credit, messages: append(machine.messages, message) }
}

fn refund_credit(machine: Machine) -> Machine {
  if machine.credit > 0 {
    let message = "refund " + to_string(machine.credit)
    return Machine { credit: 0, messages: append(machine.messages, message) }
  }
  return machine
}

fn vending_machine(events: List[Event]) -> List[String] {
  var machine = Machine { credit: 0, messages: [] }
  for event in events {
    machine = match event {
      Coin(cents) => accept_coin(machine, cents),
      Select(price) => select_item(machine, price),
      Refund => refund_credit(machine),
    }
  }
  let final_machine = refund_credit(machine)
  return final_machine.messages
}

