fn decode_row(row: String) -> List[String] {
  let marks = ["X", "O", "."]
  for a in marks {
    for b in marks {
      for c in marks {
        if row == a + b + c {
          return [a, b, c]
        }
      }
    }
  }
  return []
}

fn has_line(cells: Map[Int, String], mark: String) -> Bool {
  let lines = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6],
  ]
  for line in lines {
    let matches = filter(line, |i| map_get(cells, i) == Some(mark))
    if len(matches) == 3 {
      return true
    }
  }
  return false
}

fn tic_tac_toe(board: List[String]) -> String {
  if len(board) != 3 {
    return "invalid"
  }
  var cells = []
  for row in board {
    let decoded = decode_row(row)
    if len(decoded) != 3 {
      return "invalid"
    }
    for mark in decoded {
      cells = append(cells, mark)
    }
  }
  let xs = len(filter(cells, |mark| mark == "X"))
  let os = len(filter(cells, |mark| mark == "O"))
  if xs != os && xs != os + 1 {
    return "invalid"
  }
  let indexed = map_from(enumerate(cells))
  let x_wins = has_line(indexed, "X")
  let o_wins = has_line(indexed, "O")
  if x_wins && o_wins || x_wins && xs != os + 1 || o_wins && xs != os {
    return "invalid"
  }
  if x_wins {
    return "X wins"
  }
  if o_wins {
    return "O wins"
  }
  if xs + os == 9 {
    return "draw"
  }
  return "in progress"
}

