def anagram_groups(words: list[str]) -> list[list[str]]:
    groups: dict[str, list[str]] = {}
    for word in words:
        key = "".join(sorted(word))
        groups.setdefault(key, []).append(word)
    return [group for group in groups.values() if len(group) >= 2]

type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn stack_need(instr: Instr) -> Int {
  return match instr {
    Pop => 1,
    Dup => 1,
    Print => 1,
    Jz(_) => 1,
    Add => 2,
    Sub => 2,
    Mul => 2,
    Swap => 2,
    _ => 0,
  }
}

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  var stack = []
  var output = []
  var pc = 0
  var steps = 0
  let size = len(prog)
  while pc < size {
    if steps == 1000 {
      return Err("step limit exceeded")
    }
    let remaining = drop(prog, pc)
    let instr = unwrap_or(first(remaining), Halt)
    steps = steps + 1
    if instr == Halt {
      break
    }
    let need = stack_need(instr)
    let depth = len(stack)
    if depth < need {
      return Err("stack underflow at " + to_string(pc))
    }
    let target = match instr {
      Jz(t) => t,
      Jmp(t) => t,
      _ => pc,
    }
    if target < 0 || target >= size {
      return Err("bad jump at " + to_string(pc))
    }
    let b = unwrap_or(last(stack), 0)
    if instr == Print {
      output = append(output, b)
    }
    if need == 2 {
      let without_top = take(stack, depth - 1)
      let a = unwrap_or(last(without_top), 0)
      let rest = take(stack, depth - 2)
      if instr == Swap {
        stack = append(append(rest, b), a)
      } else {
        let value = match instr {
          Add => a + b,
          Sub => a - b,
          _ => a * b,
        }
        stack = append(rest, value)
      }
    } else if need == 1 {
      if instr == Dup {
        stack = append(stack, b)
      } else {
        stack = take(stack, depth - 1)
      }
    } else {
      stack = match instr {
        Push(n) => append(stack, n),
        _ => stack,
      }
    }
    pc = match (instr, b) {
      (Jmp(t), _) => t,
      (Jz(t), 0) => t,
      _ => pc + 1,
    }
  }
  return Ok(output)
}

