fn rle_digit(ch: String) -> Int {
  if ch < "0" || ch > "9" {
    return -1
  }
  return unwrap_or(parse_int(ch), -1)
}

fn rle_extend(run: String, ch: String, digit: Int) -> String {
  let twice = run + run
  let four = twice + twice
  let five = four + run
  var expanded = five + five
  var remaining = digit
  while remaining > 0 {
    expanded = expanded + ch
    remaining = remaining - 1
  }
  return expanded
}

fn rle_decode(s: String) -> Result[String, String] {
  let chars = filter(split(s, ""), |ch| ch != "")
  var character = ""
  var has_count = false
  for ch in chars {
    let digit = rle_digit(ch)
    if digit < 0 {
      character = ch
      has_count = false
    } else {
      if character == "" {
        return Err("missing character before count")
      }
      if !has_count && digit == 0 {
        return Err("bad count for " + character)
      }
      has_count = true
    }
  }
  var chunks = [""]
  var run = ""
  character = ""
  for ch in append(chars, "") {
    let digit = rle_digit(ch)
    if digit < 0 {
      if run == "" {
        chunks = append(chunks, character)
      } else {
        chunks = append(chunks, run)
      }
      character = ch
      run = ""
    } else {
      run = rle_extend(run, character, digit)
    }
  }
  return Ok(join(chunks, ""))
}

