def bracket_depth(s: str) -> Ok[int] | Err:
    matching_open = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []
    max_depth = 0

    for index, char in enumerate(s):
        if char in "([{":
            stack.append(char)
            max_depth = max(max_depth, len(stack))
        elif char in matching_open:
            if not stack or stack[-1] != matching_open[char]:
                return {"ok": False, "error": f"mismatch at {index}"}
