  if digits == "" {
    return Ok(Num(0))
  }
  return match parse_int(digits) {
    Some(value) => Ok(Num(value)),
    None => Err("integer out of range at " + to_string(start)),
  }
}

fn tokenize(s: String) -> Result[List[Token], String] {
  let chars = filter(split(s, ""), |c| c != "")
  let by_pos = map_from(enumerate(chars))
  let double_symbols = ["==", "<=", ">=", "!="]
  let single_symbols = ["+", "-", "*", "/", "=", "<", ">", "(", ")", ","]
  var tokens = []
  var pos = 0
  while pos < len(chars) {
    let c = char_at(by_pos, pos)
    if c == " " {
      pos = pos + 1
    } else if is_digit(c) {
      let start = pos
      var digits = ""
      var digit = c
      while is_digit(digit) {
        if digits != "" || digit != "0" {
          digits = digits + digit
        }
        pos = pos + 1
        digit = char_at(by_pos, pos)
      }
      let token = try number_token(digits, start)
      tokens = append(tokens, token)
    } else if is_ident_start(c) {
      var name = c
      pos = pos + 1
      var next = char_at(by_pos, pos)
      while is_ident_part(next) {
        name = name + next
        pos = pos + 1
        next = char_at(by_pos, pos)
      }
      tokens = append(tokens, Ident(name))
    } else {
      let pair = c + char_at(by_pos, pos + 1)
      if contains(double_symbols, pair) {
        tokens = append(tokens, Sym(pair))
        pos = pos + 2
      } else if contains(single_symbols, c) {
        tokens = append(tokens, Sym(c))
        pos = pos + 1
      } else {
        return Err("unexpected character: " + c + " at " + to_string(pos))
      }
    }
  }
  return Ok(tokens)
}

