from unicodedata import decimal


def _version_key(version: str) -> list[tuple[int, str]] | None:
    parts = version.split(".")
    if len(parts) > 4 or not all(part.isdecimal() for part in parts):
        return None

    digit_value: Callable[[str], int] = decimal
    key: list[tuple[int, str]] = []
    for part in parts:
        digits = "".join(str(digit_value(char)) for char in part)
        significant = digits.lstrip("0")
        key.append((len(significant), significant))

    key.extend([(0, "")] * (4 - len(key)))
    return key


def compare_versions(a: str, b: str) -> Ok[int] | Err:
    a_key = _version_key(a)
    if a_key is None:
        return {"ok": False, "error": "bad version: " + a}

    b_key = _version_key(b)
    if b_key is None:
        return {"ok": False, "error": "bad version: " + b}

    return {"ok": True, "value": (a_key > b_key) - (a_key < b_key)}

from __future__ import annotations


def count_islands(grid: list[str]) -> tuple[int, int]:
    if not grid:
        return (0, 0)

    height = len(grid)
    width = len(grid[0])
    visited: set[tuple[int, int]] = set()
    islands = 0
    largest = 0

    for row in range(height):
        for col in range(width):
            if grid[row][col] != "#" or (row, col) in visited:
                continue

            islands += 1
            size = 0
            stack: list[tuple[int, int]] = [(row, col)]
            visited.add((row, col))

            while stack:
                r, c = stack.pop()
                size += 1
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (
                        0 <= nr < height
                        and 0 <= nc < width
                        and grid[nr][nc] == "#"
                        and (nr, nc) not in visited
                    ):
                        visited.add((nr, nc))
                        stack.append((nr, nc))

            largest = max(largest, size)

    return (islands, largest)

