def bowling_score(rolls: list[int]) -> Ok[int] | Err:
    if any(roll < 0 or roll > 10 for roll in rolls):
        return {"ok": False, "error": "invalid roll"}

    count = len(rolls)
    index = 0
    scoring_ranges: list[tuple[int, int]] = []

    for frame in range(1, 10):
        if index == count:
            return {"ok": False, "error": "incomplete game"}

        first = rolls[index]
        if first == 10:
            scoring_ranges.append((index, index + 3))
            index += 1
        else:
            if index + 1 == count:
                return {"ok": False, "error": "incomplete game"}
            pins = first + rolls[index + 1]
            if pins > 10:
                return {"ok": False, "error": f"too many pins in frame {frame}"}
            scoring_ranges.append((index, index + (3 if pins == 10 else 2)))
            index += 2

    if count - index < 2:
        return {"ok": False, "error": "incomplete game"}

    first, second = rolls[index], rolls[index + 1]
    tenth_score = first + second
    end = index + 2

    if first != 10 and tenth_score > 10:
        return {"ok": False, "error": "too many pins in frame 10"}

    if first == 10 or tenth_score == 10:
        if end == count:
            return {"ok": False, "error": "incomplete game"}
        third = rolls[end]
        if first == 10 and second != 10 and second + third > 10:
            return {"ok": False, "error": "too many pins in frame 10"}
        tenth_score += third
        end += 1

    if end < count:
        return {"ok": False, "error": "too many rolls"}

    total = tenth_score + sum(
        sum(rolls[start:stop]) for start, stop in scoring_ranges
    )
    return {"ok": True, "value": total}

