from typing import Literal, TypedDict

class Digit(TypedDict):
    kind: Literal["Digit"]
    d: int

class Enter(TypedDict):
    kind: Literal["Enter"]

class Clear(TypedDict):
    kind: Literal["Clear"]

Key = Digit | Enter | Clear


def door_lock(code: str, events: list[Key]) -> str:
    state: Literal["locked", "open", "blocked"] = "locked"
    buffer: str = ""
    failures: int = 0
    capacity: int = len(code)

    for event in events:
        if state == "blocked":
            break

        if state == "open":
            if event["kind"] == "Enter":
                state = "locked"
            continue

        if event["kind"] == "Digit":
            buffer = (buffer + str(event["d"]))[-capacity:]
        elif event["kind"] == "Clear":
            buffer = ""
        else:
            if buffer == code:
                state = "open"
                failures = 0
            else:
                failures += 1
                if failures == 3:
                    state = "blocked"
            buffer = ""

    return state

