def edit_script_distance(a: str, b: str) -> int:
    if len(b) > len(a):
        a, b = b, a

    width = len(b)
    two_back: list[int] = [0] * (width + 1)
    previous = list(range(width + 1))

    for i, char_a in enumerate(a, start=1):
        current = [i] + [0] * width
        for j, char_b in enumerate(b, start=1):
            cost = min(
                previous[j] + 1,
                current[j - 1] + 1,
                previous[j - 1] + int(char_a != char_b),
            )
            if i >= 2 and j >= 2 and char_a == b[j - 2] and a[i - 2] == char_b:
                cost = min(cost, two_back[j - 2] + 1)
            current[j] = cost
        two_back, previous = previous, current

    return previous[width]

