def _invalid(index: int) -> Err:
    return {"ok": False, "error": f"invalid at {index}"}


def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    text = s.replace(" ", "")
    if not text.startswith("["):
        return _invalid(0)

    values: list[int] = []
    depth = max_depth = 1
    index = 1
    state: Literal["first", "element", "separator"] = "first"

    while index < len(text):
        char = text[index]
        if char == "]" and state != "element":
            depth -= 1
            index += 1
            if depth == 0:
                if index != len(text):
                    return _invalid(index)
                return {"ok": True, "value": (values, max_depth)}
            state = "separator"
        elif state == "separator":
            if char != ",":
                return _invalid(index)
            index += 1
            state = "element"
        elif char == "[":
            depth += 1
            max_depth = max(max_depth, depth)
            index += 1
            state = "first"
        else:
            negative = char == "-"
            if negative:
                index += 1
            if index == len(text) or not text[index].isdecimal():
                return _invalid(index)

            value = 0
            while index < len(text) and text[index].isdecimal():
                value = value * 10 + int(text[index])
                index += 1
            values.append(-value if negative else value)
            state = "separator"

    return _invalid(index)

from __future__ import annotations


def glob_match(pattern: str, s: str) -> bool:
    p = 0
    i = 0
    after_star = -1
    star_end = 0

    while i < len(s):
        if p < len(pattern):
            char = pattern[p]
            if char == "*":
                p += 1
                after_star = p
                star_end = i
                continue
            if char == "\\":
                next_p = p + 1
                if next_p < len(pattern):
                    char = pattern[next_p]
                    next_p += 1
                if char == s[i]:
                    p = next_p
                    i += 1
                    continue
            elif char == "?" or char == s[i]:
                p += 1
                i += 1
                continue

        if after_star == -1:
            return False

        # Let the most recent star consume one more character and retry.
        star_end += 1
        i = star_end
        p = after_star

    while p < len(pattern) and pattern[p] == "*":
        p += 1
    return p == len(pattern)

