    def record(team: str, scored: int, conceded: int) -> None:
        points, difference, goals_for = totals.get(team, (0, 0, 0))
        earned = 3 if scored > conceded else 1 if scored == conceded else 0
        totals[team] = (
            points + earned,
            difference + scored - conceded,
            goals_for + scored,
        )

    for match in matches:
        home_goals = match["home_goals"]
        away_goals = match["away_goals"]
        record(match["home"], home_goals, away_goals)
        record(match["away"], away_goals, home_goals)

    rows = [
        (team, points, difference, goals_for)
        for team, (points, difference, goals_for) in totals.items()
    ]
    return sorted(rows, key=lambda row: (-row[1], -row[2], -row[3], row[0]))

from __future__ import annotations


def life_step(grid: list[str], steps: int) -> list[str]:
    if not grid:
        return []

    height = len(grid)
    width = len(grid[0])
    current = grid.copy()

    for _ in range(steps):
        next_grid: list[str] = []
        for row in range(height):
            cells: list[str] = []
            for col in range(width):
                neighbors = 0
                for r in range(max(0, row - 1), min(height, row + 2)):
                    for c in range(max(0, col - 1), min(width, col + 2)):
                        if (r != row or c != col) and current[r][c] == "#":
                            neighbors += 1

                alive = neighbors == 3 or (
                    neighbors == 2 and current[row][col] == "#"
                )
                cells.append("#" if alive else ".")
            next_grid.append("".join(cells))
        current = next_grid

    return current

