def max_subarray(xs: list[int]) -> tuple[int, int, int] | None:
    if not xs:
        return None

    run_sum = best_sum = xs[0]
    run_start = best_start = best_end = 0

    for end in range(1, len(xs)):
        if run_sum < 0:
            run_sum = xs[end]
            run_start = end
        else:
            run_sum += xs[end]

        if run_sum > best_sum:
            best_sum = run_sum
            best_start = run_start
            best_end = end

    return best_sum, best_start, best_end

