from typing import TypedDict

class Contact(TypedDict):
    name: str
    email: str
    phone: str


def merge_contacts(contacts: list[Contact]) -> list[Contact]:
    parent = list(range(len(contacts)))
    size = [1] * len(contacts)

    def find(index: int) -> int:
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left: int, right: int) -> None:
        left, right = find(left), find(right)
        if left == right:
            return
        if size[left] < size[right]:
            left, right = right, left
        parent[right] = left
        size[left] += size[right]

    by_email: dict[str, int] = {}
    by_phone: dict[str, int] = {}
    for index, contact in enumerate(contacts):
        email = contact["email"].strip()
        phone = "".join(char for char in contact["phone"] if "0" <= char <= "9")
        if email:
            union(index, by_email.setdefault(email, index))
        if phone:
            union(index, by_phone.setdefault(phone, index))

    merged: dict[int, Contact] = {}
    for index, contact in enumerate(contacts):
        root = find(index)
        current = merged.get(root)
        if current is None:
            merged[root] = contact.copy()
            continue
        if current["name"] == "":
            current["name"] = contact["name"]
        if current["email"] == "":
            current["email"] = contact["email"]
        if current["phone"] == "":
            current["phone"] = contact["phone"]

    return list(merged.values())

