def order_states(events: list[OrderEvent]) -> Ok[list[tuple[str, str]]] | Err:
    states: dict[str, str] = {}

    for event in events:
        kind = event["kind"]
        order_id = event["id"]
        state = states.get(order_id)

        if kind == "Create":
            if state is not None:
                return {"ok": False, "error": f"duplicate order: {order_id}"}
            states[order_id] = "created"
            continue

        if state is None:
            return {"ok": False, "error": f"unknown order: {order_id}"}

        if kind == "Pay" and state == "created":
            states[order_id] = "paid"
        elif kind == "Ship" and state == "paid":
            states[order_id] = "shipped"
        elif kind == "Cancel" and state in ("created", "paid"):
            states[order_id] = "cancelled"
        else:
            return {"ok": False, "error": f"cannot {kind.lower()} {order_id} from {state}"}

    return {"ok": True, "value": sorted(states.items())}

