def _truncate_division(left: int, right: int) -> int:
    magnitude = abs(left) // abs(right)
    return -magnitude if (left < 0) != (right < 0) else magnitude


_PRECEDENCE: dict[str, int] = {"+": 1, "-": 1, "*": 2, "/": 2}
_OPERATIONS: dict[str, Callable[[int, int], int]] = {
    "+": lambda left, right: left + right,
    "-": lambda left, right: left - right,
    "*": lambda left, right: left * right,
    "/": _truncate_division,
}


def eval_expr(s: str) -> Ok[int] | Err:
    text = s.replace(" ", "")
    postfix: list[str] = []
    operators: list[str] = []
    needs_factor = True
    index = 0

    while index < len(text):
        char = text[index]
        if needs_factor:
            if char.isdecimal():
                start = index
                index += 1
                while index < len(text) and text[index].isdecimal():
                    index += 1
                postfix.append(text[start:index])
                needs_factor = False
                continue
            if char == "(":
                operators.append(char)
                index += 1
                continue
        elif char in _PRECEDENCE:
            while (
                operators
                and operators[-1] != "("
                and _PRECEDENCE[operators[-1]] >= _PRECEDENCE[char]
            ):
                postfix.append(operators.pop())
            operators.append(char)
            needs_factor = True
            index += 1
            continue
        elif char == ")":
            while operators and operators[-1] != "(":
                postfix.append(operators.pop())
            if operators:
                operators.pop()
                index += 1
                continue

        return {"ok": False, "error": "unexpected character: " + char}

    if needs_factor or "(" in operators:
        return {"ok": False, "error": "unexpected end"}
    postfix.extend(reversed(operators))

    values: list[int] = []
    for token in postfix:
        if token in _OPERATIONS:
            right = values.pop()
            left = values.pop()
            if token == "/" and right == 0:
                return {"ok": False, "error": "division by zero"}
            values.append(_OPERATIONS[token](left, right))
        else:
            value = 0
            for digit in token:
                value = value * 10 + int(digit)
            values.append(value)

    return {"ok": True, "value": values.pop()}

from __future__ import annotations


def min_coins(coins: list[int], amount: int) -> tuple[int, list[int]] | None:
    if amount < 0:
        return None
    if amount == 0:
        return (0, [])

    values = sorted({coin for coin in coins if coin <= amount})
    if not values:
        return None

    unreachable = amount + 1
    counts = [0] + [unreachable] * amount
    choices = [0] * (amount + 1)

    for total in range(1, amount + 1):
        for coin in values:
            if coin > total:
                break
            candidate = counts[total - coin] + 1
            if candidate <= counts[total]:
                counts[total] = candidate
                choices[total] = coin

    if counts[amount] == unreachable:
        return None

    used: list[int] = []
    remaining = amount
    while remaining > 0:
        coin = choices[remaining]
        used.append(coin)
        remaining -= coin

    return (counts[amount], used)

