    key: str
    value: str


def parse_config(lines: list[str]) -> Ok[list[Setting]] | Err:
    section = ""
    settings: dict[tuple[str, str], Setting] = {}

    for number, raw_line in enumerate(lines, start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        if line.startswith("["):
            header = line[1:-1].strip()
            if not line.endswith("]") or not header:
                return {"ok": False, "error": f"line {number}: bad header"}
            section = header
            continue

        key_text, separator, value_text = line.partition("=")
        if not separator:
            return {"ok": False, "error": f"line {number}: missing ="}

        key = key_text.strip()
        if not key:
            return {"ok": False, "error": f"line {number}: empty key"}

        settings[section, key] = {
            "section": section,
            "key": key,
            "value": value_text.strip(),
        }

    return {"ok": True, "value": list(settings.values())}

