from unicodedata import decimal


_digit_value: Callable[[str], int] = decimal
_units: dict[str, tuple[int, int]] = {
    "h": (0, 3600),
    "m": (1, 60),
    "s": (2, 1),
}


def parse_duration(s: str) -> Ok[int] | Err:
    if not s:
        return {"ok": False, "error": "empty"}

    total = 0
    number = 0
    has_digits = False
    last_rank = -1

    for char in s:
        if char.isdecimal():
            number = number * 10 + _digit_value(char)
            has_digits = True
            continue

        unit = _units.get(char)
        if unit is None:
            return {"ok": False, "error": f"unknown unit: {char}"}
        if not has_digits:
            return {"ok": False, "error": f"missing number before {char}"}

        rank, multiplier = unit
        if rank <= last_rank:
            return {"ok": False, "error": f"unit out of order: {char}"}

        total += number * multiplier
        last_rank = rank
        number = 0
        has_digits = False

    if has_digits:
        return {"ok": False, "error": "missing unit"}
    return {"ok": True, "value": total}

