Cmd = Forward | TurnLeft | TurnRight


def robot_walk(
    cmds: list[Cmd], obstacles: list[tuple[int, int]]
) -> tuple[int, int, str]:
    blocked = set(obstacles)
    directions = ("N", "E", "S", "W")
    offsets = ((0, 1), (1, 0), (0, -1), (-1, 0))
    x, y = 0, 0
    heading = 0

    for cmd in cmds:
        if cmd["kind"] == "TurnLeft":
            heading = (heading - 1) % 4
        elif cmd["kind"] == "TurnRight":
            heading = (heading + 1) % 4
        else:
            dx, dy = offsets[heading]
            for _ in range(cmd["steps"]):
                next_cell = (x + dx, y + dy)
                if next_cell in blocked:
                    break
                x, y = next_cell

    return x, y, directions[heading]

