def session_totals(events: list[Session]) -> list[tuple[str, int]]:
    if not events:
        return []

    totals: dict[str, int] = {}
    open_sessions: dict[str, int] = {}

    for event in events:
        user = event["user"]
        time = event["time"]
        totals.setdefault(user, 0)

        if event["kind"] == "login":
            open_sessions.setdefault(user, time)
        else:
            start = open_sessions.pop(user, None)
            if start is not None:
                totals[user] += time - start

    end = events[-1]["time"]
    for user, start in open_sessions.items():
        totals[user] += end - start

    return sorted(totals.items())

