def rle_decode(s: str) -> Ok[str] | Err:
    if s and "0" <= s[0] <= "9":
        return {"ok": False, "error": "missing character before count"}

    groups: list[tuple[str, int, int]] = []
    i = 0
    while i < len(s):
        character = s[i]
        i += 1
        start = i
        if i < len(s) and s[i] == "0":
            return {"ok": False, "error": f"bad count for {character}"}
        while i < len(s) and "0" <= s[i] <= "9":
            i += 1
        groups.append((character, start, i))

    parts: list[str] = []
    for character, start, end in groups:
        count = 1
        if start < end:
            count = 0
            for j in range(start, end):
                count = count * 10 + (ord(s[j]) - ord("0"))
        parts.append(character * count)

    return {"ok": True, "value": "".join(parts)}

from __future__ import annotations


def poker_hand(cards: list[str]) -> str:
    if len(cards) != 5:
        return "invalid"

    ranks = "23456789TJQKA"
    seen: set[str] = set()
    suits: set[str] = set()
    counts: dict[int, int] = {}

    for card in cards:
        if len(card) != 2 or card[0] not in ranks or card[1] not in "CDHS":
            return "invalid"
        if card in seen:
            return "invalid"

        seen.add(card)
        suits.add(card[1])
        rank = ranks.index(card[0])
        counts[rank] = counts.get(rank, 0) + 1

    ordered_ranks = sorted(counts)
    straight = len(ordered_ranks) == 5 and (
        ordered_ranks[-1] - ordered_ranks[0] == 4
        or ordered_ranks == [0, 1, 2, 3, 12]
    )
    flush = len(suits) == 1
    groups = sorted(counts.values(), reverse=True)

    if straight and flush:
        return "straight flush"
    if groups[0] == 4:
        return "four of a kind"
    if groups == [3, 2]:
        return "full house"
    if flush:
        return "flush"
    if straight:
        return "straight"
    if groups[0] == 3:
        return "three of a kind"
    if groups == [2, 2, 1]:
        return "two pair"
    if groups[0] == 2:
        return "one pair"
    return "high card"

