_SYMBOL_VALUES: dict[str, int] = {
    "I": 1,
    "V": 5,
    "X": 10,
    "L": 50,
    "C": 100,
    "D": 500,
    "M": 1000,
}

_STANDARD_TOKENS: tuple[tuple[int, str], ...] = (
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
)


def _standard_form(value: int) -> str:
    parts: list[str] = []
    for amount, token in _STANDARD_TOKENS:
        count, value = divmod(value, amount)
        parts.append(token * count)
    return "".join(parts)


def roman_to_int(s: str) -> Ok[int] | Err:
    if not s:
        return {"ok": False, "error": "empty"}

    total = 0
    previous = 0
    for character in s:
        current = _SYMBOL_VALUES.get(character)
        if current is None:
            return {"ok": False, "error": f"invalid character: {character}"}
        total += -previous if previous < current else previous
        previous = current
    total += previous

    if not 1 <= total <= 3999 or s != _standard_form(total):
        return {"ok": False, "error": "not canonical"}
    return {"ok": True, "value": total}

from __future__ import annotations
from typing import TypedDict

class Expense(TypedDict):
    payer: str
    amount_cents: int


def settle_debts(
    expenses: list[Expense], people: list[str]
) -> list[tuple[str, str, int]]:
    total = sum(expense["amount_cents"] for expense in expenses)
    share, remainder = divmod(total, len(people))
    balances = {
        person: -share - (1 if index < remainder else 0)
        for index, person in enumerate(people)
    }

    for expense in expenses:
        balances[expense["payer"]] += expense["amount_cents"]

    payments: list[tuple[str, str, int]] = []
    while True:
        debtor = min(people, key=balances.__getitem__)
        if balances[debtor] == 0:
            return payments

        creditor = max(people, key=balances.__getitem__)
        amount = min(-balances[debtor], balances[creditor])
        balances[debtor] += amount
        balances[creditor] -= amount
        payments.append((debtor, creditor, amount))

