def tennis_score(points: str) -> str:
    a = 0
    b = 0

    for index, point in enumerate(points):
        if point == "A":
            a += 1
        elif point == "B":
            b += 1
        else:
            return "error: bad point"

        if max(a, b) >= 4 and abs(a - b) >= 2:
            if index + 1 < len(points):
                return "error: point after game"
            return "game A" if a > b else "game B"

    if a >= 3 and b >= 3:
        if a == b:
            return "deuce"
        return "advantage A" if a > b else "advantage B"

