def wrap_text(s: str, width: int) -> list[str]:
    lines: list[str] = []
    current: list[str] = []
    length = 0

    for word in s.split(" "):
        if not word:
            continue

        if current and length + 1 + len(word) > width:
            lines.append(" ".join(current))
            current = []
            length = 0

        if current:
            length += 1
        current.append(word)
        length += len(word)

    if current:
        lines.append(" ".join(current))

    return lines

