            cents = event["cents"]
            if cents in (5, 10, 25, 100):
                credit += cents
            else:
                messages.append(f"reject {cents}")
        elif event["kind"] == "Select":
            price = event["price"]
            if credit >= price:
                messages.append(f"vend {price} change {credit - price}")
