    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt


def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    pc = 0
    steps = 0
    size = len(prog)

    while pc < size:
        if steps == 1000:
            return {"ok": False, "error": "step limit exceeded"}
        steps += 1

        instr = prog[pc]
        kind = instr["kind"]
        required = 0
        if kind in ("Pop", "Dup", "Print", "Jz"):
            required = 1
        elif kind in ("Add", "Sub", "Mul", "Swap"):
            required = 2
        if len(stack) < required:
            return {"ok": False, "error": f"stack underflow at {pc}"}

        next_pc = pc + 1
        if instr["kind"] == "Jz" or instr["kind"] == "Jmp":
            target = instr["target"]
            if not 0 <= target < size:
                return {"ok": False, "error": f"bad jump at {pc}"}
            if instr["kind"] == "Jmp" or stack.pop() == 0:
                next_pc = target
        elif instr["kind"] == "Push":
            stack.append(instr["n"])
        elif kind == "Pop":
            stack.pop()
        elif kind in ("Add", "Sub", "Mul"):
            b = stack.pop()
            a = stack.pop()
            if kind == "Add":
                stack.append(a + b)
            elif kind == "Sub":
                stack.append(a - b)
            else:
                stack.append(a * b)
        elif kind == "Dup":
            stack.append(stack[-1])
        elif kind == "Swap":
            stack[-2], stack[-1] = stack[-1], stack[-2]
        elif kind == "Print":
            output.append(stack.pop())
        elif kind == "Halt":
            break

        pc = next_pc

    return {"ok": True, "value": output}

