Token = Num | Ident | Sym


def _is_ident_start(ch: str) -> bool:
    return "a" <= ch <= "z" or ch == "_"


def tokenize(s: str) -> Ok[list[Token]] | Err:
    tokens: list[Token] = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == " ":
            i += 1
        elif ch.isdecimal():
            value = 0
            while i < len(s) and s[i].isdecimal():
                value = value * 10 + int(s[i])
                i += 1
            tokens.append(Num(kind="Num", value=value))
        elif _is_ident_start(ch):
            start = i
            i += 1
            while i < len(s) and (_is_ident_start(s[i]) or s[i].isdecimal()):
                i += 1
            tokens.append(Ident(kind="Ident", name=s[start:i]))
        else:
            pair = s[i:i + 2]
            if pair in ("==", "<=", ">=", "!="):
                tokens.append(Sym(kind="Sym", text=pair))
                i += 2
            elif ch in "+-*/=<>() ,".replace(" ", ""):
                tokens.append(Sym(kind="Sym", text=ch))
                i += 1
            else:
                return {"ok": False, "error": f"unexpected character: {ch} at {i}"}
    return {"ok": True, "value": tokens}

