fn bracket_depth(s: String) -> Result[Int, String] {
  var expected = []
  var deepest = 0
  for (i, ch) in enumerate(split(s, "")) {
    let closer = match ch {
      "(" => ")",
      "[" => "]",
      "{" => "}",
      _ => "",
    }
    if closer != "" {
      expected = append(expected, closer)
      deepest = max(deepest, len(expected))
    } else if ch == ")" || ch == "]" || ch == "}" {
      if last(expected) != Some(ch) {
        return Err("mismatch at " + to_string(i))
      }
      expected = take(expected, len(expected) - 1)
    }
  }
  if len(expected) != 0 {
    return Err("unclosed at end")
  }
  return Ok(deepest)
}

