fn bowling_score(rolls: List[Int]) -> Result[Int, String] {
  for pins in rolls {
    if pins < 0 || pins > 10 {
      return Err("invalid roll")
    }
  }
  var remaining = rolls
  var score = 0
  for frame in range(1, 10) {
    let opening = try required_roll(remaining)
    remaining = drop(remaining, 1)
    if opening == 10 {
      let bonus_rolls = take(remaining, 2)
      score = score + 10 + sum(bonus_rolls)
    } else {
      let second = try required_roll(remaining)
      remaining = drop(remaining, 1)
      let pins = opening + second
      if pins > 10 {
        return Err("too many pins in frame " + to_string(frame))
      }
      score = score + pins
      if pins == 10 {
        score = score + unwrap_or(first(remaining), 0)
      }
    }
  }
  let opening = try required_roll(remaining)
  remaining = drop(remaining, 1)
  let second = try required_roll(remaining)
  remaining = drop(remaining, 1)
  let pins = opening + second
  if opening != 10 && pins > 10 {
    return Err("too many pins in frame 10")
  }
  score = score + pins
  if opening == 10 || pins == 10 {
    let third = try required_roll(remaining)
    remaining = drop(remaining, 1)
    if opening == 10 && second != 10 && second + third > 10 {
      return Err("too many pins in frame 10")
    }
    score = score + third
  }
  if len(remaining) > 0 {
    return Err("too many rolls")
  }
  return Ok(score)
}

