fn caesar_shift(s: String, k: Int) -> String {
  let alphabet = split("a b c d e f g h i j k l m n o p q r s t u v w x y z", " ")
  let shift = (k % 26 + 26) % 26
  var rotated = drop(alphabet, shift)
  for letter in take(alphabet, shift) {
    rotated = append(rotated, letter)
  }
  let shifts = map_from(zip(alphabet, rotated))
  let chars = split(s, "")
  return join(map(chars, |c| unwrap_or(map_get(shifts, c), c)), "")
}

