fn deps_placed(deps: List[String], placed: Map[String, Bool]) -> Bool {
  for dep in deps {
    if !unwrap_or(map_get(placed, dep), false) {
      return false
    }
  }
  return true
}

fn build_order(jobs: List[Job]) -> Result[List[String], String] {
  let pending = map_from(map(jobs, |job| (job.name, false)))
  var seen = pending
  for job in jobs {
    if unwrap_or(map_get(seen, job.name), false) {
      return Err("duplicate job: " + job.name)
    }
    seen = map_set(seen, job.name, true)
  }
  for job in jobs {
    for dep in job.deps {
      if map_get(pending, dep) == None {
        return Err("unknown dependency: " + dep)
      }
    }
  }
  var placed = pending
  var order = take(keys(pending), 0)
  while len(order) < len(jobs) {
    let before = len(order)
    for job in jobs {
      let already_placed = unwrap_or(map_get(placed, job.name), false)
      if !already_placed && deps_placed(job.deps, placed) {
        order = append(order, job.name)
        placed = map_set(placed, job.name, true)
        break
      }
    }
    if len(order) == before {
      return Err("cycle detected")
    }
  }
  return Ok(order)
}

