}

fn decimal_sum(a: Int, b: Int) -> String {
  let base = 1000000000
  let tail = a % base + b % base
  let head = a / base + b / base + tail / base
  var digits = to_string(tail % base)
  if head == 0 {
    return digits
  }
  while str_len(digits) < 9 {
    digits = "0" + digits
  }
  return to_string(head) + digits
}

fn age_histogram(people: List[Person], width: Int) -> Result[List[(String, Int)], String] {
  if width < 1 {
    return Err("bad width")
  }
  for person in people {
    if person.age < 0 {
      return Err("negative age: " + person.name)
    }
  }
  if len(people) == 0 {
    return Ok([])
  }
  var counts = map_from([(0, 0)])
  var lowest = 0
  var highest = 0
  for (i, person) in enumerate(people) {
    let bucket = person.age / width
    if i == 0 || bucket < lowest {
      lowest = bucket
    }
    if bucket > highest {
      highest = bucket
    }
    let count = unwrap_or(map_get(counts, bucket), 0)
    counts = map_set(counts, bucket, count + 1)
  }
  var rows = take([("", 0)], 0)
  var bucket = lowest
  while true {
    let start = bucket * width
    let end = decimal_sum(start, width - 1)
    let label = to_string(start) + "-" + end
    let count = unwrap_or(map_get(counts, bucket), 0)
    rows = append(rows, (label, count))
    if bucket == highest {
      break
    }
    bucket = bucket + 1
  }
  return Ok(rows)
}

