type Key =
  | Digit(d: Int)
  | Enter
  | Clear

type LockState {
  status: String,
  buffer: List[String],
  failures: Int,
}

fn push_digit(buffer: List[String], digit: Int, capacity: Int) -> List[String] {
  if len(buffer) == capacity {
    return append(drop(buffer, 1), to_string(digit))
  }
  return append(buffer, to_string(digit))
}

fn submit_entry(state: LockState, code: String) -> LockState {
  if join(state.buffer, "") == code {
    return LockState { status: "open", buffer: [], failures: 0 }
  }
  let failures = state.failures + 1
  if failures == 3 {
    return LockState { status: "blocked", buffer: [], failures: failures }
  }
  return LockState { status: "locked", buffer: [], failures: failures }
}

fn door_lock(code: String, events: List[Key]) -> String {
  let capacity = str_len(code)
  var state = LockState { status: "locked", buffer: [], failures: 0 }
  for event in events {
    if state.status == "blocked" {
      break
    }
    if state.status == "open" {
      if event == Enter {
        state.status = "locked"
      }
    } else {
      state = match event {
        Digit(d) => LockState {
          status: "locked",
          buffer: push_digit(state.buffer, d, capacity),
          failures: state.failures,
        },
        Enter => submit_entry(state, code),
        Clear => LockState { status: "locked", buffer: [], failures: state.failures },
      }
    }
  }
  return state.status
}

