type Meeting {
  start: Int,
  end: Int,
}

fn free_slots(meetings: List[Meeting], day_start: Int, day_end: Int) -> List[(Int, Int)] {
  if day_end <= day_start {
    return []
  }
  var slots = []
  var cursor = day_start
  for meeting in sort_by(meetings, |m| m.start) {
    let start = max(day_start, meeting.start)
    let end = min(day_end, meeting.end)
    if start < end && end > cursor {
      if start > cursor {
        slots = append(slots, (cursor, start))
      }
      cursor = end
    }
  }
  if cursor < day_end {
    slots = append(slots, (cursor, day_end))
  }
  return slots
}

