fn edit_script_distance(a: String, b: String) -> Int {
  let a_chars = filter(split(a, ""), |c| c != "")
  let b_chars = filter(split(b, ""), |c| c != "")
  let columns = len(b_chars) + 1
  var previous = map_from(map(range(0, columns), |column| (column, column)))
  var two_back = previous
  var previous_a = ""
  for (i, a_char) in enumerate(a_chars) {
    var current = map_from([(0, i + 1)])
    var previous_b = ""
    for (j, b_char) in enumerate(b_chars) {
      let replacement = match a_char == b_char {
        true => 0,
        false => 1,
      }
      let deletion = row_cost(previous, j + 1) + 1
      let insertion = row_cost(current, j) + 1
      let diagonal = row_cost(previous, j) + replacement
      var best = min(min(deletion, insertion), diagonal)
      if i > 0 && j > 0 && a_char == previous_b && previous_a == b_char {
        let swap = row_cost(two_back, j - 1) + 1
        best = min(best, swap)
      }
      current = map_set(current, j + 1, best)
      previous_b = b_char
    }
    two_back = previous
    previous = current
    previous_a = a_char
  }
  return row_cost(previous, columns - 1)
}

