fn characters(s: String) -> List[String] {
  return filter(split(s, ""), |ch| ch != "")
}

fn find_all(s: String, pat: String) -> List[Int] {
  if pat == "" {
    return []
  }
  let text = characters(s)
  let pattern = characters(pat)
  let indexed_text = map_from(enumerate(text))
  let indexed_pattern = enumerate(pattern)
  let last_start = len(text) - len(pattern)
  var positions = []
  var start = 0
  while start <= last_start {
    var matches = true
    for (offset, ch) in indexed_pattern {
      if map_get(indexed_text, start + offset) != Some(ch) {
        matches = false
        break
      }
    }
    if matches {
      positions = append(positions, start)
    }
    start = start + 1
  }
  return positions
}

