type BankOp =
  | Open(name: String)
  | Deposit(name: String, amount: Int)
  | Withdraw(name: String, amount: Int)
  | Transfer(src: String, dst: String, amount: Int)

fn empty_balances() -> Map[String, Int] {
  return map_from([])
}

fn account_balance(balances: Map[String, Int], name: String) -> Result[Int, String] {
  return match map_get(balances, name) {
    Some(balance) => Ok(balance),
    None => Err("unknown account " + name),
  }
}

fn open_account(balances: Map[String, Int], name: String) -> Result[Map[String, Int], String] {
  return match map_get(balances, name) {
    Some(_) => Err("duplicate account " + name),
    None => Ok(map_set(balances, name, 0)),
  }
}

fn change(b: Map[String, Int], n: String, a: Int, w: Bool) -> Result[Map[String, Int], String] {
  let balance = try account_balance(b, n)
  if a <= 0 {
    return Err("invalid amount")
  }
  if w {
    if a > balance {
      return Err("insufficient funds")
    }
    return Ok(map_set(b, n, balance - a))
  }
  return Ok(map_set(b, n, balance + a))
}

fn move(b: Map[String, Int], s: String, d: String, a: Int) -> Result[Map[String, Int], String] {
  let src_balance = try account_balance(b, s)
  let dst_balance = try account_balance(b, d)
  if s == d {
    return Err("same account")
  }
  if a <= 0 {
    return Err("invalid amount")
  }
  if a > src_balance {
    return Err("insufficient funds")
  }
  let debited = map_set(b, s, src_balance - a)
  return Ok(map_set(debited, d, dst_balance + a))
}

fn apply_op(balances: Map[String, Int], op: BankOp) -> Result[Map[String, Int], String] {
  return match op {
    Open(name) => open_account(balances, name),
    Deposit(name, amount) => change(balances, name, amount, false),
    Withdraw(name, amount) => change(balances, name, amount, true),
    Transfer(src, dst, amount) => move(balances, src, dst, amount),
  }
}

fn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {
  var balances = empty_balances()
  for (i, op) in enumerate(ops) {
    let checked = match apply_op(balances, op) {
      Ok(updated) => Ok(updated),
      Err(message) => Err("step " + to_string(i + 1) + ": " + message),
    }
    balances = try checked
  }
  let pairs = zip(keys(balances), values(balances))
  return Ok(pairs)
}

