fn heading_numbers(lines: List[String]) -> List[String] {
  var outputs = []
  var level_one = 0
  var level_two = 0
  var level_three = 0
  for line in lines {
    let parts = split(line, " ")
    let marker = unwrap_or(first(parts), "")
    let title = join(drop(parts, 1), " ")
    if title != "" {
      if marker == "#" {
        level_one = level_one + 1
        level_two = 0
        level_three = 0
        outputs = append(outputs, to_string(level_one) + " " + title)
      } else if marker == "##" {
        level_two = level_two + 1
        level_three = 0
        let number = to_string(level_one) + "." + to_string(level_two)
        outputs = append(outputs, number + " " + title)
      } else if marker == "###" {
        level_three = level_three + 1
        let number = join([to_string(level_one), to_string(level_two), to_string(level_three)], ".")
        outputs = append(outputs, number + " " + title)
      }
    }
  }
  return outputs
}

