type Line {
  sku: String,
  qty: Int,
  unit_cents: Int,
}

fn floor_div(value: Int, divisor: Int) -> Int {
  let quotient = value / divisor
  if value < 0 && value % divisor != 0 {
    return quotient - 1
  }
  return quotient
}

fn apply_coupon(subtotal: Int, coupon: String) -> Result[Int, String] {
  if coupon == "BIG20" && subtotal < 10000 {
    return Err("coupon not applicable: BIG20")
  }
  return match coupon {
    "" => Ok(subtotal),
    "SAVE500" => Ok(max(subtotal, 500) - 500),
    "PCT10" => Ok(subtotal - floor_div(subtotal, 10)),
    "BIG20" => Ok(subtotal - floor_div(subtotal, 5)),
    _ => Err("unknown coupon: " + coupon),
  }
}

fn invoice_total(lines: List[Line], coupon: String) -> Result[Int, String] {
  for line in lines {
    if line.qty < 1 {
      return Err("bad quantity: " + line.sku)
    }
  }
  var subtotal = 0
  for line in lines {
    var amount = line.qty * line.unit_cents
    if line.qty >= 10 {
      amount = amount - floor_div(amount, 10)
    }
    subtotal = subtotal + amount
  }
  let amount = try apply_coupon(subtotal, coupon)
  let hundreds = amount / 100
  let remainder = amount - hundreds * 100
  let tax = hundreds * 8 + floor_div(remainder * 8 + 50, 100)
  return Ok(amount + tax)
}

