fn count_islands(grid: List[String]) -> (Int, Int) {
  let first_row = unwrap_or(first(grid), "")
  let stride = len(split(first_row, "")) + 1
  var land = map_from(take([(0, false)], 0))
  for (row, text) in enumerate(grid) {
    for (col, ch) in enumerate(split(text, "")) {
      if ch == "#" {
        land = map_set(land, row * stride + col, true)
      }
    }
  }
  var islands = 0
  var largest = 0
  for start in keys(land) {
    if unwrap_or(map_get(land, start), false) {
      islands = islands + 1
      land = map_set(land, start, false)
      var frontier = [start]
      var size = 0
      while len(frontier) > 0 {
        size = size + len(frontier)
        var next = take(frontier, 0)
        for cell in frontier {
          for neighbor in [cell - 1, cell + 1, cell - stride, cell + stride] {
            if unwrap_or(map_get(land, neighbor), false) {
              land = map_set(land, neighbor, false)
              next = append(next, neighbor)
            }
          }
        }
        frontier = next
      }
      largest = max(largest, size)
    }
  }
  return (islands, largest)
}

