fn max_subarray(xs: List[Int]) -> Option[(Int, Int, Int)] {
  if len(xs) == 0 {
    return None
  }
  var best_sum = unwrap_or(first(xs), 0)
  var best_start = 0
  var best_end = 0
  var run_sum = 0
  var run_start = 0
  for (i, x) in enumerate(xs) {
    if run_sum < 0 {
      run_sum = x
      run_start = i
    } else {
      run_sum = run_sum + x
    }
    if run_sum > best_sum {
      best_sum = run_sum
      best_start = run_start
      best_end = i
    }
  }
  return Some((best_sum, best_start, best_end))
}

