type Instruction =
  | Number(text: String)
  | Binary(op: String)

type ParseState {
  operators: List[String],
  output: List[Instruction],
}

fn precedence(op: String) -> Int {
  return match op {
    "+" => 1,
    "-" => 1,
    "*" => 2,
    "/" => 2,
    _ => 0,
  }
}

fn flush_operators(state: ParseState, minimum: Int) -> ParseState {
  var next = state
  while len(next.operators) > 0 {
    let op = unwrap_or(last(next.operators), "")
    if precedence(op) < minimum {
      break
    }
    next.operators = take(next.operators, len(next.operators) - 1)
    next.output = append(next.output, Binary(op))
  }
  return next
}

fn to_postfix(s: String) -> Result[List[Instruction], String] {
  let chars = filter(split(s, ""), |ch| ch != " " && ch != "")
  var state = ParseState { operators: [], output: [] }
  var need_factor = true
  var digits = ""
  var depth = 0
  for ch in chars {
    if ch >= "0" && ch <= "9" {
      if !need_factor && digits == "" {
        return Err("unexpected character: " + ch)
      }
      digits = digits + ch
      need_factor = false
    } else {
      if digits != "" {
        state.output = append(state.output, Number(digits))
        digits = ""
      }
      if need_factor {
        if ch != "(" {
          return Err("unexpected character: " + ch)
        }
        state.operators = append(state.operators, ch)
        depth = depth + 1
      } else if ch == ")" && depth > 0 {
        state = flush_operators(state, 1)
        state.operators = take(state.operators, len(state.operators) - 1)
        depth = depth - 1
      } else {
        let priority = precedence(ch)
        if priority == 0 {
          return Err("unexpected character: " + ch)
        }
        state = flush_operators(state, priority)
        state.operators = append(state.operators, ch)
        need_factor = true
      }
    }
  }
  if need_factor || depth > 0 {
    return Err("unexpected end")
  }
  if digits != "" {
    state.output = append(state.output, Number(digits))
  }
  state = flush_operators(state, 1)
  return Ok(state.output)
}

fn push_number(stack: List[Int], text: String) -> Result[List[Int], String] {
  var value = 0
  for ch in split(text, "") {
    let digit = unwrap_or(parse_int(ch), 0)
    value = value * 10 + digit
  }
  let next = append(stack, value)
  return Ok(next)
}

fn apply_binary(stack: List[Int], op: String) -> Result[List[Int], String] {
  let size = len(stack)
  let right = unwrap_or(last(stack), 0)
  let without_right = take(stack, size - 1)
  let left = unwrap_or(last(without_right), 0)
  if op == "/" && right == 0 {
    return Err("division by zero")
  }
  let value = match op {
    "+" => left + right,
    "-" => left - right,
    "*" => left * right,
    _ => left / right,
  }
  let rest = take(stack, size - 2)
  let next = append(rest, value)
  return Ok(next)
}

fn eval_expr(s: String) -> Result[Int, String] {
  let instructions = try to_postfix(s)
  var stack = take([0], 0)
  for instruction in instructions {
    let next = match instruction {
      Number(text) => push_number(stack, text),
      Binary(op) => apply_binary(stack, op),
    }
    stack = try next
  }
  let value = unwrap_or(last(stack), 0)
  return Ok(value)
}

