type ParseState =
  | NeedList
  | FirstElement
  | NeedElement
  | NeedDigit
  | InInteger
  | AfterElement
  | Complete

fn invalid_at(pos: Int) -> String {
  return "invalid at " + to_string(pos)
}

fn read_integer(token: String, pos: Int) -> Result[Int, String] {
  return match parse_int(token) {
    Some(value) => Ok(value),
    None => Err(invalid_at(pos)),
  }
}

fn flatten_nested(s: String) -> Result[(List[Int], Int), String] {
  let chars = filter(split(s, ""), |ch| ch != " " && ch != "")
  var state = NeedList
  var depth = 0
  var max_depth = 0
  var integers = []
  var token = ""
  var number = 0
  for (pos, ch) in enumerate(chars) {
    let digit = ch >= "0" && ch <= "9"
    let expect_element = state == FirstElement || state == NeedElement
    let expect_digit = expect_element || state == NeedDigit || state == InInteger
    let after_element = state == AfterElement || state == InInteger
    let can_close = after_element || state == FirstElement
    if ch == "[" && (state == NeedList || expect_element) {
      depth = depth + 1
      max_depth = max(max_depth, depth)
      state = FirstElement
    } else if ch == "-" && expect_element {
      token = "-"
      state = NeedDigit
    } else if digit && expect_digit {
      if expect_element || token == "0" {
        token = ""
      } else if token == "-0" {
        token = "-"
      }
      token = token + ch
      number = try read_integer(token, pos)
      state = InInteger
    } else if ch == "," && after_element || ch == "]" && can_close {
      if state == InInteger {
        integers = append(integers, number)
      }
      if ch == "," {
        state = NeedElement
      } else {
        depth = depth - 1
        if depth == 0 {
          state = Complete
        } else {
          state = AfterElement
        }
      }
    } else {
      return Err(invalid_at(pos))
    }
  }
  if state == Complete {
    return Ok((integers, max_depth))
  }
  return Err(invalid_at(len(chars)))
}

