type Match {
  home: String,
  away: String,
  home_goals: Int,
  away_goals: Int,
}

type Tally {
  team: String,
  points: Int,
  goals_for: Int,
  goals_against: Int,
}

fn empty_table() -> Map[String, Tally] {
  return map_from([])
}

fn match_points(scored: Int, conceded: Int) -> Int {
  if scored > conceded {
    return 3
  }
  if scored == conceded {
    return 1
  }
  return 0
}

fn credit(table: Map[String, Tally], team: String, gf: Int, ga: Int) -> Map[String, Tally] {
  let zero = Tally { team: team, points: 0, goals_for: 0, goals_against: 0 }
  let old = unwrap_or(map_get(table, team), zero)
  let updated = Tally {
    team: team,
    points: old.points + match_points(gf, ga),
    goals_for: old.goals_for + gf,
    goals_against: old.goals_against + ga,
  }
  return map_set(table, team, updated)
}

fn league_table(matches: List[Match]) -> List[(String, Int, Int, Int)] {
  var table = empty_table()
  for m in matches {
    table = credit(table, m.home, m.home_goals, m.away_goals)
    table = credit(table, m.away, m.away_goals, m.home_goals)
  }
  return table
    |> values()
    |> map(|t| (t.team, t.points, t.goals_for - t.goals_against, t.goals_for))
    |> sort_by(|row| row.0)
    |> sort_desc_by(|row| row.3)
    |> sort_desc_by(|row| row.2)
    |> sort_desc_by(|row| row.1)
}

