fn characters(text: String) -> List[String] {
  return filter(split(text, ""), |c| c != "")
}

fn advance(row: List[Bool], chars: List[String], token: String, escaped: Bool) -> List[Bool] {
  if !escaped && token == "*" {
    var rightmost = -1
    for (i, matched) in enumerate(row) {
      if matched {
        rightmost = i
      }
    }
    return map(enumerate(row), |entry| entry.0 <= rightmost)
  }
  let any_char = !escaped && token == "?"
  let previous = drop(row, 1)
  return chars
    |> zip(previous)
    |> map(|c, matched| matched && (any_char || c == token))
    |> append(false)
}

fn glob_match(pattern: String, s: String) -> Bool {
  let chars = reverse(characters(s))
  let n = len(chars)
  # The row tracks matching prefixes from longest to shortest.
  var row = map(range(0, n + 1), |i| i == n)
  var escaped = false
  for token in characters(pattern) {
    if !escaped && token == "\\" {
      escaped = true
    } else {
      row = advance(row, chars, token, escaped)
      escaped = false
    }
  }
  if escaped {
    row = advance(row, chars, "\\", true)
  }
  return unwrap_or(first(row), false)
}

