type Ending {
  value: Int,
  length: Int,
}

type Suffix {
  ending: Ending,
  count: Int,
}

fn lis_length(xs: List[Int]) -> (Int, Int) {
  let seed = Ending { value: 0, length: 0 }
  var endings = take([seed], 0)
  var longest = 0
  for x in xs {
    var length = 1
    for prev in endings {
      if prev.value < x {
        length = max(length, prev.length + 1)
      }
    }
    endings = append(endings, Ending { value: x, length: length })
    longest = max(longest, length)
  }
  var suffixes = take([Suffix { ending: seed, count: 0 }], 0)
  var total = 0
  for current in reverse(endings) {
    var count = 0
    if current.length == longest {
      count = 1
    } else {
      for next in suffixes {
        if current.value < next.ending.value && current.length + 1 == next.ending.length {
          count = count + next.count
        }
      }
    }
    suffixes = append(suffixes, Suffix { ending: current, count: count })
    if current.length == 1 {
      total = total + count
    }
  }
  return (longest, total)
}

