fn next_permutation(xs: List[Int]) -> List[Int] {
  if len(xs) < 2 {
    return xs
  }
  var pivot_at = -1
  var pivot_value = 0
  let neighbors = zip(xs, drop(xs, 1))
  for (i, pair) in enumerate(neighbors) {
    if pair.0 < pair.1 {
      pivot_at = i
      pivot_value = pair.0
    }
  }
  if pivot_at == -1 {
    return reverse(xs)
  }
  let suffix = reverse(drop(xs, pivot_at + 1))
  var successor = pivot_value
  var swapped = false
  var next_suffix = take(xs, 0)
  for value in suffix {
    if !swapped && value > pivot_value {
      successor = value
      swapped = true
      next_suffix = append(next_suffix, pivot_value)
    } else {
      next_suffix = append(next_suffix, value)
    }
  }
  var arrangement = append(take(xs, pivot_at), successor)
  for value in next_suffix {
    arrangement = append(arrangement, value)
  }
  return arrangement
}

