fn min_coins(coins: List[Int], amount: Int) -> Option[(Int, List[Int])] {
  if amount < 0 {
    return None
  }
  if amount == 0 {
    return Some((0, []))
  }
  let usable = filter(coins, |coin| coin <= amount)
  if len(usable) == 0 {
    return None
  }
  # Each entry stores the minimum count and the largest optimal first coin.
  var best = map_from([(0, (0, 0))])
  var total = 0
  while total < amount {
    total = total + 1
    var count = -1
    var chosen = 0
    for coin in usable {
      if coin <= total {
        let previous = unwrap_or(map_get(best, total - coin), (-1, 0))
        if previous.0 >= 0 {
          let candidate = previous.0 + 1
          if count < 0 || candidate < count || candidate == count && coin > chosen {
            count = candidate
            chosen = coin
          }
        }
      }
    }
    if count >= 0 {
      best = map_set(best, total, (count, chosen))
    }
  }
  let answer = unwrap_or(map_get(best, amount), (-1, 0))
  if answer.0 < 0 {
    return None
  }
  var used = []
  var remaining = amount
  while remaining > 0 {
    let entry = unwrap_or(map_get(best, remaining), (-1, 0))
    used = append(used, entry.1)
    remaining = remaining - entry.1
  }
  return Some((answer.0, used))
}

