fn read_live(grid: List[String], width: Int, stride: Int) -> Map[Int, Bool] {
  var live = empty_live()
  for (y, row) in enumerate(grid) {
    var x = -1
    for part in split(row, "#") {
      x = x + str_len(part) + 1
      if x < width {
        live = map_set(live, y * stride + x, true)
      }
    }
  }
  return live
}

fn empty_live() -> Map[Int, Bool] {
  return map_from([])
}

fn is_live(live: Map[Int, Bool], pos: Int) -> Bool {
  return unwrap_or(map_get(live, pos), false)
}

fn count_neighbors(live: Map[Int, Bool], pos: Int, stride: Int) -> Int {
  var count = 0
  for dy in [-1, 0, 1] {
    for dx in [-1, 0, 1] {
      if (dx != 0 || dy != 0) && is_live(live, pos + dy * stride + dx) {
        count = count + 1
      }
    }
  }
  return count
}

fn next_generation(live: Map[Int, Bool], width: Int, height: Int) -> Map[Int, Bool] {
  # Two unused positions per row prevent neighbors from wrapping across edges.
  let stride = width + 2
  let columns = range(0, width)
  var next = empty_live()
  for y in range(0, height) {
    for x in columns {
      let pos = y * stride + x
      let count = count_neighbors(live, pos, stride)
      if count == 3 || count == 2 && is_live(live, pos) {
        next = map_set(next, pos, true)
      }
    }
  }
  return next
}

fn cell_text(live: Map[Int, Bool], pos: Int) -> String {
  if is_live(live, pos) {
    return "#"
  }
  return "."
}

fn render_row(live: Map[Int, Bool], columns: List[Int], start: Int) -> String {
  let cells = map(columns, |x| cell_text(live, start + x))
  return join(cells, "")
}

fn life_step(grid: List[String], steps: Int) -> List[String] {
  let width = grid
    |> first()
    |> unwrap_or("")
    |> str_len()
  if steps == 0 || width == 0 {
    return grid
  }
  let height = len(grid)
  let stride = width + 2
  var live = read_live(grid, width, stride)
  var remaining = steps
  while remaining > 0 {
    live = next_generation(live, width, height)
    remaining = remaining - 1
  }
  let columns = range(0, width)
  let rows = range(0, height)
  return map(rows, |y| render_row(live, columns, y * stride))
}

