fn parse_ipv4_part(part: String) -> Result[Int, String] {
  let size = str_len(part)
  let error = "bad part: " + part
  if size < 1 || size > 3 {
    return Err(error)
  }
  let value = unwrap_or(parse_int(part), -1)
  if value < 0 || value > 255 || to_string(value) != part {
    return Err(error)
  }
  return Ok(value)
}

fn parse_ipv4(s: String) -> Result[Int, String] {
  let parts = split(s, ".")
  if len(parts) != 4 {
    return Err("expected 4 parts")
  }
  var address = 0
  for part in parts {
    let value = try parse_ipv4_part(part)
    address = address * 256 + value
  }
  return Ok(address)
}

