fn decode_plus(s: String) -> String {
  return join(split(s, "+"), " ")
}

fn parse_query(s: String) -> Result[List[(String, String)], String] {
  var pairs = take([("", "")], 0)
  for item in split(s, "&") {
    if item != "" {
      let parts = split(item, "=")
      let raw_key = unwrap_or(first(parts), "")
      let key = decode_plus(raw_key)
      if key == "" {
        return Err("empty key: " + item)
      }
      let raw_value = join(drop(parts, 1), "=")
      pairs = append(pairs, (key, decode_plus(raw_value)))
    }
  }
  return Ok(pairs)
}

