  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn employee_pay(emp: Employee) -> Int {
  let regular_pay = min(emp.hours, 40) * emp.rate_cents
  if emp.hours <= 40 {
    return regular_pay
  }
  let overtime_base = (emp.hours - 40) * emp.rate_cents
  var half = overtime_base / 2
  if overtime_base < 0 && overtime_base % 2 != 0 {
    half = half - 1
  }
  return regular_pay + overtime_base + half
}

fn dept_total(group: (String, List[Employee])) -> (String, Int) {
  return (group.0, sum(map(group.1, employee_pay)))
}

fn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {
  return emps
    |> group_by(|emp| emp.dept)
    |> map(dept_total)
    |> sort_by(|pair| pair.0)
    |> sort_desc_by(|pair| pair.1)
}

