fn is_vowel(letter: String, previous: String, at_start: Bool) -> Bool {
  if letter == "u" {
    return previous != "q"
  }
  if letter == "y" {
    return !at_start
  }
  return contains(["a", "e", "i", "o"], letter)
}

fn translate_word(word: String) -> String {
  let letters = filter(split(word, ""), |letter| letter != "")
  var previous = ""
  for (i, letter) in enumerate(letters) {
    if is_vowel(letter, previous, i == 0) {
      if i == 0 {
        return word + "way"
      }
      let prefix = join(take(letters, i), "")
      let suffix = join(drop(letters, i), "")
      return suffix + prefix + "ay"
    }
    previous = letter
  }
  return word + "ay"
}

fn pig_latin(s: String) -> String {
  if s == "" {
    return ""
  }
  return s
    |> split(" ")
    |> map(translate_word)
    |> join(" ")
}

