type Setting {
  section: String,
  key: String,
  value: String,
}

fn starts_with(text: String, marker: String) -> Bool {
  let parts = split(text, marker)
  return unwrap_or(first(parts), "") == ""
}

fn header_name(line: String) -> String {
  let opening_parts = split(line, "[")
  let body = join(drop(opening_parts, 1), "[")
  let closing_parts = split(body, "]")
  if unwrap_or(last(closing_parts), "") != "" {
    return ""
  }
  let inner_parts = take(closing_parts, len(closing_parts) - 1)
  return trim(join(inner_parts, "]"))
}

fn same_key(a: Setting, b: Setting) -> Bool {
  return a.section == b.section && a.key == b.key
}

fn put_setting(settings: List[Setting], entry: Setting) -> List[Setting] {
  for existing in settings {
    if same_key(existing, entry) {
      return map(settings, |item| if_same_key(item, entry))
    }
  }
  return append(settings, entry)
}

fn if_same_key(existing: Setting, entry: Setting) -> Setting {
  if same_key(existing, entry) {
    return entry
  }
  return existing
}

fn empty_settings() -> List[Setting] {
  return []
}

fn parse_config(lines: List[String]) -> Result[List[Setting], String] {
  var section = ""
  var settings = empty_settings()
  for (i, raw_line) in enumerate(lines) {
    let line = trim(raw_line)
    if line != "" && !starts_with(line, "#") {
      let prefix = "line " + to_string(i + 1) + ": "
      if starts_with(line, "[") {
        let name = header_name(line)
        if name == "" {
          return Err(prefix + "bad header")
        }
        section = name
      } else {
        let parts = split(line, "=")
        if len(parts) < 2 {
          return Err(prefix + "missing =")
        }
        let key = parts
          |> first()
          |> unwrap_or("")
          |> trim()
        if key == "" {
          return Err(prefix + "empty key")
        }
        let value_parts = drop(parts, 1)
        let value = trim(join(value_parts, "="))
        settings = put_setting(settings, Setting { section: section, key: key, value: value })
      }
    }
  }
  return Ok(settings)
}

