fn rle_compress(s: String) -> String {
  if s == "" {
    return s
  }
  var runs = []
  var current = ""
  var count = 0
  for character in split(s, "") {
    if character != "" {
      if count == 0 {
        current = character
        count = 1
      } else if character == current {
        count = count + 1
      } else {
        runs = append(runs, encode_run(current, count))
        current = character
        count = 1
      }
    }
  }
  if count > 0 {
    runs = append(runs, encode_run(current, count))
  }
  let encoded = join(runs, "")
  if str_len(encoded) < str_len(s) {
    return encoded
  }
  return s
}

