type Park =
  | Arrive(plate: String, minute: Int)
  | Leave(plate: String, minute: Int)

type Parking {
  parked: Map[String, Option[Int]],
  totals: Map[String, Int],
}

fn stay_fee(arrival: Int, departure: Int) -> Int {
  if departure <= arrival {
    return 0
  }
  # Check the cap before subtracting timestamps that could overflow.
  if arrival < 0 && departure > arrival + 270 {
    return 1000
  }
  let duration = departure - arrival
  if duration <= 30 {
    return 0
  }
  return 200 * min(5, 1 + (duration - 31) / 60)
}

fn arrive(state: Parking, plate: String, minute: Int) -> Parking {
  let arrival = unwrap_or(map_get(state.parked, plate), None)
  if arrival != None {
    return state
  }
  return Parking { parked: map_set(state.parked, plate, Some(minute)), totals: state.totals }
}

fn complete_stay(state: Parking, plate: String, arrival: Int, departure: Int) -> Parking {
  let previous = unwrap_or(map_get(state.totals, plate), 0)
  let total = previous + stay_fee(arrival, departure)
  return Parking {
    parked: map_set(state.parked, plate, None),
    totals: map_set(state.totals, plate, total),
  }
}

fn leave(state: Parking, plate: String, minute: Int) -> Parking {
  let arrival = unwrap_or(map_get(state.parked, plate), None)
  return match arrival {
    Some(start) => complete_stay(state, plate, start, minute),
    None => state,
  }
}

fn parking_fees(events: List[Park]) -> List[(String, Int)] {
  var state = Parking { parked: map_from([]), totals: map_from([]) }
  for event in events {
    state = match event {
      Arrive(plate, minute) => arrive(state, plate, minute),
      Leave(plate, minute) => leave(state, plate, minute),
    }
  }
  let totals = state.totals
  return totals
    |> keys()
    |> sort_by(|plate| plate)
    |> map(|plate| (plate, unwrap_or(map_get(totals, plate), 0)))
}

