fn decode_card(card: String) -> (Int, String) {
  let ranks = ["2", "3", "4", "5", "6", "7", "8", "9", "T", "J", "Q", "K", "A"]
  let suits = ["C", "D", "H", "S"]
  for (i, rank) in enumerate(ranks) {
    for suit in suits {
      if card == rank + suit {
        return (i + 2, suit)
      }
    }
  }
  return (0, "")
}

fn poker_hand(cards: List[String]) -> String {
  if len(cards) != 5 {
    return "invalid"
  }
  var seen = []
  var ranks = []
  var suits = []
  for card in cards {
    let decoded = decode_card(card)
    if decoded.0 == 0 || contains(seen, card) {
      return "invalid"
    }
    seen = append(seen, card)
    ranks = append(ranks, decoded.0)
    suits = append(suits, decoded.1)
  }
  let groups = group_by(ranks, |r| r)
  var pairs = 0
  var three = false
  var four = false
  for group in groups {
    let count = len(group.1)
    if count == 4 {
      four = true
    } else if count == 3 {
      three = true
    } else if count == 2 {
      pairs = pairs + 1
    }
  }
  let flush = len(group_by(suits, |s| s)) == 1
  let ordered = sort_by(ranks, |r| r)
  let low = unwrap_or(first(ordered), 0)
  let high = unwrap_or(last(ordered), 0)
