  | TurnLeft
  | TurnRight

fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var x = 0
  var y = 0
  var heading = 0
  for cmd in cmds {
    let move = match cmd {
      Forward(steps) => (0, steps),
      TurnLeft => (3, 0),
      TurnRight => (1, 0),
    }
    heading = (heading + move.0) % 4
    let delta = match heading {
      0 => (0, 1),
      1 => (1, 0),
      2 => (0, -1),
      _ => (-1, 0),
    }
    var remaining = move.1
    while remaining > 0 {
      let next = (x + delta.0, y + delta.1)
      if contains(obstacles, next) {
        break
      }
      x = next.0
      y = next.1
      remaining = remaining - 1
    }
  }
  let direction = match heading {
    0 => "N",
    1 => "E",
    2 => "S",
    _ => "W",
  }
  return (x, y, direction)
}

