fn parse_cents(text: String) -> Result[Int, String] {
  if str_len(text) != 2 {
    return Err("bad cents")
  }
  let prefixed = "1" + text
  let value = unwrap_or(parse_int(prefixed), 0)
  if to_string(value) != prefixed {
    return Err("bad cents")
  }
  return Ok(value - 100)
}

fn parse_dollars(text: String) -> Result[Int, String] {
  let groups = split(text, ",")
  if len(groups) > 1 {
    for (i, group) in enumerate(groups) {
      let width = str_len(group)
      if i == 0 {
        if width < 1 || width > 3 {
          return Err("bad dollars")
        }
      } else if width != 3 {
        return Err("bad dollars")
      }
    }
  }
  let digits = join(groups, "")
  if str_len(digits) > 14 {
    return Err("bad dollars")
  }
  let value = unwrap_or(parse_int(digits), -1)
  if value < 0 || to_string(value) != digits {
    return Err("bad dollars")
  }
  return Ok(value)
}

fn parse_money(s: String) -> Result[Int, String] {
  let currency = split(s, "$")
  let prefix = unwrap_or(first(currency), "")
  if len(currency) < 2 || prefix != "" && prefix != "-" {
    return Err("missing $")
  }
  let amount = join(drop(currency, 1), "$")
  let parts = split(amount, ".")
  if len(parts) > 2 {
    return Err("bad cents")
  }
  var cents = 0
  if len(parts) == 2 {
    cents = try (parts |> last() |> unwrap_or("") |> parse_cents())
  }
  let dollars = try (parts |> first() |> unwrap_or("") |> parse_dollars())
  if dollars > (9007199254740991 - cents) / 100 {
    return Err("bad dollars")
  }
  let total = dollars * 100 + cents
  if prefix == "-" {
    return Ok(-total)
  }
  return Ok(total)
}

