fn sliding_window_max(xs: List[Int], k: Int) -> Result[List[Int], String] {
  if k < 1 {
    return Err("window must be positive")
  }
  let n = len(xs)
  if k > n {
    return Err("window larger than input")
  }
  var maxima = []
  for (i, x) in enumerate(xs) {
    if i > n - k {
      break
    }
    let window = take(drop(xs, i), k)
    let largest = fold(window, x, |best, value| max(best, value))
    maxima = append(maxima, largest)
  }
  return Ok(maxima)
}

