fn roman_digit(symbol: String) -> Int {
  return match symbol {
    "I" => 1,
    "V" => 5,
    "X" => 10,
    "L" => 50,
    "C" => 100,
    "D" => 500,
    "M" => 1000,
    _ => 0,
  }
}

fn standard_roman(value: Int) -> String {
  let symbols = [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
  ]
  var remaining = value
  var text = ""
  for (amount, symbol) in symbols {
    while remaining >= amount {
      text = text + symbol
      remaining = remaining - amount
    }
  }
  return text
}

fn roman_to_int(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
  }
  let symbols = split(s, "")
  for symbol in symbols {
    if roman_digit(symbol) == 0 {
      return Err("invalid character: " + symbol)
    }
  }
  # A standard numeral has at most 3 thousands and 4 symbols per lower place.
  if len(symbols) > 15 {
    return Err("not canonical")
  }
  var total = 0
  var right = 0
  for symbol in reverse(symbols) {
    let value = roman_digit(symbol)
    if value < right {
      total = total - value
    } else {
      total = total + value
    }
    right = value
  }
  if total < 1 || total > 3999 {
    return Err("not canonical")
  }
  if s != standard_roman(total) {
    return Err("not canonical")
  }
  return Ok(total)
}

