  scores: List[Int],
}

fn median(scores: List[Int]) -> Float {
  let sorted = sort_by(scores, |score| score)
  let count = len(sorted)
  let middle = count / 2
  let upper = sorted
    |> drop(middle)
    |> first()
    |> unwrap_or(0)
  if count % 2 != 0 {
    return to_float(upper)
  }
  let lower = sorted
    |> take(middle)
    |> last()
    |> unwrap_or(0)
  return (to_float(lower) + to_float(upper)) / 2.0
}

fn student_medians(students: List[Student]) -> List[(String, Float)] {
  return students
    |> filter(|student| len(student.scores) > 0)
    |> map(|student| (student.name, median(student.scores)))
    |> sort_by(|pair| pair.0)
    |> sort_desc_by(|pair| pair.1)
}

