fn spiral_order(m: List[List[Int]]) -> List[Int] {
  var rows = m
  var order = []
  while len(rows) > 0 {
    let top = unwrap_or(first(rows), [])
    let width = len(top)
    if width == 0 {
      break
    }
    for row in rows {
      order = append(order, unwrap_or(first(row), 0))
    }
    let bottom = unwrap_or(last(rows), [])
    for value in drop(bottom, 1) {
      order = append(order, value)
    }
    if len(rows) == 1 || width == 1 {
      break
    }
    let above_bottom = take(rows, len(rows) - 1)
    for row in reverse(above_bottom) {
      order = append(order, unwrap_or(last(row), 0))
    }
    let top_without_right = take(top, width - 1)
    let top_middle = drop(top_without_right, 1)
    for value in reverse(top_middle) {
      order = append(order, value)
    }
    let middle_rows = drop(above_bottom, 1)
    rows = map(middle_rows, |row| drop(take(row, width - 1), 1))
  }
  return order
}

