  for point in split(points, "") {
    if has_won(a, b) || has_won(b, a) {
      return "error: point after game"
    }
    if point == "A" {
      a = a + 1
    } else if point == "B" {
      b = b + 1
    } else {
      return "error: bad point"
    }
  }
  if has_won(a, b) {
    return "game A"
  }
  if has_won(b, a) {
    return "game B"
  }
  if a >= 3 && b >= 3 {
    if a == b {
      return "deuce"
    }
    if a > b {
      return "advantage A"
    }
    return "advantage B"
  }
  if a == b {
    return point_name(a) + "-all"
  }
  return point_name(a) + "-" + point_name(b)
}

