type EditOp =
  | Insert(text: String)
  | Delete(n: Int)
  | Left(n: Int)
  | Right(n: Int)
  | Undo

type Snapshot {
  chars: List[String],
  cursor: Int,
}

type Editor {
  current: Snapshot,
  history: List[Snapshot],
}

fn splice(chars: List[String], start: Int, end: Int, inserted: List[String]) -> List[String] {
  var out = take(chars, start)
  for ch in inserted {
    out = append(out, ch)
  }
  for ch in drop(chars, end) {
    out = append(out, ch)
  }
  return out
}

fn save_edit(editor: Editor, chars: List[String], cursor: Int) -> Editor {
  return Editor {
    current: Snapshot { chars: chars, cursor: cursor },
    history: append(editor.history, editor.current),
  }
}

fn insert_text(editor: Editor, text: String) -> Editor {
  let inserted = filter(split(text, ""), |ch| ch != "")
  let cursor = editor.current.cursor
  let chars = splice(editor.current.chars, cursor, cursor, inserted)
  return save_edit(editor, chars, cursor + len(inserted))
}

fn delete_text(editor: Editor, n: Int) -> Editor {
  let cursor = editor.current.cursor
  let start = cursor - min(n, cursor)
  let chars = splice(editor.current.chars, start, cursor, [])
  return save_edit(editor, chars, start)
}

fn move_cursor(editor: Editor, cursor: Int) -> Editor {
  return Editor {
    current: Snapshot { chars: editor.current.chars, cursor: cursor },
    history: editor.history,
  }
}

fn restore(editor: Editor, snapshot: Snapshot) -> Editor {
  return Editor { current: snapshot, history: take(editor.history, len(editor.history) - 1) }
}

fn undo_edit(editor: Editor) -> Editor {
  return match last(editor.history) {
    Some(snapshot) => restore(editor, snapshot),
    None => editor,
  }
}

fn apply_edit(editor: Editor, op: EditOp) -> Editor {
  let cursor = editor.current.cursor
  let remaining = len(editor.current.chars) - cursor
  return match op {
    Insert(text) => insert_text(editor, text),
    Delete(n) => delete_text(editor, n),
    Left(n) => move_cursor(editor, cursor - min(n, cursor)),
    Right(n) => move_cursor(editor, cursor + min(n, remaining)),
    Undo => undo_edit(editor),
  }
}

fn text_editor(ops: List[EditOp]) -> String {
  var editor = Editor { current: Snapshot { chars: [], cursor: 0 }, history: [] }
  for op in ops {
    editor = apply_edit(editor, op)
  }
  return join(editor.current.chars, "")
}

