def bracket_depth(s: str) -> Ok[int] | Err:
    matching_open: dict[str, str] = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []
    depth: int = 0

    for index, char in enumerate(s):
        if char in "([{":
            stack.append(char)
            depth = max(depth, len(stack))
        elif char in matching_open:
            if not stack or stack[-1] != matching_open[char]:
                return {"ok": False, "error": f"mismatch at {index}"}
            stack.pop()

    if stack:
        return {"ok": False, "error": "unclosed at end"}
    return {"ok": True, "value": depth}

type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  var stack = []
  var output = []
  var pc = 0
  var steps = 0
  let size = len(prog)
  while pc < size {
    if steps == 1000 {
      return Err("step limit exceeded")
    }
    steps = steps + 1
    let remaining = drop(prog, pc)
    let instr = unwrap_or(first(remaining), Halt)
    if instr == Halt {
      return Ok(output)
    }
    let needed = match instr {
      Pop => 1,
      Dup => 1,
      Print => 1,
      Jz(_) => 1,
      Add => 2,
      Sub => 2,
      Mul => 2,
      Swap => 2,
      _ => 0,
    }
    let depth = len(stack)
    if depth < needed {
      return Err("stack underflow at " + to_string(pc))
    }
    let target = match instr {
      Jz(t) => Some(t),
      Jmp(t) => Some(t),
      _ => None,
    }
    let valid_target = match target {
      Some(t) => t >= 0 && t < size,
      None => true,
    }
    if !valid_target {
      return Err("bad jump at " + to_string(pc))
    }
    let b = unwrap_or(last(stack), 0)
