  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  var stack = []
  var output = []
  var pc = 0
  var steps = 0
  let size = len(prog)
  while pc < size {
    if steps == 1000 {
      return Err("step limit exceeded")
    }
    steps = steps + 1
    let remaining = drop(prog, pc)
    let instr = unwrap_or(first(remaining), Halt)
    if instr == Halt {
      return Ok(output)
    }
    let needed = match instr {
      Pop => 1,
      Dup => 1,
      Print => 1,
      Jz(_) => 1,
      Add => 2,
      Sub => 2,
      Mul => 2,
      Swap => 2,
      _ => 0,
    }
    let depth = len(stack)
    if depth < needed {
      return Err("stack underflow at " + to_string(pc))
    }
    let target = match instr {
      Jz(t) => Some(t),
      Jmp(t) => Some(t),
      _ => None,
    }
    let valid_target = match target {
      Some(t) => t >= 0 && t < size,
      None => true,
    }
    if !valid_target {
      return Err("bad jump at " + to_string(pc))
    }
    let b = unwrap_or(last(stack), 0)
    var a = 0
    if needed == 2 {
      let prefix = take(stack, depth - 1)
      a = unwrap_or(last(prefix), 0)
    }
    let rest = take(stack, depth - needed)
    stack = match instr {
      Push(n) => append(stack, n),
      Dup => append(stack, b),
      Add => append(rest, a + b),
      Sub => append(rest, a - b),
      Mul => append(rest, a * b),
