from __future__ import annotations
from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Job(TypedDict):
    name: str
    deps: list[str]


def build_order(jobs: list[Job]) -> Ok[list[str]] | Err:
    from heapq import heapify, heappop, heappush

    indices: dict[str, int] = {}
    for index, job in enumerate(jobs):
        name = job["name"]
        if name in indices:
            return {"ok": False, "error": f"duplicate job: {name}"}
        indices[name] = index

    dependents: list[list[int]] = [[] for _ in jobs]
    remaining: list[int] = [0] * len(jobs)
    for index, job in enumerate(jobs):
        for dependency in job["deps"]:
            if dependency not in indices:
                return {"ok": False, "error": f"unknown dependency: {dependency}"}
            dependents[indices[dependency]].append(index)
            remaining[index] += 1

    ready: list[int] = [
        index for index, count in enumerate(remaining) if count == 0
    ]
    heapify(ready)

    order: list[str] = []
    while ready:
        index = heappop(ready)
        order.append(jobs[index]["name"])
        for dependent in dependents[index]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heappush(ready, dependent)

    if len(order) != len(jobs):
        return {"ok": False, "error": "cycle detected"}
    return {"ok": True, "value": order}

