def bowling_score(rolls: list[int]) -> Ok[int] | Err:
    if any(roll < 0 or roll > 10 for roll in rolls):
        return {"ok": False, "error": "invalid roll"}

    count = len(rolls)
    index = 0
    score = 0

    for frame in range(1, 10):
        if index == count:
            return {"ok": False, "error": "incomplete game"}
        first = rolls[index]
        index += 1

        # Bonus lookahead does not consume rolls. An incomplete game
        # is rejected when the frame parser reaches the missing roll.
        if first == 10:
            score += 10 + sum(rolls[index:index + 2])
            continue

        if index == count:
            return {"ok": False, "error": "incomplete game"}
        pins = first + rolls[index]
        index += 1
        if pins > 10:
            return {"ok": False, "error": f"too many pins in frame {frame}"}
        score += pins
        if pins == 10:
            score += sum(rolls[index:index + 1])

    if count - index < 2:
        return {"ok": False, "error": "incomplete game"}
    first, second = rolls[index], rolls[index + 1]
    index += 2

    if first != 10 and first + second > 10:
        return {"ok": False, "error": "too many pins in frame 10"}
    score += first + second

    if first == 10 or first + second == 10:
        if index == count:
            return {"ok": False, "error": "incomplete game"}
        bonus = rolls[index]
        index += 1
        if first == 10 and second != 10 and second + bonus > 10:
            return {"ok": False, "error": "too many pins in frame 10"}
        score += bonus

    if index < count:
        return {"ok": False, "error": "too many rolls"}
    return {"ok": True, "value": score}

