    return {"ok": False, "error": f"step {step}: {message}"}


def bank_ledger(ops: list[BankOp]) -> Ok[list[tuple[str, int]]] | Err:
    balances: dict[str, int] = {}

    for step, op in enumerate(ops, start=1):
        if op["kind"] == "Open":
            name = op["name"]
            if name in balances:
                return _step_error(step, f"duplicate account {name}")
            balances[name] = 0
            continue

        if op["kind"] == "Transfer":
            src, dst = op["src"], op["dst"]
            if src not in balances:
                return _step_error(step, f"unknown account {src}")
            if dst not in balances:
                return _step_error(step, f"unknown account {dst}")
            if src == dst:
                return _step_error(step, "same account")
            amount = op["amount"]
            if amount <= 0:
                return _step_error(step, "invalid amount")
            if amount > balances[src]:
                return _step_error(step, "insufficient funds")
            balances[src] -= amount
            balances[dst] += amount
            continue

        name = op["name"]
        if name not in balances:
            return _step_error(step, f"unknown account {name}")
        amount = op["amount"]
        if amount <= 0:
            return _step_error(step, "invalid amount")
        if op["kind"] == "Withdraw":
            if amount > balances[name]:
                return _step_error(step, "insufficient funds")
            balances[name] -= amount
        else:
            balances[name] += amount

    return {"ok": True, "value": list(balances.items())}

