def count_islands(grid: list[str]) -> tuple[int, int]:
    if not grid:
        return (0, 0)

    height = len(grid)
    width = len(grid[0])
    visited: set[tuple[int, int]] = set()
    island_count = 0
    largest_island = 0

    for row, line in enumerate(grid):
        for col, cell in enumerate(line):
            if cell != "#" or (row, col) in visited:
                continue

            island_count += 1
            size = 0
            stack: list[tuple[int, int]] = [(row, col)]
            visited.add((row, col))

            while stack:
                r, c = stack.pop()
                size += 1
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if (
                        0 <= nr < height
                        and 0 <= nc < width
                        and grid[nr][nc] == "#"
                        and (nr, nc) not in visited
                    ):
                        visited.add((nr, nc))
                        stack.append((nr, nc))

            largest_island = max(largest_island, size)

    return (island_count, largest_island)

