def _version_key(version: str) -> list[tuple[int, str]] | None:
    parts = version.split(".", 4)
    if len(parts) > 4:
        return None

    key: list[tuple[int, str]] = []
    for part in parts:
        if not part.isdecimal():
            return None
        if not part.isascii():
            part = "".join(str(int(digit)) for digit in part)
        digits = part.lstrip("0")
        key.append((len(digits), digits))

    key.extend([(0, "")] * (4 - len(key)))
    return key


def compare_versions(a: str, b: str) -> Ok[int] | Err:
    a_key = _version_key(a)
    if a_key is None:
        return {"ok": False, "error": "bad version: " + a}

    b_key = _version_key(b)
    if b_key is None:
        return {"ok": False, "error": "bad version: " + b}

    if a_key < b_key:
        return {"ok": True, "value": -1}
    if a_key > b_key:
        return {"ok": True, "value": 1}
    return {"ok": True, "value": 0}

