    kind: Literal["Clear"]

Key = Digit | Enter | Clear


def door_lock(code: str, events: list[Key]) -> str:
    state: Literal["locked", "open"] = "locked"
    buffer = ""
    failures = 0
    width = len(code)

    for event in events:
        if state == "open":
            if event["kind"] == "Enter":
                state = "locked"
            continue

        if event["kind"] == "Digit":
            buffer = (buffer + str(event["d"]))[-width:]
        elif event["kind"] == "Clear":
            buffer = ""
        else:
            matches = buffer == code
            buffer = ""
            if matches:
                state = "open"
                failures = 0
            else:
                failures += 1
                if failures == 3:
                    return "blocked"

    return state

