        if line["qty"] < 1:
            return {"ok": False, "error": "bad quantity: " + line["sku"]}

    subtotal = 0
    for line in lines:
        qty = line["qty"]
        line_amount = qty * line["unit_cents"]
        if qty >= 10:
            line_amount -= line_amount // 10
        subtotal += line_amount

    if coupon == "":
        amount = subtotal
    elif coupon == "SAVE500":
        amount = max(0, subtotal - 500)
    elif coupon == "PCT10":
        amount = subtotal - subtotal // 10
    elif coupon == "BIG20":
        if subtotal < 10000:
            return {"ok": False, "error": "coupon not applicable: BIG20"}
        amount = subtotal - subtotal // 5
    else:
        return {"ok": False, "error": "unknown coupon: " + coupon}

    tax = (amount * 8 + 50) // 100
    return {"ok": True, "value": amount + tax}

