from typing import TypedDict

class Match(TypedDict):
    home: str
    away: str
    home_goals: int
    away_goals: int


def league_table(matches: list[Match]) -> list[tuple[str, int, int, int]]:
    totals: dict[str, tuple[int, int, int]] = {}

    def record(team: str, goals_for: int, goals_against: int) -> None:
        points, difference, scored = totals.get(team, (0, 0, 0))
        match_points = 3 if goals_for > goals_against else int(goals_for == goals_against)
        totals[team] = (
            points + match_points,
            difference + goals_for - goals_against,
            scored + goals_for,
        )

    for match in matches:
        home_goals = match["home_goals"]
        away_goals = match["away_goals"]
        record(match["home"], home_goals, away_goals)
        record(match["away"], away_goals, home_goals)

    rows = [
        (team, points, difference, scored)
        for team, (points, difference, scored) in totals.items()
    ]
    return sorted(rows, key=lambda row: (-row[1], -row[2], -row[3], row[0]))

