def max_subarray(xs: list[int]) -> tuple[int, int, int] | None:
    if not xs:
        return None

    current_sum = best_sum = xs[0]
    current_start = best_start = best_end = 0

    for end in range(1, len(xs)):
        if current_sum < 0:
            current_sum = xs[end]
            current_start = end
        else:
            current_sum += xs[end]

        if current_sum > best_sum or (
            current_sum == best_sum
            and (current_start, end) < (best_start, best_end)
        ):
            best_sum, best_start, best_end = current_sum, current_start, end

    return best_sum, best_start, best_end

