def life_step(grid: list[str], steps: int) -> list[str]:
    current = grid.copy()
    height = len(current)
    width = len(current[0]) if height else 0

    for _ in range(steps):
        next_grid: list[str] = []
        for y, row in enumerate(current):
            next_row: list[str] = []
            for x, cell in enumerate(row):
                neighbors = 0
                for ny in range(max(0, y - 1), min(height, y + 2)):
                    for nx in range(max(0, x - 1), min(width, x + 2)):
                        if (ny != y or nx != x) and current[ny][nx] == "#":
                            neighbors += 1
                alive = neighbors == 3 or (cell == "#" and neighbors == 2)
                next_row.append("#" if alive else ".")
            next_grid.append("".join(next_row))
        current = next_grid

    return current

from __future__ import annotations


def glob_match(pattern: str, s: str) -> bool:
    p = 0
    i = 0
    after_star = -1
    star_end = 0

    while i < len(s):
        if p < len(pattern):
            char = pattern[p]
            if char == "*":
                p += 1
                after_star = p
                star_end = i
                continue

            next_p = p + 1
            if char == "\\":
                if next_p < len(pattern):
                    char = pattern[next_p]
                    next_p += 1
                matches = char == s[i]
            else:
                matches = char == "?" or char == s[i]

            if matches:
                p = next_p
                i += 1
                continue

        if after_star == -1:
            return False

        # Let the most recent star consume one more character and retry.
        star_end += 1
        i = star_end
        p = after_star

    while p < len(pattern) and pattern[p] == "*":
        p += 1

    return p == len(pattern)

