def _merge(left: tuple[int, int], right: tuple[int, int]) -> tuple[int, int]:
    if left[0] > right[0]:
        return left
    if right[0] > left[0]:
        return right
    return left[0], left[1] + right[1]


def lis_length(xs: list[int]) -> tuple[int, int]:
    ranks = {value: rank for rank, value in enumerate(sorted(set(xs)), start=1)}
    tree: list[tuple[int, int]] = [(0, 0)] * (len(ranks) + 1)
    best = (0, 0)

    for value in xs:
        rank = ranks[value]
        prefix = (0, 0)
        index = rank - 1
        while index > 0:
            prefix = _merge(prefix, tree[index])
            index -= index & -index

        length, count = prefix
        current = (length + 1, count if length else 1)
        best = _merge(best, current)

        index = rank
        while index < len(tree):
            tree[index] = _merge(tree[index], current)
            index += index & -index

    return best

from __future__ import annotations


def min_coins(coins: list[int], amount: int) -> tuple[int, list[int]] | None:
    if amount < 0:
        return None
    if amount == 0:
        return (0, [])

    values = sorted({coin for coin in coins if coin <= amount})
    if not values:
        return None

    unreachable = amount + 1
    counts = [0] + [unreachable] * amount
    first = [0] * (amount + 1)

    for subtotal in range(1, amount + 1):
        for coin in values:
            if coin > subtotal:
                break
            candidate = counts[subtotal - coin] + 1
            if candidate <= counts[subtotal] and candidate < unreachable:
                counts[subtotal] = candidate
                first[subtotal] = coin

    if counts[amount] == unreachable:
        return None

    used: list[int] = []
    remaining = amount
    while remaining > 0:
        coin = first[remaining]
        used.append(coin)
        remaining -= coin

    return (counts[amount], used)

