from typing import TypedDict

class Contact(TypedDict):
    name: str
    email: str
    phone: str


def merge_contacts(contacts: list[Contact]) -> list[Contact]:
    parent = list(range(len(contacts)))
    size = [1] * len(contacts)

    def find(index: int) -> int:
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left: int, right: int) -> None:
        left = find(left)
        right = find(right)
        if left == right:
            return
        if size[left] < size[right]:
            left, right = right, left
        parent[right] = left
        size[left] += size[right]

    first_by_email: dict[str, int] = {}
    first_by_phone: dict[str, int] = {}
    for index, contact in enumerate(contacts):
        email = contact["email"].strip()
        phone = "".join(char for char in contact["phone"] if "0" <= char <= "9")
        if email:
            union(index, first_by_email.setdefault(email, index))
        if phone:
            union(index, first_by_phone.setdefault(phone, index))

    merged_by_root: dict[int, Contact] = {}
    for index, contact in enumerate(contacts):
        root = find(index)
        if root not in merged_by_root:
            merged_by_root[root] = contact.copy()
            continue

        merged = merged_by_root[root]
        if merged["name"] == "":
            merged["name"] = contact["name"]
        if merged["email"] == "":
            merged["email"] = contact["email"]
        if merged["phone"] == "":
            merged["phone"] = contact["phone"]

    return list(merged_by_root.values())

