    ok: Literal[False]
    error: str


def _divide(left: int, right: int) -> int:
    magnitude = abs(left) // abs(right)
    return -magnitude if (left < 0) != (right < 0) else magnitude


_OPERATORS: dict[str, tuple[int, Callable[[int, int], int]]] = {
    "+": (1, int.__add__),
    "-": (1, int.__sub__),
    "*": (2, int.__mul__),
    "/": (2, _divide),
}


def _unexpected(character: str) -> Err:
    return {"ok": False, "error": "unexpected character: " + character}


def eval_expr(s: str) -> Ok[int] | Err:
    s = s.replace(" ", "")
    output: list[str] = []
    operators: list[str] = []
    depth = 0
    need_factor = True
    i = 0

    # Parse into postfix order without performing any arithmetic.
    while i < len(s):
        character = s[i]
        if need_factor:
            if character == "(":
                operators.append(character)
                depth += 1
            elif character.isdecimal():
                start = i
                i += 1
                while i < len(s) and s[i].isdecimal():
                    i += 1
                output.append(s[start:i])
                need_factor = False
                continue
            else:
                return _unexpected(character)
        elif character in _OPERATORS:
            precedence = _OPERATORS[character][0]
            while (
                operators
                and operators[-1] != "("
                and _OPERATORS[operators[-1]][0] >= precedence
            ):
                output.append(operators.pop())
            operators.append(character)
            need_factor = True
        elif character == ")" and depth > 0:
            while operators[-1] != "(":
                output.append(operators.pop())
            operators.pop()
            depth -= 1
        else:
            return _unexpected(character)
        i += 1

    if need_factor or depth > 0:
        return {"ok": False, "error": "unexpected end"}

    while operators:
        output.append(operators.pop())

    values: list[int] = []
    for token in output:
        if token in _OPERATORS:
            right = values.pop()
            left = values.pop()
            if token == "/" and right == 0:
                return {"ok": False, "error": "division by zero"}
            values.append(_OPERATORS[token][1](left, right))
        else:
            value = 0
            for digit in token:
                value = value * 10 + int(digit)
            values.append(value)

    return {"ok": True, "value": values.pop()}

