def parse_csv_line(s: str) -> Ok[list[str]] | Err:
    fields: list[str] = []
    i = 0
    n = len(s)

    while True:
        if i < n and s[i] == '"':
            i += 1
            chars: list[str] = []
            while i < n:
                char = s[i]
                i += 1
                if char == '"':
                    if i == n or s[i] != '"':
                        break
                    i += 1
                chars.append(char)
            else:
                return {"ok": False, "error": "unterminated quote"}

            if i < n and s[i] != ",":
                return {"ok": False, "error": f"expected comma at {i}"}
            fields.append("".join(chars))
        else:
            start = i
            while i < n and s[i] != ",":
                if s[i] == '"':
                    return {"ok": False, "error": f"unexpected quote at {i}"}
                i += 1
            fields.append(s[start:i])

        if i == n:
            return {"ok": True, "value": fields}
        i += 1

