def parse_duration(s: str) -> Ok[int] | Err:
    if not s:
        return {"ok": False, "error": "empty"}

    units = "hms"
    multipliers = (3600, 60, 1)
    last_unit = -1
    total = 0
    number = 0
    has_digits = False

    for char in s:
        if char.isdecimal():
            number = number * 10 + int(char)
            has_digits = True
            continue

        unit = units.find(char)
        if unit == -1:
            return {"ok": False, "error": f"unknown unit: {char}"}
        if not has_digits:
            return {"ok": False, "error": f"missing number before {char}"}
        if unit <= last_unit:
            return {"ok": False, "error": f"unit out of order: {char}"}

        total += number * multipliers[unit]
        last_unit = unit
        number = 0
        has_digits = False

    if has_digits:
        return {"ok": False, "error": "missing unit"}
    return {"ok": True, "value": total}

