def _translate_word(word: str) -> str:
    for index, letter in enumerate(word):
        if letter == "u" and index > 0 and word[index - 1] == "q":
            continue
        if letter in "aeiou" or (letter == "y" and index > 0):
            if index == 0:
                return word + "way"
            return word[index:] + word[:index] + "ay"
    return word + "ay"


