def robot_walk(cmds: list[Cmd], obstacles: list[tuple[int, int]]) -> tuple[int, int, str]:
    blocked = set(obstacles)
    directions = ("N", "E", "S", "W")
    offsets = ((0, 1), (1, 0), (0, -1), (-1, 0))
    heading = 0
    x = y = 0

    for cmd in cmds:
        if cmd["kind"] == "TurnLeft":
            heading = (heading - 1) % 4
        elif cmd["kind"] == "TurnRight":
            heading = (heading + 1) % 4
        else:
            dx, dy = offsets[heading]
            for _ in range(cmd["steps"]):
                next_cell = (x + dx, y + dy)
                if next_cell in blocked:
                    break
                x, y = next_cell

    return x, y, directions[heading]

from __future__ import annotations


def poker_hand(cards: list[str]) -> str:
    if len(cards) != 5 or len(set(cards)) != 5:
        return "invalid"

    ranks = "23456789TJQKA"
    rank_counts: dict[int, int] = {}
    suits: set[str] = set()

    for card in cards:
        if len(card) != 2 or card[0] not in ranks or card[1] not in "CDHS":
            return "invalid"
        rank = ranks.index(card[0])
        rank_counts[rank] = rank_counts.get(rank, 0) + 1
        suits.add(card[1])

    counts = sorted(rank_counts.values(), reverse=True)
    distinct_ranks = sorted(rank_counts)
    flush = len(suits) == 1
    straight = len(distinct_ranks) == 5 and (
        distinct_ranks[-1] - distinct_ranks[0] == 4
        or distinct_ranks == [0, 1, 2, 3, 12]
    )

    if straight and flush:
        return "straight flush"
    if counts == [4, 1]:
        return "four of a kind"
    if counts == [3, 2]:
        return "full house"
    if flush:
        return "flush"
    if straight:
        return "straight"
    if counts == [3, 1, 1]:
        return "three of a kind"
    if counts == [2, 2, 1]:
        return "two pair"
    if counts == [2, 1, 1, 1]:
        return "one pair"
    return "high card"

