def parse_money(s: str) -> Ok[int] | Err:
    negative = s.startswith("-")
    prefix = "-$" if negative else "$"
    if not s.startswith(prefix):
        return {"ok": False, "error": "missing $"}

    dollars, dot, cents = s[len(prefix):].partition(".")
    if dot and (len(cents) != 2 or not cents.isdecimal()):
        return {"ok": False, "error": "bad cents"}

    groups = dollars.split(",")
    if not all(group.isdecimal() for group in groups):
        return {"ok": False, "error": "bad dollars"}
    if len(groups) > 1 and (
        len(groups[0]) > 3 or any(len(group) != 3 for group in groups[1:])
    ):
        return {"ok": False, "error": "bad dollars"}

    digits = "".join(groups)
    if len(digits) > 1 and digits.startswith("0"):
        return {"ok": False, "error": "bad dollars"}

    whole = 0
    for digit in digits:
        whole = whole * 10 + int(digit)

    value = whole * 100 + (int(cents) if dot else 0)
    return {"ok": True, "value": -value if negative else value}

