from typing import TypedDict

class Expense(TypedDict):
    payer: str
    amount_cents: int


def settle_debts(
    expenses: list[Expense], people: list[str]
) -> list[tuple[str, str, int]]:
    total = sum(expense["amount_cents"] for expense in expenses)
    share, remainder = divmod(total, len(people))
    balances = {
        person: -(share + (index < remainder))
        for index, person in enumerate(people)
    }
    for expense in expenses:
        balances[expense["payer"]] += expense["amount_cents"]

    payments: list[tuple[str, str, int]] = []
    while True:
        debtor = min(people, key=balances.__getitem__)
        debt = -balances[debtor]
        if debt == 0:
            return payments

        creditor = max(people, key=balances.__getitem__)
        amount = min(debt, balances[creditor])
        payments.append((debtor, creditor, amount))
        balances[debtor] += amount
        balances[creditor] -= amount

