def rle_decode(s: str) -> Ok[str] | Err:
    if s and "0" <= s[0] <= "9":
        return {"ok": False, "error": "missing character before count"}

    groups: list[tuple[str, int, int]] = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        start = i
        if i < len(s) and s[i] == "0":
            return {"ok": False, "error": f"bad count for {char}"}
        while i < len(s) and "0" <= s[i] <= "9":
            i += 1
        groups.append((char, start, i))

    parts: list[str] = []
    for char, start, end in groups:
        if start == end:
            parts.append(char)
        else:
            count = 0
            for i in range(start, end):
                count = count * 10 + ord(s[i]) - ord("0")
            parts.append(char * count)
    return {"ok": True, "value": "".join(parts)}

from __future__ import annotations


def spiral_order(m: list[list[int]]) -> list[int]:
    if not m or not m[0]:
        return []

    result: list[int] = []
    top, bottom = 0, len(m) - 1
    left, right = 0, len(m[0]) - 1

    while top <= bottom and left <= right:
        for row in range(top, bottom + 1):
            result.append(m[row][left])
        left += 1
        if left > right:
            break

        for col in range(left, right + 1):
            result.append(m[bottom][col])
        bottom -= 1
        if top > bottom:
            break

        for row in range(bottom, top - 1, -1):
            result.append(m[row][right])
        right -= 1
        if left > right:
            break

        for col in range(right, left - 1, -1):
            result.append(m[top][col])
        top += 1

    return result

