from typing import TypedDict

class Student(TypedDict):
    name: str
    scores: list[int]


def student_medians(students: list[Student]) -> list[tuple[str, float]]:
    medians: list[tuple[str, float]] = []
    for student in students:
        scores = sorted(student["scores"])
        count = len(scores)
        if count == 0:
            continue

        middle = count // 2
        if count % 2:
            median = float(scores[middle])
        else:
            median = (scores[middle - 1] + scores[middle]) / 2
        medians.append((student["name"], median))

    medians.sort(key=lambda pair: (-pair[1], pair[0]))
    return medians

from __future__ import annotations


def wrap_text(s: str, width: int) -> list[str]:
    lines: list[str] = []
    current: list[str] = []
    length = 0

    for word in s.split(" "):
        if not word:
            continue

        word_length = len(word)
        if current and length + 1 + word_length > width:
            lines.append(" ".join(current))
            current.clear()
            length = 0

        if current:
            length += 1
        current.append(word)
        length += word_length

    if current:
        lines.append(" ".join(current))

    return lines

