class Insert(TypedDict):
    kind: Literal["Insert"]
    text: str

class Delete(TypedDict):
    kind: Literal["Delete"]
    n: int

class Left(TypedDict):
    kind: Literal["Left"]
    n: int

class Right(TypedDict):
    kind: Literal["Right"]
    n: int

class Undo(TypedDict):
    kind: Literal["Undo"]

EditOp = Insert | Delete | Left | Right | Undo


def text_editor(ops: list[EditOp]) -> str:
    text = ""
    cursor = 0
    history: list[tuple[str, int]] = []

    for op in ops:
        if op["kind"] == "Insert":
            history.append((text, cursor))
            inserted = op["text"]
            text = text[:cursor] + inserted + text[cursor:]
            cursor += len(inserted)
        elif op["kind"] == "Delete":
            history.append((text, cursor))
            start = max(0, cursor - op["n"])
            text = text[:start] + text[cursor:]
            cursor = start
        elif op["kind"] == "Left":
            cursor = max(0, cursor - op["n"])
        elif op["kind"] == "Right":
            cursor = min(len(text), cursor + op["n"])
        elif op["kind"] == "Undo" and history:
            text, cursor = history.pop()

    return text

