from typing import Literal


def tennis_score(points: str) -> str:
    a = 0
    b = 0
    winner: Literal["A", "B"] | None = None

    for point in points:
        if winner is not None:
            return "error: point after game"

        if point == "A":
            a += 1
        elif point == "B":
            b += 1
        else:
            return "error: bad point"

        if a >= 4 and a - b >= 2:
            winner = "A"
        elif b >= 4 and b - a >= 2:
            winner = "B"

    if winner is not None:
        return f"game {winner}"

    if a >= 3 and b >= 3:
        if a == b:
            return "deuce"
        return "advantage A" if a > b else "advantage B"

    names = ("love", "15", "30", "40")
    if a == b:
        return f"{names[a]}-all"
    return f"{names[a]}-{names[b]}"

