from typing import Literal, TypedDict

class Coin(TypedDict):
    kind: Literal["Coin"]
    cents: int

class Select(TypedDict):
    kind: Literal["Select"]
    price: int

class Refund(TypedDict):
    kind: Literal["Refund"]

Event = Coin | Select | Refund


def vending_machine(events: list[Event]) -> list[str]:
    credit = 0
    messages: list[str] = []

    for event in events:
        if event["kind"] == "Coin":
            cents = event["cents"]
            if cents in (5, 10, 25, 100):
                credit += cents
            else:
                messages.append(f"reject {cents}")
        elif event["kind"] == "Select":
            price = event["price"]
            if credit >= price:
                messages.append(f"vend {price} change {credit - price}")
                credit = 0
            else:
                messages.append(f"insufficient {credit}")
        elif credit > 0:
            messages.append(f"refund {credit}")
            credit = 0

    if credit > 0:
        messages.append(f"refund {credit}")

    return messages

