from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Push(TypedDict):
    kind: Literal["Push"]
    n: int

class Pop(TypedDict):
    kind: Literal["Pop"]

class Add(TypedDict):
    kind: Literal["Add"]

class Sub(TypedDict):
    kind: Literal["Sub"]

class Mul(TypedDict):
    kind: Literal["Mul"]

class Dup(TypedDict):
    kind: Literal["Dup"]

class Swap(TypedDict):
    kind: Literal["Swap"]

class Jz(TypedDict):
    kind: Literal["Jz"]
    target: int

class Jmp(TypedDict):
    kind: Literal["Jmp"]
    target: int

class Print(TypedDict):
    kind: Literal["Print"]

class Halt(TypedDict):
    kind: Literal["Halt"]

Instr = Push | Pop | Add | Sub | Mul | Dup | Swap | Jz | Jmp | Print | Halt


def stack_vm(prog: list[Instr]) -> Ok[list[int]] | Err:
    stack: list[int] = []
    output: list[int] = []
    pc = 0
    steps = 0
    size = len(prog)

    while pc < size:
        if steps == 1000:
            return {"ok": False, "error": "step limit exceeded"}
        steps += 1

        instr = prog[pc]
        kind = instr["kind"]
        needed = 0
        if kind in ("Pop", "Dup", "Print", "Jz"):
            needed = 1
        elif kind in ("Add", "Sub", "Mul", "Swap"):
            needed = 2
        if len(stack) < needed:
            return {"ok": False, "error": f"stack underflow at {pc}"}

        if instr["kind"] == "Push":
            stack.append(instr["n"])
        elif instr["kind"] == "Jz" or instr["kind"] == "Jmp":
            target = instr["target"]
            if not 0 <= target < size:
                return {"ok": False, "error": f"bad jump at {pc}"}
            if kind == "Jmp" or stack.pop() == 0:
                pc = target
                continue
        elif kind == "Pop":
            stack.pop()
        elif kind == "Dup":
            stack.append(stack[-1])
        elif kind == "Swap":
            stack[-2], stack[-1] = stack[-1], stack[-2]
        elif kind == "Print":
            output.append(stack.pop())
        elif kind in ("Add", "Sub", "Mul"):
            b = stack.pop()
            a = stack.pop()
            if kind == "Add":
                stack.append(a + b)
            elif kind == "Sub":
                stack.append(a - b)
            else:
                stack.append(a * b)
        elif kind == "Halt":
            break

        pc += 1

    return {"ok": True, "value": output}

