from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str

class Num(TypedDict):
    kind: Literal["Num"]
    value: int

class Ident(TypedDict):
    kind: Literal["Ident"]
    name: str

class Sym(TypedDict):
    kind: Literal["Sym"]
    text: str

Token = Num | Ident | Sym


def _is_ident_start(char: str) -> bool:
    return "a" <= char <= "z" or char == "_"


def tokenize(s: str) -> Ok[list[Token]] | Err:
    tokens: list[Token] = []
    i = 0
    while i < len(s):
        char = s[i]
        if char == " ":
            i += 1
        elif char.isdecimal():
            value = 0
            while i < len(s) and s[i].isdecimal():
                value = value * 10 + int(s[i])
                i += 1
            tokens.append({"kind": "Num", "value": value})
        elif _is_ident_start(char):
            start = i
            i += 1
            while i < len(s) and (_is_ident_start(s[i]) or s[i].isdecimal()):
                i += 1
            tokens.append({"kind": "Ident", "name": s[start:i]})
        else:
            pair = s[i:i + 2]
            if pair in ("==", "<=", ">=", "!="):
                tokens.append({"kind": "Sym", "text": pair})
                i += 2
            elif char in "+-*/=<>() ,".replace(" ", ""):
                tokens.append({"kind": "Sym", "text": char})
                i += 1
            else:
                return {"ok": False, "error": f"unexpected character: {char} at {i}"}
    return {"ok": True, "value": tokens}
